  'тарталетка с творожным сыром': { kcal: 85, p: 3.5, f: 4.5, c: 7, per: 'шт', pieceG: 24 },
  'тарталетка с красной икрой и творожным сыром': { kcal: 100, p: 5.5, f: 6.5, c: 7, per: 'шт', pieceG: 30 },
