  'каша с молоком': { kcal: 100, p: 3.5, f: 4, c: 14 }, 'овсянка с молоком': { kcal: 100, p: 3.5, f: 4, c: 14 }, 'овсянка на молоке': { kcal: 100, p: 3.5, f: 4, c: 14 },
