/* Включена ли функция, которой принадлежит карточка (независимо от layout). */
/* ------------------------------------------------------------
   0.9.4 — конфигуратор Android-виджета (пункт 4 владельца).
   Пользователь сам выбирает галочками, что показывать на виджете:
   все карточки Главной + активность + календарь тренировок.
   «Стоимость» строки (units) честно отражает занимаемое место:
   показатель с полосой прогресса (вода, питание) занимает две строки,
   простая строка — одну. Бюджет фиксирован размером виджета, поэтому
   лишний элемент не добавляется молча, а объясняет, почему не влез.
------------------------------------------------------------- */
const WIDGET_ITEMS = [
  { id: 'water', label: 'Вода', icon: '💧', units: 2 },
  { id: 'food', label: 'Питание', icon: '🍽️', units: 2 },
  { id: 'steps', label: 'Шаги', icon: '👟', units: 1 },
  { id: 'activity', label: 'Активность', icon: '🏃', units: 1 },
  { id: 'weight', label: 'Вес', icon: '⚖️', units: 1 },
  { id: 'day-plan', label: 'План дня', icon: '📋', units: 1 },
  { id: 'day-mood', label: 'Самочувствие', icon: '🌗', units: 1 },
  { id: 'workout', label: 'Календарь тренировок', icon: '🗓️', units: 1 }
];

/* Бюджет строк по размеру виджета. Цифры взяты из реальной высоты ячеек
   Android: у 2×1 остаётся место на 3 строки, у 4×2 — на 5 (ровно то, что
   виджет показывал до 0.9.4: вода, питание, шаги), у 4×4 — на 8.
   Натив дополнительно обрезает список по числу слотов своей раскладки,
   поэтому уменьшение виджета пальцем не ломает вёрстку. */
const WIDGET_SIZES = [
  { id: 'small', label: 'Компактный 2×1', units: 3 },
  { id: 'medium', label: 'Средний 4×2', units: 5 },
  { id: 'large', label: 'Большой 4×4', units: 8 }
];

function widgetSizeById(id) {
  return WIDGET_SIZES.find((size) => size.id === id) || WIDGET_SIZES[1];
}

function widgetItemById(id) {
  return WIDGET_ITEMS.find((item) => item.id === id) || null;
}

function widgetUnitsUsed(items) {
  return (Array.isArray(items) ? items : []).reduce((sum, id) => {
    const item = widgetItemById(id);
    return sum + (item ? item.units : 0);
  }, 0);
}

/* Элемент виджета доступен, только если соответствующая карточка/функция
   включена в приложении. 0.9.4 (дефект владельца, п.5): «Питание» скрыто
   на Главной, а на виджете оставалось — теперь выключенный показатель
   не попадает на виджет и не предлагается в конфигураторе. */
function isWidgetItemAvailable(id) {
  if (TRACKER_CARDS.includes(id)) return isTrackerEnabled(id);
  if (id === 'day-plan' || id === 'day-mood') return isHomeCardShown(id);
  return true;
}

function isHomeCardFeatureEnabled(id) {
  const density = state.homeDensity || 'normal';
  if (density === 'minimal') {
    if (id === 'day-plan' || id === 'day-mood') return false;
    return true;
  }
  if (id === 'steps') return true;
  if (id === 'day-plan') return !!((state.dayChecklist && state.dayChecklist.enabled) || (state.gameMode && state.gameMode.enabled) || getTodayCourses().length > 0 || density === 'normal' || density === 'full');
  if (id === 'day-mood') return !!((state.dayChecklist && state.dayChecklist.enabled) || density === 'normal' || density === 'full');
  return true;
}

/* Карточка реально отображается: функция включена И в раскладке не скрыта. */
function isHomeCardShown(id, layout) {
  const l = layout || normalizeHomeLayoutValue(state.homeLayout);
  return l.visible[id] !== false && isHomeCardFeatureEnabled(id);
}

function syncHomeCardVisibility(id) {
  if (typeof document === 'undefined') return;
  const card = $(`#${id}-card`);
  if (card) card.hidden = !isHomeCardShown(id);
}

/* ------------------------------------------------------------
   0.8.25 (замечание владельца: «скрыл Питание — с Главной ушло,
   а в Плане дня осталось»): скрытая карточка = выключенная
   СУЩНОСТЬ во всём приложении, а не только на Главной.
   isTrackerEnabled — единый ответ на вопрос «ведём ли мы этот
   показатель»: используется Планом дня, заданиями игрового
   режима и разделами Статистики.
   Важно: сюда попадают только карточки-показатели (вода,
   питание, шаги, вес). «План дня» и «Самочувствие» — сами
   элементы Главной, их видимость к сущностям не относится.
------------------------------------------------------------ */
const TRACKER_CARDS = ['water', 'food', 'steps', 'weight'];

function isTrackerEnabled(id, layout) {
  if (!TRACKER_CARDS.includes(id)) return true;
  const l = layout || normalizeHomeLayoutValue(state.homeLayout);
  return l.visible[id] !== false;
}

const PROFILES_KEY = 'fitflow:profiles';
const LEGACY_STATE_KEY = 'fitflow:state';
let profilesState = { activeId: 'default', profiles: [{ id: 'default', name: 'Мой профиль' }] };

function profileStateKey(id = profilesState.activeId) {
  return id === 'default' ? LEGACY_STATE_KEY : `fitflow:state:${id}`;
}

function normalizeProfiles() {
  const source = profilesState || {};
  const ids = new Set();
  const profiles = (Array.isArray(source.profiles) ? source.profiles : [])
    .map((profile) => ({ id: String(profile.id || uid()), name: normalizeActivityName(profile.name) || '' }))
    .filter((profile) => profile.name && !ids.has(profile.id) && ids.add(profile.id))
    .slice(0, 10);
  if (!profiles.some((profile) => profile.id === 'default')) profiles.unshift({ id: 'default', name: 'Мой профиль' });
  const activeId = profiles.some((profile) => profile.id === source.activeId) ? source.activeId : profiles[0].id;
  profilesState = { activeId, profiles };
}

function loadProfiles() {
  try {
    const raw = localStorage.getItem(PROFILES_KEY);
    if (raw) profilesState = JSON.parse(raw);
  } catch (e) { }
  normalizeProfiles();
  try { localStorage.setItem(PROFILES_KEY, JSON.stringify(profilesState)); } catch (e) { }
}

function saveProfiles() {
  try { localStorage.setItem(PROFILES_KEY, JSON.stringify(profilesState)); } catch (e) { }
}

