const MORNING_MOTIVATION_ENDINGS = [
  '.',
  '. Пусть день начнётся спокойно.',
  '. Выберите то, что поддержит вас.',
  '. Спокойный темп тоже движение вперёд.',
  '. Пусть это будет по-доброму к себе.'
];


function getMorningMotivationMessage(theme, sequenceIndex = 0) {
  const messages = MORNING_MOTIVATION_MESSAGES[theme] || MORNING_MOTIVATION_MESSAGES.mixed;
  const index = Math.abs(Math.floor(Number(sequenceIndex) || 0));
  const base = messages[index % messages.length];
  const ending = MORNING_MOTIVATION_ENDINGS[Math.floor(index / messages.length) % MORNING_MOTIVATION_ENDINGS.length];
  return `${base}${ending}`;
}

function morningMotivationVariantsCount(theme) {
  const messages = MORNING_MOTIVATION_MESSAGES[theme] || MORNING_MOTIVATION_MESSAGES.mixed;
  return messages.length * MORNING_MOTIVATION_ENDINGS.length;
}

const ACTIVITY_TYPES = {
  walk: { label: 'Прогулка', emoji: '🚶' },
  cardio: { label: 'Кардио / бег', emoji: '🏃' },
  swim: { label: 'Плавание', emoji: '🏊' },
  bike: { label: 'Велосипед', emoji: '🚲' },
  strength: { label: 'Силовая', emoji: '🏋️' },
  stretch: { label: 'Растяжка', emoji: '🧘' },
  leisure: { label: 'Активный отдых', emoji: '⛸️' },
  other: { label: 'Другое', emoji: '💪' }
};

const state = {
  schemaVersion: STATE_SCHEMA_VERSION, // 0.5.0
  water: { date: todayKey(), total: 0, log: [], goal: DEFAULTS.water.goal },
  food: { date: todayKey(), items: [], goal: DEFAULTS.food.goal },
  favoriteMeals: [],
  dailyHistory: [],
  workouts: [],
  activityTemplates: [],
  reminders: { ...DEFAULTS.reminders },
  morningMotivation: { ...DEFAULTS.morningMotivation },
  activitySettings: { ...DEFAULTS.activitySettings },
  profileSettings: { ...DEFAULTS.profileSettings },
  mealReminders: { ...DEFAULTS.mealReminders },
  waterReminders: { ...DEFAULTS.waterReminders },
  dayChecklist: { ...DEFAULTS.dayChecklist },
  gameMode: { ...DEFAULTS.gameMode },
  sleepCheckin: { ...DEFAULTS.sleepCheckin, log: [] },
  dayMood: { ...DEFAULTS.dayMood },
  customMealTypes: [],
  theme: null,
  strengthSessions: [], // 0.8.4
  strengthTemplates: [], // 0.8.8
  strengthPlan: [] // 0.8.9
};

function isValidReminderTime(time) {
  if (typeof time !== 'string' || !/^\d{2}:\d{2}$/.test(time)) return false;
  const [hours, minutes] = time.split(':').map(Number);
  return hours >= 0 && hours <= 23 && minutes >= 0 && minutes <= 59;
}

function normalizeReminderSettings() {
  const reminders = state.reminders || {};
  state.reminders = {
    enabled: reminders.enabled === true,
    time: isValidReminderTime(reminders.time) ? reminders.time : DEFAULTS.reminders.time
  };
}

/* P13: вечерний пуш «Оцени день» (самочувствие) — собственный переключатель
   и время, по умолчанию выключен (не докучаем без явного согласия). */
function normalizeDayMoodReminder() {
  const r = state.dayMoodReminder || {};
  state.dayMoodReminder = {
    enabled: r.enabled === true,
    time: isValidReminderTime(r.time) ? r.time : DEFAULTS.dayMoodReminder.time
  };
}

function normalizeCustomMealTypes() {
  const ids = new Set();
  state.customMealTypes = (Array.isArray(state.customMealTypes) ? state.customMealTypes : [])
    .map((meal) => ({ id: String(meal.id || uid()), label: normalizeActivityName(meal.label) || '' }))
    .filter((meal) => meal.label && !ids.has(meal.id) && ids.add(meal.id))
    .slice(0, 20);
}

function getMealTypes() {
  return [...MEAL_REMINDER_TYPES, ...state.customMealTypes];
}

function normalizeMealReminders() {
  const source = state.mealReminders || {};
  // Версия 2 безопасно отключает старые повторяющиеся напоминания v0.1.24.
  // Пользователь заново выбирает только нужные приёмы пищи.
  const legacy = source.version !== 2;
  const map = new Map((legacy ? [] : (Array.isArray(source.meals) ? source.meals : [])).map((meal) => [meal.id, meal]));
  state.mealReminders = {
    version: 2,
    enabled: legacy ? false : source.enabled === true,
    meals: getMealTypes().map((type) => {
      const meal = map.get(type.id) || {};
      return { id: type.id, label: type.label, enabled: meal.enabled === true, time: isValidReminderTime(meal.time) ? meal.time : type.time };
    })
  };
}

function normalizeMorningMotivation() {
  const motivation = state.morningMotivation || {};
  const theme = MORNING_MOTIVATION_THEMES[motivation.theme] ? motivation.theme : DEFAULTS.morningMotivation.theme;
  const message = typeof motivation.message === 'string' && motivation.message.length > 0 && motivation.message.length <= 180
    ? motivation.message
    : getMorningMotivationMessage(theme, 0);
  state.morningMotivation = {
    enabled: motivation.enabled === true,
    time: isValidReminderTime(motivation.time) ? motivation.time : DEFAULTS.morningMotivation.time,
    theme,
    message
  };
}

function normalizeDayChecklist() {
  state.dayChecklist = { enabled: (state.dayChecklist || {}).enabled === true };
}

function normalizeGameMode() {
  state.gameMode = { enabled: (state.gameMode || {}).enabled === true };
}

/* ===== Чек-ин сна (идея пользователя 06.08.2026: утром — оценка сна,
   опционально «во сколько лёг/встал» и «что делал перед сном»; при
   отклонении от целевого режима более чем на 30 мин день помечается
   «режим сбит» — плавно показываем, что регулярность влияет на качество) */
const SLEEP_TAGS = [
  { id: 'phone', label: '📱 Экран' }, { id: 'sport', label: '🏋️ Спорт' },
  { id: 'coffee', label: '☕ Кофе/чай' }, { id: 'food', label: '🍽️ Поздняя еда' },
  { id: 'work', label: '💼 Работа' }, { id: 'book', label: '📖 Чтение' },
  { id: 'alcohol', label: '🍷 Алкоголь' }, { id: 'walk', label: '🚶 Прогулка' }
];
const SLEEP_TAG_IDS = new Set(SLEEP_TAGS.map((t) => t.id));
const SLEEP_SCHEDULE_TOLERANCE_MIN = 30;

function sleepTimeToMinutes(t) {
  const m = /^([01]?\d|2[0-3]):([0-5]\d)$/.exec(String(t || ''));
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

/* «Утро» чек-ина сна — настраиваемое окно [start, end). Если конец не позже
   начала (например, 10:00–02:00), окно считается переходящим через полночь.
   Равные границы = «окна нет» (false): иначе получилось бы «показывать всегда». */
function isSleepWindowNow(now, startStr, endStr) {
  const start = sleepTimeToMinutes(startStr);
  const end = sleepTimeToMinutes(endStr);
  if (start == null || end == null || start === end) return false;
  const d = (now instanceof Date) ? now : new Date(now);
  if (Number.isNaN(d.getTime())) return false;
  const m = d.getHours() * 60 + d.getMinutes();
  return start < end ? (m >= start && m < end) : (m >= start || m < end);
}

/* Длительность сна по «лёг/встал» с переходом через полночь.
   Менее 30 мин или более 16 ч — скорее ошибка ввода, чем сон: возвращаем null. */
function computeSleepDurationMin(bedTime, wakeTime) {
  const b = sleepTimeToMinutes(bedTime);
  const w = sleepTimeToMinutes(wakeTime);
  if (b == null || w == null) return null;
  let d = w - b;
  if (d <= 0) d += 1440;
  return (d >= 30 && d <= 16 * 60) ? d : null;
}

function circularMinutesDistance(a, b) {
  const d = Math.abs(a - b) % 1440;
  return Math.min(d, 1440 - d);
}

/* «В режиме»: и отбой, и подъём в пределах ±30 минут от целевых.
   null — данных недостаточно (что-то из времён не указано). */
function evaluateSleepOnSchedule(bedTime, wakeTime, targetBed, targetWake) {
  const b = sleepTimeToMinutes(bedTime);
  const w = sleepTimeToMinutes(wakeTime);
  const tb = sleepTimeToMinutes(targetBed);
  const tw = sleepTimeToMinutes(targetWake);
  if (b == null || w == null || tb == null || tw == null) return null;
  return circularMinutesDistance(b, tb) <= SLEEP_SCHEDULE_TOLERANCE_MIN
    && circularMinutesDistance(w, tw) <= SLEEP_SCHEDULE_TOLERANCE_MIN;
}

function normalizeSleepCheckin() {
  const sc = state.sleepCheckin || {};
  const validTime = (v, fallback) => (typeof v === 'string' && /^([01]?\d|2[0-3]):[0-5]\d$/.test(v) ? v : fallback);
  const log = (Array.isArray(sc.log) ? sc.log : [])
    .filter((e) => e && typeof e === 'object' && /^\d{4}-\d{2}-\d{2}$/.test(e.date))
    .map((e) => ({
      id: String(e.id || uid()),
      date: e.date,
      rating: (Number.isInteger(Number(e.rating)) && Number(e.rating) >= 1 && Number(e.rating) <= 5) ? Number(e.rating) : null,
      bedTime: validTime(e.bedTime, null),
      wakeTime: validTime(e.wakeTime, null),
      durationMin: (Number.isFinite(Number(e.durationMin)) && Number(e.durationMin) > 0 && Number(e.durationMin) <= 960) ? Math.round(Number(e.durationMin)) : null,
      tags: (Array.isArray(e.tags) ? e.tags : []).map((t) => String(t)).filter((t) => SLEEP_TAG_IDS.has(t)).slice(0, 6),
      onSchedule: e.onSchedule === true ? true : (e.onSchedule === false ? false : null),
      createdAt: Number(e.createdAt) || Date.now()
    }))
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(-400); // чуть больше года истории достаточно

  // 0.7.0 / 0.7.5: сохранение и синхронизация объективных данных сна (Health Connect)
  const rawHistory = sc.history && typeof sc.history === 'object' ? sc.history : {};
  const history = {};
  Object.keys(rawHistory).forEach((d) => {
    if (/^\d{4}-\d{2}-\d{2}$/.test(d) && rawHistory[d] && typeof rawHistory[d] === 'object') {
      const h = rawHistory[d];
      const dur = Number(h.durationMinutes || h.durationMin) || 0;
      history[d] = {
        date: d,
        durationMinutes: dur > 0 ? dur : (Number(h.durationMin) || 0),
        durationMin: dur > 0 ? dur : (Number(h.durationMin) || 0),
        bedTime: validTime(h.bedTime, null),
        wakeTime: validTime(h.wakeTime, null),
        rating: Number(h.rating) || 4,
        source: typeof h.source === 'string' ? h.source : 'Health Connect'
      };
    }
  });

  // Синхронизируем log в history
  log.forEach((entry) => {
    if (!history[entry.date]) {
      history[entry.date] = {
        date: entry.date,
        durationMinutes: entry.durationMin || 0,
        durationMin: entry.durationMin || 0,
        bedTime: entry.bedTime,
        wakeTime: entry.wakeTime,
        rating: entry.rating || 4,
        source: 'Чек-ин'
      };
    }
  });

  state.sleepCheckin = {
    enabled: sc.enabled === true,
    targetBed: validTime(sc.targetBed, DEFAULTS.sleepCheckin.targetBed),
    targetWake: validTime(sc.targetWake, DEFAULTS.sleepCheckin.targetWake),
    windowStart: validTime(sc.windowStart, DEFAULTS.sleepCheckin.windowStart),
    windowEnd: validTime(sc.windowEnd, DEFAULTS.sleepCheckin.windowEnd),
    log,
    history,
    skipped: (typeof sc.skipped === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(sc.skipped)) ? sc.skipped : null
  };
  // Равные границы окна бессмысленны («всегда»/«никогда» по логике) — откатываем на умолчание.
  if (state.sleepCheckin.windowStart === state.sleepCheckin.windowEnd) {
    state.sleepCheckin.windowStart = DEFAULTS.sleepCheckin.windowStart;
    state.sleepCheckin.windowEnd = DEFAULTS.sleepCheckin.windowEnd;
  }
}

function getTodaySleepEntry() {
  return ((state.sleepCheckin && state.sleepCheckin.log) || []).find((e) => e.date === todayKey()) || null;
}

/* Сводка по последним N дням для мотивационной строки в диалоге сна. */
function getSleepCheckinSummary(days = 7) {
  const cutoff = statsDateKey(days - 1);
  const entries = ((state.sleepCheckin && state.sleepCheckin.log) || []).filter((e) => e.date >= cutoff);
  if (!entries.length) return null;
  const durations = entries.map((e) => e.durationMin).filter((v) => Number.isFinite(v));
  const ratings = entries.map((e) => e.rating).filter((v) => Number.isInteger(v));
  const sched = entries.map((e) => e.onSchedule).filter((v) => v !== null);
  return {
    nights: entries.length,
    avgDurationMin: durations.length ? Math.round(durations.reduce((s, v) => s + v, 0) / durations.length) : null,
    avgRating: ratings.length ? Math.round((ratings.reduce((s, v) => s + v, 0) / ratings.length) * 10) / 10 : null,
    onScheduleCount: sched.filter(Boolean).length,
    scheduleTotal: sched.length
  };
}

function normalizeDayMood() {
  const mood = state.dayMood || {};
  const r = Number(mood.rating);
  const rating = (r >= 1 && r <= 5 && Number.isInteger(r)) ? r : null;
  const date = typeof mood.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(mood.date) ? mood.date : null;
  // Совместимость: до 0.2.7 оценка хранилась без даты и «зависала» в чек-листе
  // на все следующие дни. Такую старую оценку честно очищаем.
  state.dayMood = { date: rating ? date : null, rating: date ? rating : null };
}

function getTodayMood() {
  return (state.dayMood.date === todayKey() && state.dayMood.rating) ? state.dayMood.rating : null;
}

/* 0.8.28: рубильник онлайн-функций. Правило миграции — «офлайн по умолчанию»:
   в старых сохранениях объекта нет, и все флаги честно поднимаются как false.
   Молчаливого включения сети при обновлении приложения быть не должно. */
function normalizeOnlineFeatures() {
  const src = state.onlineFeatures || {};
  state.onlineFeatures = {
    master: src.master === true,
    cloudAi: src.cloudAi === true,
    barcodeLookup: src.barcodeLookup === true,
    modelDownload: src.modelDownload === true
  };
}

/* Единственный шлюз: разрешён ли выход в сеть для функции `feature`.
   Любой сетевой вызов в приложении обязан спросить сначала здесь. Общий
   рубильник имеет приоритет над частным флагом — выключил его и всё офлайн. */
function isOnlineAllowed(feature) {
  const o = state.onlineFeatures || {};
  if (!o.master) return false;
  return o[feature] === true;
}

function normalizeAiSettings() {
  const ai = state.aiSettings || {};
  state.aiSettings = {
    enabled: !!ai.enabled,
    mode: ['litert', 'expert', 'cloud'].includes(ai.mode) ? ai.mode : 'expert',
    modelPath: typeof ai.modelPath === 'string' ? ai.modelPath : '',
    modelName: typeof ai.modelName === 'string' ? ai.modelName : '',
    downloadUrl: typeof ai.downloadUrl === 'string' ? ai.downloadUrl : '',
    cloudProvider: Object.prototype.hasOwnProperty.call(CLOUD_PROVIDERS, ai.cloudProvider) ? ai.cloudProvider : 'gemini',
    cloudKey: typeof ai.cloudKey === 'string' ? ai.cloudKey : '',
    cloudModel: typeof ai.cloudModel === 'string' ? ai.cloudModel : '',
    cloudModels: Array.isArray(ai.cloudModels) ? ai.cloudModels.filter((m) => typeof m === 'string').slice(0, 8) : [],
    cloudBase: typeof ai.cloudBase === 'string' ? ai.cloudBase : ''
  };
}

function normalizeWaterReminders() {
  // 0.5.6 (решение владельца): настройки «пауза после записи» больше нет — «и так
  // уже слишком много переключателей». Правило стало автоматическим и фиксированным
  // (isWaterReminderSlotSkipped). Поле зазора паузы из старых сохранений осознанно не переносим.
  const source = state.waterReminders || {};
  state.waterReminders = {
    enabled: source.enabled === true,
    interval: [60, 90, 120].includes(Number(source.interval)) ? Number(source.interval) : DEFAULTS.waterReminders.interval,
    windowStart: isValidReminderTime(source.windowStart) ? source.windowStart : DEFAULTS.waterReminders.windowStart,
    windowEnd: isValidReminderTime(source.windowEnd) ? source.windowEnd : DEFAULTS.waterReminders.windowEnd
  };
}

function isValidWeightDate(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
}

function normalizeWeightHistory(history) {
  const entries = new Map();
  (Array.isArray(history) ? history : []).forEach((entry) => {
    const date = String(entry && entry.date || '');
    const weight = Number(String(entry && entry.weightKg || '').replace(',', '.'));
    if (!isValidWeightDate(date) || date > todayKey() || !Number.isFinite(weight) || weight < 25 || weight > 300) return;
    entries.set(date, { date, weightKg: Math.round(weight * 10) / 10, updatedAt: Number(entry.updatedAt) || 0 });
  });
  return [...entries.values()].sort((a, b) => a.date.localeCompare(b.date)).slice(-1000);
}

function clampOptionalInt(value, min, max) {
  const num = Number(String(value ?? '').replace(',', '.'));
  if (!Number.isFinite(num)) return null;
  const rounded = Math.round(num);
  return rounded >= min && rounded <= max ? rounded : null;
}

/* Необязательные сведения профиля (пол, возраст, рост, активность) —
   нужны только для точных норм воды/калорий и хранятся локально. */
function normalizeProfileSettings() {
  const profile = state.profileSettings || {};
  const weight = Number(String(profile.weightKg || '').replace(',', '.'));
  const sex = profile.sex === 'female' || profile.sex === 'male' ? profile.sex : null;
  const activityLevel = ['low', 'medium', 'high'].includes(profile.activityLevel) ? profile.activityLevel : null;
  state.profileSettings = {
    weightKg: Number.isFinite(weight) && weight >= 25 && weight <= 300 ? Math.round(weight * 10) / 10 : null,
    weightHistory: normalizeWeightHistory(profile.weightHistory),
    lastWeightReminderTs: Number(profile.lastWeightReminderTs) || 0,
    sex,
    ageYears: clampOptionalInt(profile.ageYears, 5, 120),
    heightCm: clampOptionalInt(profile.heightCm, 80, 250),
    activityLevel
  };
}

function checkWeighInReminder() {
  normalizeProfileSettings();
  const history = normalizeWeightHistory(state.profileSettings && state.profileSettings.weightHistory);
  if (!history || history.length === 0) return;
  const latest = history[history.length - 1];
  if (!latest || !latest.date) return;

  const now = Date.now();
  const lastWeightDateMs = new Date(latest.date).getTime();
  if (isNaN(lastWeightDateMs)) return;
  const daysSinceWeight = Math.floor((now - lastWeightDateMs) / (1000 * 60 * 60 * 24));

  // 0.7.0 (запрос владельца): разовое напоминание, если вес не вносился 35+ дней (1-1.5 месяца). При игноре — новый период отсчёта.
  if (daysSinceWeight >= 35) {
    const lastReminder = state.profileSettings.lastWeightReminderTs || 0;
    const daysSinceReminder = Math.floor((now - lastReminder) / (1000 * 60 * 60 * 24));
    if (daysSinceReminder >= 35) {
      state.profileSettings.lastWeightReminderTs = now;
      saveState();
      setTimeout(() => {
        toast(`⚖️ Пора обновить вес: последняя запись была ${daysSinceWeight} дн. назад. Свежий вес помогает точнее рассчитывать нормы калорий и воды.`);
      }, 2000);
    }
  }
}

/* Личные нормы на день:
   вода — ориентир 30 мл на кг веса с надбавкой за активность;
   калории — формула Миффлина — Сан Жеора (если заполнены пол, возраст, рост)
   с поправкой на активность; при неполных данных — честная упрощённая оценка. */
const PROFILE_ACTIVITY_FACTORS = {
  low: { kcal: 1.4, waterBonusMl: 0 },
  medium: { kcal: 1.55, waterBonusMl: 250 },
  high: { kcal: 1.7, waterBonusMl: 500 }
};

function roundToStep(value, step) { return Math.round(value / step) * step; }

function computeProfileNorms() {
  const profile = state.profileSettings || {};
  const weight = Number(profile.weightKg);
  if (!Number.isFinite(weight) || weight < 25 || weight > 300) return { ok: false, reason: 'weight' };
  const factors = PROFILE_ACTIVITY_FACTORS[profile.activityLevel] || PROFILE_ACTIVITY_FACTORS.medium;
  const waterMl = Math.min(5000, Math.max(1000, roundToStep(weight * 30 + factors.waterBonusMl, 50)));
  const exact = Boolean(profile.sex && profile.ageYears && profile.heightCm);
  let kcal;
  if (exact) {
    const bmr = 10 * weight + 6.25 * profile.heightCm - 5 * profile.ageYears + (profile.sex === 'male' ? 5 : -161);
    kcal = bmr * factors.kcal;
  } else {
    // Упрощённая оценка «на кг веса», пока антропометрия не заполнена.
    const perKg = profile.activityLevel === 'high' ? 33 : (profile.activityLevel === 'low' ? 25 : 29);
    kcal = weight * perKg;
  }
  kcal = Math.min(5000, Math.max(1000, roundToStep(kcal, 50)));
  return { ok: true, exact, waterMl, kcal };
}

/* Отрисовка блока «Профиль и цели» в Настройках: значения не затираем,
   пока пользователь печатает в поле (фокус). */
function renderProfileBasics() {
  const profile = state.profileSettings || {};
  const sexChoices = $('#profile-sex-choices');
  if (sexChoices) {
    $$('#profile-sex-choices button').forEach((btn) =>
      btn.classList.toggle('active', (profile.sex || null) === (btn.dataset.profileSex === 'none' ? null : btn.dataset.profileSex)));
  }
  const activityChoices = $('#profile-activity-choices');
  if (activityChoices) {
    $$('#profile-activity-choices button').forEach((btn) =>
      btn.classList.toggle('active', (profile.activityLevel || null) === (btn.dataset.profileActivity === 'none' ? null : btn.dataset.profileActivity)));
  }
  const ageInput = $('#profile-age-input');
  if (ageInput && document.activeElement !== ageInput) ageInput.value = profile.ageYears || '';
  const heightInput = $('#profile-height-input');
  if (heightInput && document.activeElement !== heightInput) heightInput.value = profile.heightCm || '';
  const termsStatus = $('#terms-status');
  if (termsStatus) {
    termsStatus.textContent = hasAcceptedTerms()
      ? 'Условия использования приняты. Если вы не согласны с условиями, пожалуйста, прекратите использование приложения и удалите его с устройства.'
      : 'Условия использования ещё не приняты — откройте их кнопкой выше и подтвердите согласие.';
  }
}

function saveProfileBasicField(field, rawValue) {
  if (field === 'ageYears') state.profileSettings.ageYears = clampOptionalInt(rawValue, 5, 120);
  else if (field === 'heightCm') state.profileSettings.heightCm = clampOptionalInt(rawValue, 80, 250);
  else return;
  saveState();
  renderProfileBasics();
}

function toggleProfileChoice(kind, value) {
  const key = kind === 'sex' ? 'sex' : 'activityLevel';
  // 0.4.15 (аудит А2/А3): «Не указан» — явный пункт; повторный тап больше НЕ снимает выбор.
  state.profileSettings[key] = (value === 'none' || value === '' || value == null) ? null : value;
  saveState();
  renderProfileBasics();
}

/* Диалог «Мои нормы на день»: показ расчёта и применение к целям */
let pendingProfileNorms = null;

function openNormsDialog() {
  const norms = computeProfileNorms();
  if (!norms.ok) {
    toast('Для расчёта нормы нужен текущий вес — добавьте его на карточке «Вес» на Главной.');
    return;
  }
  pendingProfileNorms = norms;
  const text = $('#norms-dialog-text');
  if (text) text.innerHTML = '💧 Вода: <b>' + fmt(norms.waterMl) + ' мл</b><br>🔥 Калории: <b>' + fmt(norms.kcal) + ' ккал</b>';
  const hint = $('#norms-dialog-hint');
  if (hint) {
    hint.textContent = norms.exact
      ? 'Расчёт по формуле Миффлина — Сан Жеора с учётом пола, возраста, роста, веса и активности. Это ориентир для поддержания веса, а не врачебная рекомендация.'
      : 'Пока использована упрощённая оценка по весу' + (state.profileSettings && state.profileSettings.activityLevel ? ' и активности' : '') + '. Заполните пол, возраст и рост в «Профиль и цели» — расчёт станет точнее (формула Миффлина — Сан Жеора).';
  }
  const dialog = $('#norms-dialog');
  if (dialog) dialog.hidden = false;
}

function closeNormsDialog() {
  const dialog = $('#norms-dialog');
  if (dialog) dialog.hidden = true;
  pendingProfileNorms = null;
}

function applyNormsDialog() {
  const norms = pendingProfileNorms;
  if (!norms) { closeNormsDialog(); return; }
  state.water.goal = norms.waterMl;
  state.food.goal = norms.kcal;
  saveState();
  closeNormsDialog();
  renderAll();
  toast('Нормы применены: вода ' + fmt(norms.waterMl) + ' мл, калории ' + fmt(norms.kcal) + ' ккал.');
}

function openMethodologyDialog() {
  const dialog = $('#methodology-dialog');
  if (dialog) dialog.hidden = false;
}

function closeMethodologyDialog() {
  const dialog = $('#methodology-dialog');
  if (dialog) dialog.hidden = true;
}

function openExplainDialog(metric) {
  const dialog = $('#explain-dialog');
  const content = $('#explain-dialog-content');
  const title = $('#explain-dialog-title');
  if (!dialog || !content) return;
  
  normalizeProfileSettings();
  const profile = state.profileSettings || {};
  const weight = profile.weightKg || 70;
  const height = profile.heightCm || 175;
  const age = profile.ageYears || 30;
  const sex = profile.sex || 'male';
  const activity = profile.activityLevel || 'medium';

  let html = '';
  if (metric === 'food') {
    if (title) title.textContent = 'Откуда цель по калориям?';
    const bmr = sex === 'female'
      ? Math.round(10 * weight + 6.25 * height - 5 * age - 161)
      : Math.round(10 * weight + 6.25 * height - 5 * age + 5);
    const mult = activity === 'high' ? 1.55 : (activity === 'medium' ? 1.375 : 1.2);
    const calculated = Math.round(bmr * mult);
    html = `
      <div style="margin-bottom:8px"><strong>Формула Миффлина — Сан Жеора:</strong></div>
      <div style="margin-bottom:4px">• Вес: ${weight} кг · Рост: ${height} см · Возраст: ${age} лет (${sex === 'female' ? 'жен.' : 'муж.'})</div>
      <div style="margin-bottom:4px">• Базовый обмен (BMR): ≈ <strong>${fmt(bmr)} ккал</strong> (на работу органов)</div>
      <div style="margin-bottom:4px">• Коэффициент активности: × ${mult} (${activity === 'high' ? 'высокая' : (activity === 'medium' ? 'умеренная' : 'низкая')})</div>
      <hr style="border:none; border-top:1px solid rgba(0,0,0,0.1); margin:8px 0;" />
      <div>• Расчётный ориентир: ≈ <strong>${fmt(calculated)} ккал/день</strong></div>
      <div style="margin-top:6px; color:#666; font-size:12px"><em>Ваша текущая цель: ${fmt(state.food.goal)} ккал. Можно скорректировать кнопками «Цель −/+».</em></div>
    `;
  } else if (metric === 'water') {
    if (title) title.textContent = 'Откуда норма воды?';
    const baseWater = Math.round(weight * 30);
    const actAdd = activity === 'high' ? 500 : (activity === 'medium' ? 250 : 0);
    const calculated = baseWater + actAdd;
    html = `
      <div style="margin-bottom:8px"><strong>Базовый физиологический расчёт:</strong></div>
      <div style="margin-bottom:4px">• Вес: ${weight} кг × 30 мл/кг = ≈ <strong>${fmt(baseWater)} мл</strong></div>
      <div style="margin-bottom:4px">• Надбавка за активность: + <strong>${actAdd} мл</strong></div>
      <hr style="border:none; border-top:1px solid rgba(0,0,0,0.1); margin:8px 0;" />
      <div>• Стартовый ориентир: ≈ <strong>${fmt(calculated)} мл/день</strong></div>
      <div style="margin-top:6px; color:#666; font-size:12px"><em>Ваша текущая цель: ${fmt(state.water.goal)} мл.</em></div>
    `;
  } else if (metric === 'steps') {
    if (title) title.textContent = 'Откуда цель шагов?';
    const steps = (state.healthSync && state.healthSync.lastSteps) || getPhoneSteps() || 0;
    const goal = (state.healthSync && state.healthSync.dailyGoal) || 8000;
    const kcal = (state.healthSync && state.healthSync.lastKcal) || Math.round(steps * 0.04);
    html = `
      <div style="margin-bottom:8px"><strong>Суточное движение (NEAT):</strong></div>
      <div style="margin-bottom:4px">• Рекомендованный ориентир: <strong>8 000 – 10 000 шагов</strong></div>
      <div style="margin-bottom:4px">• Энерготраты при ходьбе: ≈ <strong>0.04 ккал на 1 шаг</strong></div>
      <div style="margin-bottom:4px">• Сегодня пройдено: <strong>${fmt(steps)} шагов</strong> (≈ ${fmt(kcal)} ккал)</div>
      <hr style="border:none; border-top:1px solid rgba(0,0,0,0.1); margin:8px 0;" />
      <div style="color:#666; font-size:12px"><em>Ваша текущая цель: ${fmt(goal)} шагов/день. Можно изменить кнопками «Цель −/+» на карточке.</em></div>
    `;
  }
  content.innerHTML = html;
  dialog.hidden = false;
}

function closeExplainDialog() {
  const dialog = $('#explain-dialog');
  if (dialog) dialog.hidden = true;
}

function applyHomeDensityClass() {
  if (typeof document === 'undefined') return;
  const density = state.homeDensity || 'normal';
  const homeView = $('#home-view');
  if (homeView) homeView.dataset.density = density;
  if (document.body) document.body.dataset.density = density;
}

function setHomeDensity(density) {
  if (!['minimal', 'normal', 'full'].includes(density)) density = 'normal';
  state.homeDensity = density;

  const layout = normalizeHomeLayoutValue(state.homeLayout);
  if (density === 'minimal') {
    layout.visible['day-plan'] = false;
    layout.visible['day-mood'] = false;
    layout.visible['steps'] = true;
    layout.visible['water'] = true;
    layout.visible['food'] = true;
    layout.visible['weight'] = true;
    // Минимум — план свёрнут, быстрые записи скрыты
    try { localStorage.setItem('fitflow:dayplan-collapsed', '1'); } catch (e) {}
  } else if (density === 'normal') {
    layout.visible['day-plan'] = true;
    layout.visible['day-mood'] = true;
    layout.visible['steps'] = true;
    layout.visible['water'] = true;
    layout.visible['food'] = true;
    layout.visible['weight'] = true;
    // Обычный — план свёрнут в компактную строку, быстрые записи скрыты
    try { localStorage.setItem('fitflow:dayplan-collapsed', '1'); } catch (e) {}
  } else if (density === 'full') {
    layout.visible['day-plan'] = true;
    layout.visible['day-mood'] = true;
    layout.visible['steps'] = true;
    layout.visible['water'] = true;
    layout.visible['food'] = true;
    layout.visible['weight'] = true;
    // Полный — план развёрнут, быстрые записи видны
    try { localStorage.setItem('fitflow:dayplan-collapsed', '0'); } catch (e) {}
  }
  state.homeLayout = layout;
  saveState();
  applyHomeLayout();
  applyHomeDensityClass();
  renderDayPlan();
  renderDayMood();
  renderHomeDensity();
  renderHomeLayoutSettings();
  toast(density === 'minimal' ? 'Главная: «Минимум» (только шаги, вода, еда и вес)' : (density === 'normal' ? 'Главная: «Обычный» (+ план дня и самочувствие)' : 'Главная: «Полный» (все карточки и расширения)'));
}

function renderHomeDensity() {
  if (typeof document === 'undefined') return;
  const density = state.homeDensity || 'normal';
  applyHomeDensityClass();
  $$('#home-density-segmented button').forEach((btn) => {
    btn.classList.toggle('active', btn.dataset.density === density);
  });
  const hint = $('#home-density-hint');
  if (hint) {
    if (density === 'minimal') hint.textContent = 'Минимум: только шаги, вода, еда и вес (максимально чистый фокус-экран).';
    else if (density === 'normal') hint.textContent = 'Обычный: шаги, вода, еда, вес, компактный план дня и самочувствие.';
    else hint.textContent = 'Полный: все карточки, развёрнутый план с курсами, медали и быстрые записи на Главной.';
  }
}

function normalizeHomeLayoutValue(source) {
  const layout = source && typeof source === 'object' ? source : {};
  const knownIds = HOME_CARDS.map((card) => card.id);
  const seen = new Set();
  // 0.3.11: «Чек-лист дня» и «Задания дня» объединены в «План дня» —
  // старые id из сохранённого порядка переводим на новую карточку.
  const LEGACY_CARD_ALIASES = { 'day-checklist': 'day-plan', 'game-tasks': 'day-plan' };
  const order = (Array.isArray(layout.order) ? layout.order : [])
    .map((id) => LEGACY_CARD_ALIASES[String(id)] || String(id))
    .filter((id) => knownIds.includes(id) && !seen.has(id) && seen.add(id));
  // Карточки, которых нет в сохранённом порядке (например, новые после обновления),
  // ставим в НАЧАЛО в порядке HOME_CARDS — так у текущих пользователей экран
  // не перестраивается неожиданно: новые карточки оказываются там, где были раньше.
  const missing = knownIds.filter((id) => !seen.has(id));
  if (missing.length) order.unshift(...missing);

  const rawVisible = layout.visible && typeof layout.visible === 'object' ? layout.visible : {};
  const visible = Object.fromEntries(knownIds.map((id) => {
    // Обе старые карточки были скрыты → скрыта и объединённая; если скрыта была
    // только одна, «План дня» остаётся (вторая секция у пользователя была видна).
    if (id === 'day-plan' && rawVisible['day-plan'] === undefined
      && rawVisible['day-checklist'] === false && rawVisible['game-tasks'] === false) return [id, false];
    return [id, rawVisible[id] !== false];
  }));
  if (!Object.values(visible).some(Boolean)) visible[order[0]] = true;
  return { order, visible };
}

function normalizeHomeLayout() {
  state.homeLayout = normalizeHomeLayoutValue(state.homeLayout);
}

/* 0.9.4: раскладка Android-виджета. Правила миграции честные:
   у кого настройки ещё нет — виджет остаётся ровно таким, каким был
   до обновления (вода, питание, шаги), ничего не пропадает и не появляется.
   Порядок элементов = порядок пользователя; лишнее по бюджету обрезается,
   чтобы сохранённая раскладка не могла «переполнить» виджет. */
function normalizeWidgetLayoutValue(source) {
  const raw = source && typeof source === 'object' ? source : {};
  const size = widgetSizeById(String(raw.size || '')).id;
  const budget = widgetSizeById(size).units;
  const seen = new Set();
  const picked = [];
  let used = 0;
  (Array.isArray(raw.items) ? raw.items : ['water', 'food', 'steps'])
    .map((id) => String(id))
    .forEach((id) => {
      const item = widgetItemById(id);
      if (!item || seen.has(id)) return;
      if (used + item.units > budget) return;
      seen.add(id);
      picked.push(id);
      used += item.units;
    });
  return { size, items: picked };
}

function normalizeWidgetLayout() {
  state.widgetLayout = normalizeWidgetLayoutValue(state.widgetLayout);
}

/* Что реально уедет в натив: выбранное пользователем минус то, что
   выключено в приложении (скрытая карточка = выключенный показатель). */
function activeWidgetItems() {
  return normalizeWidgetLayoutValue(state.widgetLayout).items.filter(isWidgetItemAvailable);
}

function normalizeActivitySettings() {
  const settings = state.activitySettings || {};
  state.activitySettings = {
    weeklyGoalMinutes: Math.min(1440, Math.max(30, Math.round(Number(settings.weeklyGoalMinutes) || DEFAULTS.activitySettings.weeklyGoalMinutes)))
  };
}

function normalizeOptionalNote(value) {
  const note = String(value || '').trim().replace(/\s+/g, ' ');
  return note.length > 0 && note.length <= 120 ? note : null;
}

function normalizeActivityName(value) {
  const name = String(value || '').trim().replace(/\s+/g, ' ');
  return name.length >= 2 && name.length <= 60 ? name : null;
}

function normalizeFavoriteMeal(meal) {
  if (!meal || typeof meal !== 'object') return null;
  const name = normalizeActivityName(meal.name);
  const kcal = Math.round(Number(meal.kcal));
  if (!name || !Number.isFinite(kcal) || kcal < 1 || kcal > 5000) return null;
  const p = Number.isFinite(Number(meal.p)) ? Math.round(Number(meal.p) * 10) / 10 : null;
  const f = Number.isFinite(Number(meal.f)) ? Math.round(Number(meal.f) * 10) / 10 : null;
  const c = Number.isFinite(Number(meal.c)) ? Math.round(Number(meal.c) * 10) / 10 : null;
  return { id: String(meal.id || uid()), name, kcal, p, f, c };
}

function normalizeFavoriteMeals() {
  const ids = new Set();
  state.favoriteMeals = (Array.isArray(state.favoriteMeals) ? state.favoriteMeals : [])
    .map(normalizeFavoriteMeal)
    .filter((meal) => meal && !ids.has(meal.id) && ids.add(meal.id))
    .slice(0, 30);
}

function normalizeCustomFoods() {
  const names = new Set();
  state.customFoods = (Array.isArray(state.customFoods) ? state.customFoods : [])
    .map((item) => {
      if (!item || typeof item.name !== 'string') return null;
      const name = item.name.trim().toLowerCase().replace(/\s+/g, ' ');
      const kcal = Math.round(Number(item.kcal));
      if (!name || name.length < 2 || !Number.isFinite(kcal) || kcal < 1 || kcal > 900) return null;
      const num = (v) => { const n = Number(v); return (Number.isFinite(n) && n >= 0 && n < 1000) ? Math.round(n * 10) / 10 : null; };
      const pieceG = Math.round(Number(item.pieceG));
      return {
        id: String(item.id || uid()), name, kcal,
        p: num(item.p), f: num(item.f), c: num(item.c),
        pieceG: (Number.isFinite(pieceG) && pieceG > 0 && pieceG <= 2000) ? pieceG : null
      };
    })
    .filter((item) => item && !names.has(item.name) && names.add(item.name))
    .slice(0, 200);
}

/* Добавление/замена своего продукта. Совпадение по названию = замена
   (пользователь обновил данные с новой упаковки). */
function addCustomFood(input) {
  if (!Array.isArray(state.customFoods)) state.customFoods = [];
  const name = String((input && input.name) || '').trim().toLowerCase().replace(/\s+/g, ' ');
  const kcal = Math.round(Number(input && input.kcal));
  if (!name || name.length < 2) return { ok: false, error: 'name' };
  if (!Number.isFinite(kcal) || kcal < 1 || kcal > 900) return { ok: false, error: 'kcal' };
  const num = (v) => { const n = Number(v); return (Number.isFinite(n) && n >= 0 && n < 1000) ? Math.round(n * 10) / 10 : null; };
  const pieceG = Math.round(Number(input && input.pieceG));
  state.customFoods = state.customFoods.filter((item) => item.name !== name);
  const item = {
    id: uid(), name, kcal,
    p: num(input.p), f: num(input.f), c: num(input.c),
    pieceG: (Number.isFinite(pieceG) && pieceG > 0 && pieceG <= 2000) ? pieceG : null
  };
  state.customFoods.push(item);
  normalizeCustomFoods();
  saveState();
  return { ok: true, item };
}

function removeCustomFood(id) {
  const before = (Array.isArray(state.customFoods) ? state.customFoods : []).length;
  state.customFoods = (Array.isArray(state.customFoods) ? state.customFoods : []).filter((item) => item.id !== id);
  if (state.customFoods.length !== before) saveState();
  return state.customFoods.length !== before;
}

/* ============================================================
   💊 «Мой курс» (0.3.30, решение пользователя по POSTPONED P8):
   приёмы по времени — витамины, спортивные добавки, назначения.
   Сделано МАЛЫМ, поверх ГОТОВЫХ механик (принцип не-нагромождения):
   строки живут в карточке «План дня» (ручные отметки — приём нельзя
   вывести из других записей, только подтверждение пользователя),
   напоминания едут тем же системным планировщиком, что вода и приёмы
   пищи. Схем приёма здесь нет и не будет: FitFlow не врач, расписание
   задаёт сам пользователь по инструкции/назначению специалиста.
============================================================ */
const COURSE_REMINDER_CHANNEL = 'fitflow_course_reminders_v1';
const COURSE_REMINDER_DAYS = 14;          // окно планирования, как у приёмов пищи
const COURSE_REMINDER_ID_BASE = 60000;    // диапазон id 60000–61999 (вода 75000+)
const MAX_COURSES = 10;
const MAX_COURSE_DOSES = 4;
const COURSE_DOSE_DEFAULT_TIMES = ['08:00', '14:00', '20:00', '22:00'];

function isValidCourseTime(t) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(t || '').trim()); }

function normalizeCourseTimes(times) {
  const unique = new Set();
  return (Array.isArray(times) ? times : [])
    .map((t) => String(t || '').trim())
    .filter((t) => isValidCourseTime(t) && !unique.has(t) && unique.add(t))
    .sort()
    .slice(0, MAX_COURSE_DOSES);
}

/* Нормализация одного курса. checkLog: дата → индексы отмеченных приёмов;
   старше 90 дней выкидываем — счётчик дня выводится из startDate, а не из
   отметок, поэтому бэкап не пухнет историей. */
function normalizeCourse(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const name = String(raw.name || '').trim().replace(/\s+/g, ' ').slice(0, 60);
  if (name.length < 2) return null;
  const times = normalizeCourseTimes(raw.times);
  if (!times.length) return null;
  const startDate = /^\d{4}-\d{2}-\d{2}$/.test(String(raw.startDate || '')) ? String(raw.startDate) : null;
  if (!startDate) return null;
  const daysNum = Math.round(Number(raw.daysTotal));
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - 90);
  const cutoffKey = courseDateKey(cutoff);
  const checkLog = {};
  if (raw.checkLog && typeof raw.checkLog === 'object') {
    Object.keys(raw.checkLog).forEach((date) => {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || date < cutoffKey) return;
      const marks = (Array.isArray(raw.checkLog[date]) ? raw.checkLog[date] : [])
        .map((n) => Math.round(Number(n)))
        .filter((n, i, arr) => Number.isInteger(n) && n >= 0 && n < times.length && arr.indexOf(n) === i)
        .sort((a, b) => a - b);
      if (marks.length) checkLog[date] = marks;
    });
  }
  return {
    id: String(raw.id || uid()),
    name, times, startDate,
    daysTotal: (Number.isFinite(daysNum) && daysNum > 0 && daysNum <= 365) ? daysNum : 0, // 0 = «пока не остановлю»
    remind: raw.remind !== false,
    checkLog
  };
}

function normalizeCourses() {
  const ids = new Set();
  state.myCourses = (Array.isArray(state.myCourses) ? state.myCourses : [])
    .map(normalizeCourse)
    .filter((course) => course && !ids.has(course.id) && ids.add(course.id))
    .slice(0, MAX_COURSES);
}

function courseDateKey(date) {
  const pad = (v) => String(v).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function getCourse(id) {
  return (Array.isArray(state.myCourses) ? state.myCourses : []).find((c) => c.id === id) || null;
}

function addCourse(input) {
  if (!Array.isArray(state.myCourses)) state.myCourses = [];
  if (state.myCourses.length >= MAX_COURSES) return { ok: false, error: 'limit' };
  const name = String((input && input.name) || '').trim();
  if (name.length < 2) return { ok: false, error: 'name' };
  if (!normalizeCourseTimes(input && input.times).length) return { ok: false, error: 'times' };
  const candidate = normalizeCourse({
    id: uid(), name, times: input.times,
    daysTotal: input.daysTotal, startDate: input.startDate || todayKey(),
    remind: input.remind !== false, checkLog: {}
  });
  if (!candidate) return { ok: false, error: 'times' };
  state.myCourses.push(candidate);
  saveState();
  return { ok: true, item: candidate };
}

function updateCourse(id, patch) {
  const list = Array.isArray(state.myCourses) ? state.myCourses : [];
  const idx = list.findIndex((c) => c.id === id);
  if (idx === -1) return { ok: false, error: 'not-found' };
  const name = String((patch && patch.name) || '').trim();
  if (name.length < 2) return { ok: false, error: 'name' };
  if (!normalizeCourseTimes(patch && patch.times).length) return { ok: false, error: 'times' };
  const prev = list[idx];
  const normalized = normalizeCourse({
    ...prev, ...patch, name,
    id: prev.id, startDate: prev.startDate, checkLog: prev.checkLog
  });
  if (!normalized) return { ok: false, error: 'times' };
  state.myCourses[idx] = normalized;
  saveState();
  return { ok: true, item: normalized };
}

function removeCourse(id) {
  const before = (Array.isArray(state.myCourses) ? state.myCourses : []).length;
  state.myCourses = (Array.isArray(state.myCourses) ? state.myCourses : []).filter((c) => c.id !== id);
  if (state.myCourses.length !== before) saveState();
  return state.myCourses.length !== before;
}

function courseDayNumber(course, dateKey = todayKey()) {
  if (!course || !course.startDate) return null;
  const start = new Date(course.startDate + 'T00:00:00');
  const day = new Date(dateKey + 'T00:00:00');
  if (isNaN(start.getTime()) || isNaN(day.getTime())) return null;
  return Math.floor((day - start) / 86400000) + 1;
}

function isCourseActiveOn(course, dateKey = todayKey()) {
  const day = courseDayNumber(course, dateKey);
  if (day == null || day < 1) return false;
  return !course.daysTotal || day <= course.daysTotal;
}

function getTodayCourses(dateKey = todayKey()) {
  return (Array.isArray(state.myCourses) ? state.myCourses : []).filter((c) => isCourseActiveOn(c, dateKey));
}

/* «день 12 из 30» / «день 12» — текст счётчика курса. */
function courseDayLabel(course, dateKey = todayKey()) {
  const day = courseDayNumber(course, dateKey);
  if (day == null || day < 1) return '';
  return course.daysTotal ? `день ${day} из ${course.daysTotal}` : `день ${day}`;
}

function courseEndDateKey(course) {
  if (!course || !course.daysTotal) return null;
  const end = new Date(course.startDate + 'T00:00:00');
  end.setDate(end.getDate() + course.daysTotal - 1);
  return courseDateKey(end);
}

function fmtCourseDate(dateKey) {
  const parts = String(dateKey || '').split('-');
  return parts.length === 3 ? `${parts[2]}.${parts[1]}.${parts[0]}` : String(dateKey || '');
}

/* Статус курса для списка в Настройках: «день 12 из 30», «начнётся 10.08.2026»,
   «завершён 30.08.2026». */
function courseStatusLabel(course, dateKey = todayKey()) {
  const day = courseDayNumber(course, dateKey);
  if (day == null) return '';
  if (day < 1) return 'начнётся ' + fmtCourseDate(course.startDate);
  if (course.daysTotal && day > course.daysTotal) return 'завершён ' + fmtCourseDate(courseEndDateKey(course));
  return courseDayLabel(course, dateKey);
}

function courseDosesForDate(course, dateKey = todayKey()) {
  const marks = new Set((course && course.checkLog && course.checkLog[dateKey]) || []);
  return (course ? course.times : []).map((time, index) => ({ index, time, done: marks.has(index) }));
}

function toggleCourseDose(courseId, doseIndex, dateKey = todayKey()) {
  const course = getCourse(courseId);
  if (!course) return false;
  const idx = Math.round(Number(doseIndex));
  if (!Number.isInteger(idx) || idx < 0 || idx >= course.times.length) return false;
  if (!course.checkLog || typeof course.checkLog !== 'object') course.checkLog = {};
  const marks = new Set(Array.isArray(course.checkLog[dateKey]) ? course.checkLog[dateKey] : []);
  if (marks.has(idx)) marks.delete(idx); else marks.add(idx);
  const list = [...marks].sort((a, b) => a - b);
  if (list.length) course.checkLog[dateKey] = list; else delete course.checkLog[dateKey];
  saveState();
  return true;
}

/* Строки курсов в карточке «План дня»: ручные отметки приёмов сегодня. */
function buildCoursesPlanHtml(dateKey = todayKey()) {
  const courses = getTodayCourses(dateKey);
  if (!courses.length) return '';
  const mark = (ok) => ok ? '<span class="checklist-icon done">✓</span>' : '<span class="checklist-icon pending">○</span>';
  return '<div class="checklist-items course-items">' + courses.map((course) => {
    const doses = courseDosesForDate(course, dateKey);
    const doneCount = doses.filter((d) => d.done).length;
    const chips = doses.map((d) =>
      `<button type="button" class="course-dose-chip${d.done ? ' done' : ''}" data-course-dose="${course.id}:${d.index}">${d.done ? '✓ ' : ''}${d.time}</button>`
    ).join('');
    return `<div class="course-plan-row">
      <div class="course-plan-head">${mark(doneCount === doses.length)}<span class="course-plan-name">💊 ${escapeHtml(course.name)} <small class="course-day-label">${courseDayLabel(course, dateKey)}</small></span><span class="game-tasks-note">${doneCount} из ${doses.length}</span></div>
      <div class="course-dose-chips">${chips}</div>
    </div>`;
  }).join('') + '</div>';
}

/* ---- Напоминания о курсе: тот же механизм, что вода/питание ---- */
function courseReminderId(coursePos, dayIdx, doseIdx) {
  return COURSE_REMINDER_ID_BASE + coursePos * 200 + dayIdx * 10 + doseIdx;
}

function courseReminderAllIds() {
  const ids = [];
  for (let pos = 0; pos < MAX_COURSES; pos++) {
    for (let d = 0; d < COURSE_REMINDER_DAYS; d++) {
      for (let k = 0; k < MAX_COURSE_DOSES; k++) ids.push(courseReminderId(pos, d, k));
    }
  }
  return ids;
}

async function ensureCourseReminderChannel(localNotifications) {
  if (typeof localNotifications.createChannel !== 'function') return;
  await localNotifications.createChannel({
    id: COURSE_REMINDER_CHANNEL,
    name: 'FitFlow: мой курс',
    description: 'Напоминания о приёмах по расписанию курса',
    importance: 3,
    visibility: 1,
    sound: 'default',
    vibrates: false
  });
}

async function cancelCourseReminders(localNotifications = getLocalNotifications()) {
  if (!localNotifications) return;
  try { await localNotifications.cancel({ notifications: courseReminderAllIds().map((id) => ({ id })) }); } catch (e) { }
}

async function scheduleCourseReminders({ requestPermission = true } = {}) {
  const localNotifications = getLocalNotifications();
  if (!localNotifications) return { ok: false, message: 'Напоминания о курсе работают только в Android-приложении.' };
  let allowed = false;
  if (requestPermission) allowed = await ensureNotificationPermission(localNotifications);
  else { try { allowed = (await localNotifications.checkPermissions()).display === 'granted'; } catch (e) { } }
  if (!allowed) return { ok: false, message: 'Разрешите уведомления Android, чтобы приходили напоминания о курсе.' };
  try {
    await ensureCourseReminderChannel(localNotifications);
    await cancelCourseReminders(localNotifications);
    const notifications = [];
    (Array.isArray(state.myCourses) ? state.myCourses : []).forEach((course, pos) => {
      if (!course.remind) return;
      course.times.forEach((time, doseIdx) => {
        const firstAt = nextReminderDate(time);
        for (let dayIdx = 0; dayIdx < COURSE_REMINDER_DAYS; dayIdx++) {
          const at = new Date(firstAt.getTime());
          at.setDate(at.getDate() + dayIdx);
          const date = courseDateKey(at);
          if (!isCourseActiveOn(course, date)) continue;
          // Сегодняшний приём уже отмечен — не тревожим (0.3.30).
          if (date === todayKey() && (((course.checkLog || {})[date]) || []).includes(doseIdx)) continue;
          const day = courseDayNumber(course, date);
          notifications.push({
            id: courseReminderId(pos, dayIdx, doseIdx),
            title: `💊 ${course.name} · ${time}`,
            body: course.daysTotal
              ? `Приём ${doseIdx + 1} из ${course.times.length} — день ${day} из ${course.daysTotal}. Отметьте в FitFlow.`
              : `Приём ${doseIdx + 1} из ${course.times.length} — день ${day}. Отметьте в FitFlow.`,
            schedule: { at, allowWhileIdle: true },
            channelId: COURSE_REMINDER_CHANNEL,
            smallIcon: 'ic_stat_icon', iconColor: '#FF9E3D', autoCancel: true,
            actionTypeId: COURSE_DOSE_ACTION_TYPE,
            /* 0.8.25: в extra кладём КОНКРЕТНЫЙ приём и его дату — кнопка
               «✓ Принял» отмечает именно его, даже если уведомление открыли
               позже или их накопилось несколько. */
            extra: {
              source: 'fitflow-course-reminder',
              courseId: course.id,
              notifSettings: 'course',
              doseIndex: doseIdx,
              dateKey: date
            }
          });
        }
      });
    });
    if (notifications.length) await localNotifications.schedule({ notifications });
    return { ok: true };
  } catch (e) {
    console.warn('Не удалось запланировать напоминания о курсе:', e);
    return { ok: false, message: 'Не удалось включить напоминания о курсе. Проверьте разрешения Android.' };
  }
}

async function refreshCourseRemindersOnLaunch() {
  if (!getLocalNotifications()) return;
  const hasActive = (Array.isArray(state.myCourses) ? state.myCourses : []).some((c) => c.remind && isCourseActiveOn(c));
  if (!hasActive) return;
  await scheduleCourseReminders({ requestPermission: false });
}

/* ---- UI «Моего курса» ---- */
let pendingCourseDeleteId = null;
let pendingCourseDoseCount = 2;
let editingCourseId = null;

function renderCoursesSettings() { renderCourseList(); }

function renderCourseList() {
  const list = $('#course-list');
  if (!list) return;
  const empty = $('#course-empty');
  const courses = Array.isArray(state.myCourses) ? state.myCourses : [];
  if (empty) empty.hidden = courses.length > 0;
  list.innerHTML = courses.map((course) =>
    '<div class="custom-food-row"><span><b>' + escapeHtml(course.name) + '</b>'
    + '<small>' + escapeHtml(course.times.join(', ')) + ' · ' + courseStatusLabel(course)
    + (course.remind ? ' · 🔔' : ' · без напоминаний') + '</small></span>'
    + '<span class="custom-food-actions">'
    + '<button class="icon-btn course-edit" type="button" data-id="' + course.id + '" aria-label="Изменить курс">✏️</button>'
    + '<button class="icon-btn course-del" type="button" data-id="' + course.id + '" aria-label="Удалить курс">✕</button></span></div>'
  ).join('');
  list.querySelectorAll('.course-edit').forEach((btn) =>
    btn.addEventListener('click', () => openCourseDialog(btn.dataset.id)));
  list.querySelectorAll('.course-del').forEach((btn) =>
    btn.addEventListener('click', () => askDeleteCourse(btn.dataset.id)));
}

function renderCourseTimeInputs(count, values = []) {
  const box = $('#course-times');
  if (!box) return;
  box.innerHTML = Array.from({ length: count }, (_, i) =>
    `<label>Приём ${i + 1}<input class="dialog-text-input" type="time" id="course-time-${i}" value="${values[i] || COURSE_DOSE_DEFAULT_TIMES[i]}"></label>`
  ).join('');
}

function syncCourseDoseButtons(count) {
  $$('#course-doses [data-doses]').forEach((btn) =>
    btn.classList.toggle('active', Number(btn.dataset.doses) === count));
}

function currentCourseTimeValues() {
  return $$('#course-times input[type="time"]').map((el) => el.value).filter(Boolean);
}

function setCourseDoseCount(n) {
  const count = Math.min(MAX_COURSE_DOSES, Math.max(1, Math.round(Number(n)) || 1));
  const values = currentCourseTimeValues();
  pendingCourseDoseCount = count;
  syncCourseDoseButtons(count);
  renderCourseTimeInputs(count, values);
}

function openCourseDialog(id) {
  const dialog = $('#course-dialog');
  if (!dialog) return;
  editingCourseId = id || null;
  const course = id ? getCourse(id) : null;
  const title = $('#course-dialog-title');
  if (title) title.textContent = course ? 'Правка курса' : 'Новый курс';
  if ($('#course-name')) $('#course-name').value = course ? course.name : '';
  if ($('#course-days')) $('#course-days').value = course ? course.daysTotal : 30;
  if ($('#course-remind')) $('#course-remind').checked = course ? course.remind : true;
  const count = course ? course.times.length : 2;
  pendingCourseDoseCount = count;
  syncCourseDoseButtons(count);
  renderCourseTimeInputs(count, course ? course.times : COURSE_DOSE_DEFAULT_TIMES);
  dialog.hidden = false;
  const nameInput = $('#course-name');
  if (nameInput) nameInput.focus();
}

function closeCourseDialog() {
  editingCourseId = null;
  const dialog = $('#course-dialog');
  if (dialog) dialog.hidden = true;
}

function saveCourseFromDialog() {
  const name = ($('#course-name') || {}).value || '';
  const daysRaw = Number(($('#course-days') || {}).value);
  const input = {
    name,
    times: currentCourseTimeValues(),
    daysTotal: (Number.isFinite(daysRaw) && daysRaw > 0) ? daysRaw : 0,
    remind: !!($('#course-remind') || {}).checked
  };
  const res = editingCourseId ? updateCourse(editingCourseId, input) : addCourse(input);
  if (!res.ok) {
    toast(res.error === 'name'
      ? 'Название — от 2 символов'
      : res.error === 'limit'
        ? 'Максимум ' + MAX_COURSES + ' курсов — принцип малого приложения'
        : 'Проверьте время приёмов: формат ЧЧ:ММ, без повторов');
    return;
  }
  const wasEditing = !!editingCourseId;
  closeCourseDialog();
  renderCoursesSettings();
  renderDayPlan();
  if (input.remind) {
    scheduleCourseReminders().then((r) => {
      if (!r.ok) toast(r.message || 'Курс сохранён, но напоминания не включились — отметки работают');
    });
  } else {
    scheduleCourseReminders({ requestPermission: false });
  }
  toast(wasEditing ? '💊 Курс обновлён' : '💊 Курс добавлен — отметки появились в «Плане дня»');
}

function askDeleteCourse(id) {
  const course = getCourse(id);
  if (!course) return;
  pendingCourseDeleteId = id;
  const label = $('#course-del-name');
  if (label) label.textContent = '«' + course.name + '» (' + course.times.join(', ') + ')';
  const dialog = $('#course-del-dialog');
  if (dialog) dialog.hidden = false;
}

function confirmDeleteCourse() {
  if (pendingCourseDeleteId) {
    removeCourse(pendingCourseDeleteId);
    pendingCourseDeleteId = null;
    scheduleCourseReminders({ requestPermission: false });
    toast('💊 Курс удалён');
    renderCoursesSettings();
    renderDayPlan();
  }
  const dialog = $('#course-del-dialog');
  if (dialog) dialog.hidden = true;
}

function cancelDeleteCourse() {
  pendingCourseDeleteId = null;
  const dialog = $('#course-del-dialog');
  if (dialog) dialog.hidden = true;
}

/* 0.4.9 (ПОЛЕВОЙ БАГ-противоречие №1 «правдивость расчётов»: «за вчерашний день
   нет информации вообще»): объект дня здесь СОБИРАЛИ, но в карту byDate НИКОГДА
   НЕ КЛАЛИ — каждая нормализация молча обнуляла всю историю (recordDailySummary
   зовёт её при каждом saveState): день жил, пока был «сегодня», и стирался на
   переходе через полночь. Лечение Инженерное: операция вынесена в ЧИСТУЮ
   функцию с node-прогоном — регресс «собрать, но не сохранить» теперь ловится
   тестом, а не владельцем продукта через неделю. Дедуп по дате: поздняя запись
   побеждает (соответствует recordDailySummary — он обновляет тот же день). */
function normalizeDailyHistoryList(list) {
  const byDate = new Map();
  (Array.isArray(list) ? list : []).forEach((day) => {
    if (!day || !/^\d{4}-\d{2}-\d{2}$/.test(day.date)) return;
    const normalized = {
      date: day.date,
      waterTotal: Math.max(0, Math.round(Number(day.waterTotal) || 0)),
      waterGoal: Math.max(500, Math.round(Number(day.waterGoal) || DEFAULTS.water.goal)),
      foodTotal: Math.max(0, Math.round(Number(day.foodTotal) || 0)),
      foodGoal: Math.max(800, Math.round(Number(day.foodGoal) || DEFAULTS.food.goal)),
      foodP: Math.round((Number(day.foodP) || 0) * 10) / 10,
      foodF: Math.round((Number(day.foodF) || 0) * 10) / 10,
      foodC: Math.round((Number(day.foodC) || 0) * 10) / 10,
      activityMinutes: Math.max(0, Math.round(Number(day.activityMinutes) || 0)),
      mood: (function(m){ const v = Number(m); return (v >= 1 && v <= 5 && Number.isInteger(v)) ? v : undefined; })(day.mood)
    };
    // 0.8.22 (P24): сохраняем компактные позиции еды дня.
    if (Array.isArray(day.items) && day.items.length) normalized.items = compactFoodItemsForHistory(day.items);
    byDate.set(normalized.date, normalized);
  });
  return [...byDate.values()].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 400);
}

function normalizeDailyHistory() {
  state.dailyHistory = normalizeDailyHistoryList(state.dailyHistory);
}

/* Тренировки лежат в журнале state.workouts с датами и переживают переход
   через полночь (в отличие от счётчиков дня) — минуты активности за любую
   дату можно посчитать правдиво в любой момент (0.4.9: используется и при
   архивной сводке, и для честного фона статистики в дни без сводки). */
function activityMinutesForDate(date) {
  return (Array.isArray(state.workouts) ? state.workouts : [])
    .filter((workout) => workout && workout.date === date)
    .reduce((sum, workout) => sum + (Number(workout.durationMinutes) || 0), 0);
}

/* 0.8.22 (P24): компактная копия позиций еды для истории дня. */
function compactFoodItemsForHistory(items) {
  return (Array.isArray(items) ? items : []).slice(0, 100).map((f) => ({
    name: String(f && (f.name || f.raw) || '').slice(0, 120),
    amount: f && f.amount != null ? Number(f.amount) : null,
    unit: f && f.unit ? String(f.unit) : 'г',
    kcal: Math.round(Number(f && f.kcal) || 0),
    p: f && f.p != null ? Number(f.p) : null,
    f: f && f.f != null ? Number(f.f) : null,
    c: f && f.c != null ? Number(f.c) : null,
    mealType: f && f.mealType ? String(f.mealType) : null,
    perPiece: !!(f && f.perPiece)
  })).filter((x) => x.name && x.kcal >= 0);
}

function recordDailySummary(date) {
  if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return;
  const foodItems = state.food && state.food.date === date && Array.isArray(state.food.items) ? state.food.items : [];
  const waterTotal = state.water && state.water.date === date ? Number(state.water.total) || 0 : 0;
  const waterGoal = state.water && state.water.date === date ? state.water.goal : DEFAULTS.water.goal;
  const foodGoal = state.food && state.food.date === date ? state.food.goal : DEFAULTS.food.goal;
  const foodTotal = foodItems.reduce((sum, item) => sum + (Number(item.kcal) || 0), 0);
  const foodP = foodItems.reduce((sum, item) => sum + (Number(item.p) || 0), 0);
  const foodF = foodItems.reduce((sum, item) => sum + (Number(item.f) || 0), 0);
  const foodC = foodItems.reduce((sum, item) => sum + (Number(item.c) || 0), 0);
  const activityMinutes = activityMinutesForDate(date);

  // Не создаём пустые дни, если пользователь в этот день ничего не отмечал.
  if (waterTotal <= 0 && foodTotal <= 0 && activityMinutes <= 0) return;
  const summary = { date, waterTotal, waterGoal, foodTotal, foodGoal, foodP, foodF, foodC, activityMinutes };
  // 0.8.22 (P24): компактные позиции еды дня — для «Повторить вчерашний приём».
  if (foodItems.length) summary.items = compactFoodItemsForHistory(foodItems);
  if (date === todayKey() && getTodayMood()) summary.mood = getTodayMood();
  const history = Array.isArray(state.dailyHistory) ? state.dailyHistory : [];
  const index = history.findIndex((day) => day.date === date);
  if (index >= 0) history[index] = summary;
  else history.push(summary);
  state.dailyHistory = history;
  normalizeDailyHistory();
}

function normalizeActivityTemplates() {
  const templates = Array.isArray(state.activityTemplates) ? state.activityTemplates : [];
  state.activityTemplates = templates
    .filter((template) => template && typeof template === 'object'
      && ACTIVITY_TYPES[template.type]
      && normalizeActivityName(template.name)
      && Number.isFinite(Number(template.durationMinutes))
      && Number(template.durationMinutes) >= 5)
    .map((template) => ({
      id: String(template.id || uid()),
      name: normalizeActivityName(template.name),
      type: template.type,
      durationMinutes: Math.min(1440, Math.round(Number(template.durationMinutes))),
      createdAt: Number(template.createdAt) || Date.now()
    }))
    .sort((a, b) => b.createdAt - a.createdAt);
}

function normalizeWorkouts() {
  const workouts = Array.isArray(state.workouts) ? state.workouts : [];
  state.workouts = workouts
    .filter((workout) => workout && typeof workout === 'object'
      && /^\d{4}-\d{2}-\d{2}$/.test(workout.date)
      && ACTIVITY_TYPES[workout.type]
      && Number.isFinite(Number(workout.durationMinutes))
      && Number(workout.durationMinutes) >= 5)
    .map((workout) => ({
      id: String(workout.id || uid()),
      date: workout.date,
      type: workout.type,
      title: normalizeActivityName(workout.title) || null,
      note: normalizeOptionalNote(workout.note),
      intensity: ['low','medium','high'].includes(workout.intensity) ? workout.intensity : 'medium',
      durationMinutes: Math.min(1440, Math.round(Number(workout.durationMinutes))),
      createdAt: Number(workout.createdAt) || Date.now()
    }))
    .sort((a, b) => b.createdAt - a.createdAt);
}

// В списке всегда видны только имена: раскрыт может быть один профиль с его действиями.
let expandedProfileId = null;

function renderProfiles() {
  if (typeof document === 'undefined') return;
  const active = profilesState.profiles.find((profile) => profile.id === profilesState.activeId);
  const name = active ? active.name : 'Мой профиль';
  const switcher = $('#profile-switcher');
  if (switcher) {
    switcher.title = `Текущий профиль: ${name}`;
    switcher.setAttribute('aria-label', `Выбрать профиль. Текущий: ${name}`);
  }
  const settingsName = $('#profile-settings-name');
  if (settingsName) settingsName.textContent = name;
  const list = $('#profile-list');
  if (!list) return;

  list.innerHTML = profilesState.profiles.map((profile, index) => {
    const isActive = profile.id === profilesState.activeId;
    const isOpen = profile.id === expandedProfileId;
    const profileId = escapeHtml(profile.id);
    const profileName = escapeHtml(profile.name);
    const detailsId = `profile-details-${index}`;
    return `
      <section class="profile-card ${isActive ? 'active' : ''}">
        <div class="profile-card-header">
          <button type="button" class="profile-select" data-profile-id="${profileId}" aria-label="${isActive ? 'Текущий профиль' : 'Перейти в профиль'}: ${profileName}">
            <span class="profile-card-name">${profileName}</span>
            <span class="profile-card-status">${isActive ? 'Текущий' : 'Перейти ›'}</span>
          </button>
          <button class="profile-expand-btn" type="button" data-profile-expand="${profileId}" aria-expanded="${isOpen}" aria-controls="${detailsId}" aria-label="${isOpen ? 'Свернуть' : 'Открыть'} параметры профиля ${profileName}">
            <span aria-hidden="true">⌄</span>
          </button>
        </div>
        <div class="profile-card-details" id="${detailsId}" ${isOpen ? '' : 'hidden'}>
          <p>${isActive ? 'Это активный профиль. Его вес, цели, история и уведомления не смешиваются с другими профилями. Вес и график находятся на Главной и в Статистике.' : 'Нажмите название выше, чтобы перейти в этот профиль. Его данные хранятся отдельно.'}</p>
          <div class="profile-card-actions">
            <button class="profile-edit-btn" type="button" data-profile-rename="${profileId}">Переименовать</button>
            ${profile.id !== 'default' ? `<button class="profile-delete-btn" type="button" data-profile-delete="${profileId}">Удалить</button>` : ''}
          </div>
        </div>
      </section>`;
  }).join('');
}

function toggleProfileDetails(id) {
  if (!profilesState.profiles.some((profile) => profile.id === id)) return;
  expandedProfileId = expandedProfileId === id ? null : id;
  renderProfiles();
}

function openProfilesDialog() {
  expandedProfileId = null;
  renderProfiles();
  $('#profiles-dialog').hidden = false;
}
function closeProfilesDialog() {
  expandedProfileId = null;
  $('#profiles-dialog').hidden = true;
}
async function switchProfile(id) {
  if (!profilesState.profiles.some((profile) => profile.id === id)) return;
  if (id === profilesState.activeId) { closeProfilesDialog(); return; }
  saveState();
  await cancelTrainingReminder();
  await cancelMealReminders();
  await cancelWaterReminders();
  await cancelMorningMotivation();
  // 0.4.15 (аудит А3#29): курсовые напоминания тоже гасим при смене профиля
  // (раньше спасала только перезагрузка); случайные дубли cancelWater убраны.
  try { await cancelCourseReminders(); } catch (e) { }
  profilesState.activeId = id;
  saveProfiles();
  location.reload();
}
function addProfile() {
  const input = $('#profile-new-name');
  const name = normalizeActivityName(input.value);
  if (!name) { toast('Введите имя профиля'); input.focus(); return; }
  if (profilesState.profiles.length >= 10) { toast('Можно добавить не более 10 профилей'); return; }
  const id = `profile-${uid()}`;
  profilesState.profiles.push({ id, name });
  saveProfiles();
  switchProfile(id);
}

let pendingProfileRenameId = null;
function requestRenameProfile(id) {
  const profile = profilesState.profiles.find((item) => item.id === id);
  if (!profile) return;
  pendingProfileRenameId = id;
  $('#profile-rename-input').value = profile.name;
  $('#profile-rename-dialog').hidden = false;
  setTimeout(() => $('#profile-rename-input').focus(), 100);
}
function closeRenameProfileDialog() { pendingProfileRenameId = null; $('#profile-rename-dialog').hidden = true; }
function confirmRenameProfile() {
  const profile = profilesState.profiles.find((item) => item.id === pendingProfileRenameId);
  const name = normalizeActivityName($('#profile-rename-input').value);
  if (!profile || !name) { toast('Введите название профиля'); return; }
  profile.name = name;
  saveProfiles();
  closeRenameProfileDialog();
  renderProfiles();
  toast('Профиль переименован');
}

let pendingProfileDeleteId = null;
function requestDeleteProfile(id) {
  const profile = profilesState.profiles.find((item) => item.id === id);
  if (!profile || profile.id === 'default') return;
  pendingProfileDeleteId = id;
  $('#profile-delete-text').textContent = `Профиль «${profile.name}» и все его данные будут удалены только с этого устройства. Это нельзя отменить.`;
  $('#profile-delete-dialog').hidden = false;
}
function closeDeleteProfileDialog() { pendingProfileDeleteId = null; $('#profile-delete-dialog').hidden = true; }
async function confirmDeleteProfile() {
  const id = pendingProfileDeleteId;
  const profile = profilesState.profiles.find((item) => item.id === id);
  if (!profile) return closeDeleteProfileDialog();
  profilesState.profiles = profilesState.profiles.filter((item) => item.id !== id);
  localStorage.removeItem(profileStateKey(id));
  const wasActive = profilesState.activeId === id;
  if (wasActive) {
    await cancelTrainingReminder(); await cancelMealReminders();
    await cancelWaterReminders(); await cancelMorningMotivation();
    try { await cancelCourseReminders(); } catch (e) { } // 0.4.15: как и в switchProfile
    profilesState.activeId = 'default';
  }
  saveProfiles();
  closeDeleteProfileDialog();
  if (wasActive) { location.reload(); return; }
  renderProfiles();
  toast('Профиль удалён');
}

// 0.5.0: точка пошаговых миграций состояния. Старые состояния (без номера
// схемы = v1) получают номер актуальной схемы; будущие изменения формата
// добавляют сюда шаги «если версия < N — преобразовать данные».
function migrateStateSchema() {
  // 0.8.4: дневник силовых — новое поле; старые состояния дополняем пустым списком.
  if ((state.schemaVersion || 0) < 3 && !Array.isArray(state.strengthSessions)) {
    state.strengthSessions = [];
  }
  // 0.8.8: шаблоны силовых.
  if ((state.schemaVersion || 0) < 4 && !Array.isArray(state.strengthTemplates)) {
    state.strengthTemplates = [];
  }
  // 0.8.9: план тренировок.
  if ((state.schemaVersion || 0) < 5 && !Array.isArray(state.strengthPlan)) {
    state.strengthPlan = [];
  }
  state.schemaVersion = STATE_SCHEMA_VERSION;
}

function loadState() {
  try {
    const raw = localStorage.getItem(profileStateKey());
    if (raw) Object.assign(state, JSON.parse(raw));
  } catch (e) { /* повреждённые данные — начинаем заново */ }

  migrateStateSchema(); // 0.5.0

  const today = todayKey();
  const previousWaterDate = state.water.date;
  const previousFoodDate = state.food.date;
  if (previousWaterDate !== today || previousFoodDate !== today) {
    recordDailySummary(previousWaterDate !== today ? previousWaterDate : previousFoodDate);
  }
  if (state.water.date !== today) {
    state.water = { date: today, total: 0, log: [], goal: state.water.goal || DEFAULTS.water.goal };
  }
  if (state.food.date !== today) {
    state.food = { date: today, items: [], goal: state.food.goal || DEFAULTS.food.goal };
  }
  normalizeDailyHistory();
  normalizeReminderSettings();
  normalizeDayMoodReminder();
  normalizeCustomMealTypes();
  normalizeMealReminders();
  normalizeMorningMotivation();
  normalizeActivitySettings();
  normalizeProfileSettings();
  normalizeHomeLayout();
  normalizeWidgetLayout();
  normalizeFavoriteMeals();
  normalizeCustomFoods();
  normalizeCombosState();
  normalizeCourses();
  normalizeWorkouts();
  normalizeStrengthSessions();
  normalizeStrengthTemplates();
  normalizeStrengthPlan();
  normalizeActivityTemplates();
  normalizeWaterReminders();
  normalizeDayChecklist();
  normalizeGameMode();
  normalizeSleepCheckin();
  normalizeDayMood();
  normalizeOnlineFeatures();
  normalizeAiSettings();
  normalizeHealthSync();
  if (previousWaterDate !== today || previousFoodDate !== today) {
    try { localStorage.setItem(profileStateKey(), JSON.stringify(state)); } catch (e) { /* localStorage недоступен */ }
  }
}


/* ============================================================
   💾 SQLite Storage Engine (0.6.0 — sql.js WASM + IndexedDB)
   ------------------------------------------------------------
   - Полная независимость: sql.js скомпилирован в WebAssembly
     (работает 100% офлайн, без нативных плагинов и правок workflow).
   - Двойная запись (Dual-Write): каждая операция сохраняется
     в localStorage и синхронизируется в реляционные таблицы SQLite.
   - Автоматическая резервная копия: перед первой миграцией
     создаётся полный JSON-снимок fitflow:pre-sqlite-backup.
   - Безопасный откат: при любой непредвиденной ошибке WASM
     приложение бесшовно продолжает работу на localStorage.
   ============================================================ */
let sqliteDb = null;
let sqliteReady = false;
let sqliteSyncTimer = null;

const SQLITE_IDB_NAME = 'fitflow_sqlite_db';
const SQLITE_IDB_STORE = 'fitflow_store';
const SQLITE_IDB_KEY = 'main_db_bytes';

function openSqliteIdb() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') return reject(new Error('IndexedDB is not available'));
    const req = indexedDB.open(SQLITE_IDB_NAME, 1);
    req.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(SQLITE_IDB_STORE)) {
        db.createObjectStore(SQLITE_IDB_STORE);
      }
    };
    req.onsuccess = (e) => resolve(e.target.result);
    req.onerror = (e) => reject(e.target.error);
  });
}

function loadSqliteIdbBytes() {
  return new Promise(async (resolve) => {
    try {
      const db = await openSqliteIdb();
      const tx = db.transaction(SQLITE_IDB_STORE, 'readonly');
      const store = tx.objectStore(SQLITE_IDB_STORE);
      const req = store.get(SQLITE_IDB_KEY);
      req.onsuccess = (e) => resolve(e.target.result || null);
      req.onerror = () => resolve(null);
    } catch (e) {
      resolve(null);
    }
  });
}

function saveSqliteIdbBytes(bytes) {
  return new Promise(async (resolve, reject) => {
    try {
      const db = await openSqliteIdb();
      const tx = db.transaction(SQLITE_IDB_STORE, 'readwrite');
      const store = tx.objectStore(SQLITE_IDB_STORE);
      const req = store.put(bytes, SQLITE_IDB_KEY);
      req.onsuccess = () => resolve(true);
      req.onerror = (e) => reject(e.target.error);
    } catch (e) {
      reject(e);
    }
  });
}

function createSqliteSchema(db) {
  db.run(`
    CREATE TABLE IF NOT EXISTS meta (
      key TEXT PRIMARY KEY,
      value TEXT
    );
    CREATE TABLE IF NOT EXISTS profiles (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      created_at INTEGER,
      updated_at INTEGER
    );
    CREATE TABLE IF NOT EXISTS states (
      profile_id TEXT PRIMARY KEY,
      schema_version INTEGER,
      state_json TEXT NOT NULL,
      updated_at INTEGER
    );
    CREATE TABLE IF NOT EXISTS daily_summaries (
      profile_id TEXT,
      date TEXT,
      water_ml INTEGER,
      food_kcal REAL,
      activity_min INTEGER,
      weight_kg REAL,
      mood_rating INTEGER,
      PRIMARY KEY (profile_id, date)
    );
    CREATE TABLE IF NOT EXISTS food_entries (
      id TEXT PRIMARY KEY,
      profile_id TEXT,
      date TEXT,
      name TEXT,
      amount REAL,
      unit TEXT,
      kcal REAL,
      p REAL,
      f REAL,
      c REAL,
      meal_type TEXT,
      time TEXT,
      created_at INTEGER
    );
    CREATE TABLE IF NOT EXISTS workout_entries (
      id TEXT PRIMARY KEY,
      profile_id TEXT,
      date TEXT,
      type TEXT,
      duration_min INTEGER,
      kcal REAL,
      intensity TEXT,
      note TEXT,
      created_at INTEGER
    );
    CREATE TABLE IF NOT EXISTS weight_entries (
      id TEXT PRIMARY KEY,
      profile_id TEXT,
      date TEXT,
      weight_kg REAL,
      created_at INTEGER
    );
    CREATE TABLE IF NOT EXISTS custom_foods (
      id TEXT PRIMARY KEY,
      profile_id TEXT,
      name TEXT,
      kcal REAL,
      p REAL,
      f REAL,
      c REAL,
      piece_g REAL,
      created_at INTEGER
    );
    CREATE TABLE IF NOT EXISTS combos (
      id TEXT PRIMARY KEY,
      profile_id TEXT,
      name TEXT,
      text TEXT NOT NULL,
      created_at INTEGER
    );
  `);
}

function syncStateToSqliteNow() {
  if (!sqliteDb || !sqliteReady) return;
  try {
    const pId = activeProfileId || 'default';
    const sJson = JSON.stringify(state);

    // 1. Meta
    const metaStmt = sqliteDb.prepare('INSERT OR REPLACE INTO meta VALUES (?, ?)');
    metaStmt.run(['schema_version', String(STATE_SCHEMA_VERSION || 2)]);
    metaStmt.run(['active_profile', pId]);
    metaStmt.run(['fitflow_version', FITFLOW_VERSION || '0.6.0']);
    metaStmt.run(['last_sync_ts', String(Date.now())]);
    metaStmt.free();

    // 2. States
    const stateStmt = sqliteDb.prepare('INSERT OR REPLACE INTO states VALUES (?, ?, ?, ?)');
    stateStmt.run([pId, STATE_SCHEMA_VERSION || 2, sJson, Date.now()]);
    stateStmt.free();

    // 3. Profiles
    const profiles = getProfiles();
    const profStmt = sqliteDb.prepare('INSERT OR REPLACE INTO profiles VALUES (?, ?, ?, ?)');
    profiles.forEach((p) => {
      profStmt.run([p.id, p.name || 'Пользователь', p.createdAt || Date.now(), Date.now()]);
    });
    profStmt.free();

    // 4. Daily Summaries
    const dailyHist = Array.isArray(state.dailyHistory) ? state.dailyHistory : [];
    const sumStmt = sqliteDb.prepare('INSERT OR REPLACE INTO daily_summaries VALUES (?, ?, ?, ?, ?, ?, ?)');
    dailyHist.forEach((d) => {
      if (d && d.date) {
        sumStmt.run([pId, d.date, Number(d.water) || 0, Number(d.food) || 0, Number(d.workoutMinutes) || 0, d.weight != null ? Number(d.weight) : null, d.mood != null ? Number(d.mood) : null]);
      }
    });
    const cur = currentDaySummary();
    sumStmt.run([pId, cur.date, Number(cur.water) || 0, Number(cur.food) || 0, Number(cur.workoutMinutes) || 0, cur.weight != null ? Number(cur.weight) : null, cur.mood != null ? Number(cur.mood) : null]);
    sumStmt.free();

    // 5. Food Entries (today)
    const foodItems = (state.food && Array.isArray(state.food.items)) ? state.food.items : [];
    const foodStmt = sqliteDb.prepare('INSERT OR REPLACE INTO food_entries VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)');
    foodItems.forEach((f) => {
      if (f && f.id) {
        foodStmt.run([f.id, pId, todayKey(), f.name || f.raw || '', f.amount != null ? Number(f.amount) : null, f.unit || 'г', Number(f.kcal) || 0, f.p != null ? Number(f.p) : null, f.f != null ? Number(f.f) : null, f.c != null ? Number(f.c) : null, f.mealType || null, f.time || null, Number(f.createdAt) || Date.now()]);
      }
    });
    foodStmt.free();

    // 6. Workout Entries
    const workouts = Array.isArray(state.workouts) ? state.workouts : [];
    const wStmt = sqliteDb.prepare('INSERT OR REPLACE INTO workout_entries VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)');
    workouts.forEach((w) => {
      if (w && w.id) {
        wStmt.run([w.id, pId, w.date || todayKey(), w.type || 'other', Number(w.minutes || w.durationMin) || 0, Number(w.kcal) || 0, w.intensity || 'medium', w.note || null, Number(w.createdAt) || Date.now()]);
      }
    });
    wStmt.free();

    // 7. Weight Entries
    const weightHist = (state.profileSettings && Array.isArray(state.profileSettings.weightHistory)) ? state.profileSettings.weightHistory : [];
    const wtStmt = sqliteDb.prepare('INSERT OR REPLACE INTO weight_entries VALUES (?, ?, ?, ?, ?)');
    weightHist.forEach((wt) => {
      if (wt && wt.date) {
        wtStmt.run([wt.id || uid(), pId, wt.date, Number(wt.weight) || 0, Number(wt.createdAt) || Date.now()]);
      }
    });
    wtStmt.free();

    // 8. Custom Foods
    const customFoods = Array.isArray(state.customFoods) ? state.customFoods : [];
    const cfStmt = sqliteDb.prepare('INSERT OR REPLACE INTO custom_foods VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)');
    customFoods.forEach((cf) => {
      if (cf && cf.id) {
        cfStmt.run([cf.id, pId, cf.name || '', Number(cf.kcal) || 0, cf.p != null ? Number(cf.p) : null, cf.f != null ? Number(cf.f) : null, cf.c != null ? Number(cf.c) : null, cf.pieceG != null ? Number(cf.pieceG) : null, Number(cf.createdAt) || Date.now()]);
      }
    });
    cfStmt.free();

    // 9. Combos
    const combos = getCombos();
    const cbStmt = sqliteDb.prepare('INSERT OR REPLACE INTO combos VALUES (?, ?, ?, ?, ?)');
    combos.forEach((cb) => {
      if (cb && cb.id) {
        cbStmt.run([cb.id, pId, cb.name || '', cb.text || '', Number(cb.createdAt) || Date.now()]);
      }
    });
    cbStmt.free();

    // Export binary and persist to IndexedDB
    const bytes = sqliteDb.export();
    saveSqliteIdbBytes(bytes).catch((err) => console.warn('IndexedDB save failed:', err));
    renderStorageEngineStatus();
  } catch (e) {
    console.warn('SQLite sync error:', e);
  }
}

function scheduleSqliteSync() {
  if (sqliteSyncTimer) clearTimeout(sqliteSyncTimer);
  sqliteSyncTimer = setTimeout(syncStateToSqliteNow, 180);
}

function getSqliteStats() {
  if (!sqliteDb || !sqliteReady) return null;
  try {
    const qCount = (tbl) => {
      try {
        const res = sqliteDb.exec(`SELECT count(*) as c FROM ${tbl};`);
        return (res && res[0] && res[0].values && res[0].values[0] && res[0].values[0][0]) || 0;
      } catch (e) { return 0; }
    };
    return {
      summaries: qCount('daily_summaries'),
      food: qCount('food_entries'),
      workouts: qCount('workout_entries'),
      weight: qCount('weight_entries'),
      customFoods: qCount('custom_foods'),
      combos: qCount('combos'),
      profiles: qCount('profiles')
    };
  } catch (e) {
    return null;
  }
}

function renderStorageEngineStatus() {
  if (typeof document === 'undefined') return;
  const statusEl = document.getElementById('storage-engine-status');
  if (!statusEl) return;
  if (sqliteReady && sqliteDb) {
    const stats = getSqliteStats();
    if (stats) {
      statusEl.innerHTML = `💾 <b>SQLite активен (WASM + IndexedDB)</b><br><small style="opacity:0.85">Записей в базе: ${stats.summaries} дн. истории · ${stats.food} еды · ${stats.workouts} трен. · ${stats.weight} веса · Резерв: localStorage (Dual-Write)</small>`;
    } else {
      statusEl.textContent = '💾 SQLite активен (WASM + IndexedDB) · Резерв: localStorage';
    }
  } else {
    statusEl.textContent = '💾 Хранилище: localStorage (Dual-Write резерв)';
  }
}

async function initSqliteStorage() {
  if (typeof window === 'undefined') return;
  try {
    // 1. Check if SQLite bundle / init function is available
    const initFn = window.initFitFlowSqlite || (typeof initSqlJs !== 'undefined' ? initSqlJs : null);
    if (!initFn) {
      console.log('SQLite bundle не подключён, используется localStorage fallback');
      renderStorageEngineStatus();
      return;
    }

    const SQL = await initFn();
    if (!SQL || !SQL.Database) return;

    // 2. Load existing binary database from IndexedDB
    const savedBytes = await loadSqliteIdbBytes();
    if (savedBytes && savedBytes.length > 0) {
      sqliteDb = new SQL.Database(savedBytes);
      createSqliteSchema(sqliteDb);
      sqliteReady = true;
      console.log('✓ SQLite база успешно загружена из IndexedDB (' + savedBytes.length + ' байт)');
    } else {
      // 3. First time migration from localStorage to SQLite
      sqliteDb = new SQL.Database();
      createSqliteSchema(sqliteDb);
      sqliteReady = true;

      // Safety snapshot before migration
      try {
        localStorage.setItem('fitflow:pre-sqlite-backup', JSON.stringify({
          state,
          allProfiles: JSON.parse(localStorage.getItem('fitflow:all-profiles') || 'null'),
          ts: Date.now(),
          version: FITFLOW_VERSION
        }));
      } catch (e) { }

      // Initial sync
      syncStateToSqliteNow();
      console.log('✓ Выполнена начальная миграция из localStorage в SQLite');
    }

    renderStorageEngineStatus();
  } catch (err) {
    console.warn('Ошибка инициализации SQLite, переключаюсь на localStorage fallback:', err);
    sqliteReady = false;
    sqliteDb = null;
    renderStorageEngineStatus();
  }
}

function saveState() {
  try {
    recordDailySummary(todayKey());
    localStorage.setItem(profileStateKey(), JSON.stringify(state));
    updateNativeWidget();
    scheduleSqliteSync();
  } catch (e) {
    console.warn('Не удалось сохранить данные:', e);
  }
}

/* ============================================================
   Тема (Авто / Light / Dark)
   ============================================================ */
const LIGHT_THEME_COLOR = '#fafdfc';
const DARK_THEME_COLOR = '#0e1514';

function applyTheme(theme) {
  document.documentElement.setAttribute('data-theme', theme);
  document.getElementById('meta-theme')
    .setAttribute('content', theme === 'dark' ? DARK_THEME_COLOR : LIGHT_THEME_COLOR);
}

function systemPrefersDark() {
  return window.matchMedia('(prefers-color-scheme: dark)').matches;
}

function getThemeMode() {
  const saved = localStorage.getItem('fitflow:theme');
  return saved === 'light' || saved === 'dark' ? saved : 'auto';
}

function setThemeMode(mode) {
  if (mode === 'auto') {
    localStorage.removeItem('fitflow:theme');
  } else {
    localStorage.setItem('fitflow:theme', mode);
  }
  applyThemeMode(mode);
}

function applyThemeMode(mode) {
  applyTheme(mode === 'auto' ? (systemPrefersDark() ? 'dark' : 'light') : mode);
  $$('#theme-segmented button').forEach((btn) =>
    btn.classList.toggle('active', btn.dataset.themeMode === mode));
}

function initTheme() {
  applyThemeMode(getThemeMode());
  applyPalette(getPalette());
  applyFont(getFont());

  // Следим за системной темой в режиме «Авто»
  window.matchMedia('(prefers-color-scheme: dark)')
    .addEventListener('change', (e) => {
      if (getThemeMode() === 'auto') {
        applyTheme(e.matches ? 'dark' : 'light');
      }
    });
}

function toggleTheme() {
  const current = document.documentElement.getAttribute('data-theme');
  setThemeMode(current === 'dark' ? 'light' : 'dark');
}

