function activityThemeEmoji(type) {
  const p = getPalette();
  const set = THEME_ACTIVITY_SETS[p] || THEME_ACTIVITY_SETS.standard;
  return set[type] || (ACTIVITY_TYPES[type] && ACTIVITY_TYPES[type].emoji) || '💪';
}
function themeIcon(slot) {
  const set = THEME_ICON_SETS[getPalette()] || THEME_ICON_STANDARD;
  return set[slot] || THEME_ICON_STANDARD[slot] || '';
}
function applyThemeIconSet() {
  if (typeof document === 'undefined' || !document.querySelectorAll) return;
  document.querySelectorAll('[data-icon-slot]').forEach((el) => {
    const v = themeIcon(el.dataset.iconSlot);
    if (v && el.textContent !== v) el.textContent = v;
  });
}
/* Иконка карточки Главной в текстовых местах (быстрые чипы, список порядка):
   тематический эмодзи; Вес — SVG напольных весов (0.4.14). */
function homeCardIcon(id) {
  const slotMap = { 'day-plan': 'dayplan', 'day-mood': 'mood', water: 'water', food: 'food' };
  const slot = slotMap[id];
  if (slot) return themeIcon(slot);
  const found = HOME_CARDS.find((c) => c.id === id);
  return found ? found.icon : '';
}

function getPalette() {
  const saved = localStorage.getItem('fitflow:palette');
  return PALETTE_IDS.has(saved) ? saved : 'standard';
}

function applyPalette(palette) {
  const p = PALETTE_IDS.has(palette) ? palette : 'standard';
  if (p === 'standard') document.documentElement.removeAttribute('data-palette');
  else document.documentElement.setAttribute('data-palette', p);
  $$('#palette-segmented button').forEach((btn) =>
    btn.classList.toggle('active', btn.dataset.palette === p));
  applyThemeIconSet(); // 0.4.14: значки разделов под тему
}

function setPalette(palette) {
  const p = PALETTE_IDS.has(palette) ? palette : 'standard';
  if (p === 'standard') localStorage.removeItem('fitflow:palette');
  else localStorage.setItem('fitflow:palette', p);
  applyPalette(p);
  const label = (PALETTES.find((x) => x.id === p) || {}).label || p;
  toast('🎨 Стиль: ' + label + (p === 'neon' ? ' — эффектнее всего в тёмном режиме' : ''));
}


/* Шрифты тем из СИСТЕМНЫХ семейств Android (0.4.10, просьба «доп. шрифты в
   темах»): ноль файлов в APK, ноль сети — WebView гарантированно имеет
   sans-serif (Roboto), sans-serif-condensed (он играет Sport) и serif.
   Авторский файловый шрифт (Comfortaa для «Винограда») — отдельная опция
   пользователя через tools/github-workflows/FONT_PATCH.md (нужна ручная
   правка workflow и загрузка .ttf, памятка там же). */
const FONT_OPTIONS = ['standard', 'condensed', 'serif'];
const FONT_LABELS = { standard: 'Стандарт', condensed: 'Узкий (Condensed)', serif: 'Книжный с засечками' };
function getFont() {
  const saved = localStorage.getItem('fitflow:font');
  return FONT_OPTIONS.includes(saved) ? saved : 'standard';
}
function applyFont(font) {
  const f = FONT_OPTIONS.includes(font) ? font : 'standard';
  // 0.4.15 (п.4 владельца): «Стандарт» выбран ЯВНО (ключ сохранён) —
  // единый системный шрифт поверх всех тем; ключ ещё не задан — тематические шрифты живут.
  if (f === 'standard') {
    if (localStorage.getItem('fitflow:font') === 'standard') document.documentElement.setAttribute('data-font', 'standard');
    else document.documentElement.removeAttribute('data-font');
  }
  else document.documentElement.setAttribute('data-font', f);
  $$('#font-segmented button').forEach((btn) =>
    btn.classList.toggle('active', btn.dataset.font === f));
}
function setFont(font) {
  const f = FONT_OPTIONS.includes(font) ? font : 'standard';
  localStorage.setItem('fitflow:font', f); // 0.4.15: «Стандарт» — тоже явный выбор
  applyFont(f);
  toast('🔤 Шрифт: ' + FONT_LABELS[f]);
}
/* ============================================================
   Рендер
   ============================================================ */
const RING_CIRCUMFERENCE = 2 * Math.PI * 54;
// 0.4.15 (аудит А2): статичное «Сегодня отличный день…» выцветало — небольшой пул,
// детерминированная ротация по дню года (без случайности и повторных сюрпризов).
const GREETING_SUBTITLES = [
  'Маленькие шаги каждый день важнее идеального понедельника',
  'Стакан воды и короткая прогулка — уже хороший день',
  'Записывайте по факту — FitFlow сам всё посчитает',
  'Сегодняшние записи — завтрашняя честная статистика',
  'Без спешки: ровный ритм побеждает рывки',
  'Вода, еда, движение, сон — остальное приложится',
  'Данные остаются на устройстве — дневник только ваш',
  'Любая запись лучше, чем день без записей'
];
let activeStatsPeriod = 'week';
let activeWaterDetailPeriod = 'week';
let activeFoodDetailPeriod = 'week';
let activeWeightPeriod = 'month';

/* 0.9.4: короткие тексты для строк виджета, которых нет в старом наборе.
   Виджет — не второе приложение: одна строка = один факт без расшифровок. */
function widgetWeightLine() {
  const history = normalizeWeightHistory(state.profileSettings.weightHistory);
  const latest = history[history.length - 1];
  const weight = state.profileSettings.weightKg || (latest ? latest.weightKg : null);
  return weight ? `Вес: ${Number(weight).toLocaleString('ru-RU')} кг` : 'Вес: нет записей';
}

function widgetDayPlanLine() {
  const waterOk = state.water.goal > 0 && state.water.total >= state.water.goal;
  const foodKcal = state.food.items.reduce((sum, item) => sum + (Number(item.kcal) || 0), 0);
  const foodOk = computeMealsEatenToday() >= 3 || (state.food.goal > 0 && foodKcal >= state.food.goal);
  const activityOk = (Array.isArray(state.workouts) ? state.workouts : [])
    .filter((workout) => workout.date === todayKey()).length > 0;
  const rows = [];
  if (isTrackerEnabled('water')) rows.push(waterOk);
  if (isTrackerEnabled('food')) rows.push(foodOk);
  rows.push(activityOk);
  const done = rows.filter(Boolean).length;
  return `План дня: ${done} из ${rows.length}`;
}

function widgetMoodLine() {
  const mood = getTodayMood();
  const emojis = { 1: '😞', 2: '🙁', 3: '😐', 4: '🙂', 5: '😄' };
  return mood ? `Самочувствие: ${emojis[mood]} ${mood}/5` : 'Самочувствие: не отмечено';
}

/* Календарь тренировок на виджете: что назначено планом силовых на сегодня
   и что уже выполнено. Плюс обычные тренировки дня, если они записаны. */
function widgetWorkoutLine() {
  const templates = state.strengthTemplates || [];
  const plan = normalizeStrengthPlanList(state.strengthPlan);
  const dow = strengthTodayDow();
  const todayPlan = plan.filter((entry) => entry.days.includes(dow))
    .map((entry) => templates.find((template) => template.id === entry.templateId))
    .filter(Boolean);
  if (todayPlan.length) {
    const done = todayPlan.filter((template) => isPlanDoneToday(template.id)).length;
    if (done >= todayPlan.length) return `Тренировка: ✅ ${todayPlan[0].name}`;
    const next = todayPlan.find((template) => !isPlanDoneToday(template.id));
    return `Тренировка: ${next ? next.name : todayPlan[0].name}`;
  }
  const logged = (Array.isArray(state.workouts) ? state.workouts : [])
    .filter((workout) => workout.date === todayKey()).length;
  if (logged > 0) return `Тренировка: записана (${logged})`;
  return 'Тренировка: отдых';
}

function widgetActivityLine(activityMinutes) {
  const minutes = Number(activityMinutes) || 0;
  if (minutes <= 0) return 'Активность: 0 мин';
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  if (!hours) return `Активность: ${minutes} мин`;
  return rest ? `Активность: ${hours} ч ${rest} мин` : `Активность: ${hours} ч`;
}

function updateNativeWidget() {
  if (typeof window === 'undefined' || !window.FitFlowExport
      || typeof window.FitFlowExport.updateWidget !== 'function') return;
  try {
    const activityMinutes = (Array.isArray(state.workouts) ? state.workouts : [])
      .filter((workout) => workout.date === todayKey())
      .reduce((sum, workout) => sum + (Number(workout.durationMinutes) || 0), 0);
    const foodTotal = state.food.items.reduce((sum, item) => sum + (Number(item.kcal) || 0), 0);
    const stepsToday = (state.healthSync && state.healthSync.lastSteps) || getPhoneSteps() || 0;
    const activeProfile = profilesState.profiles.find((profile) => profile.id === profilesState.activeId);
    const profileName = String(activeProfile ? activeProfile.name : 'Мой профиль').slice(0, 40);
    window.FitFlowExport.updateWidget(JSON.stringify({
      waterTotal: state.water.total,
      waterGoal: state.water.goal,
      lastWaterAt: state.water.lastAddedAt || 0, // для автопропуска ближайшего напоминания (0.5.6)
      foodTotal,
      foodGoal: state.food.goal,
      activityMinutes,
      stepsToday,
      priority: (state.healthSync && state.healthSync.priority) || 'auto', // 0.7.13: для фонового разрешения шагов в виджете
      profileName,
      date: todayKey(),
      // 0.9.4: раскладка виджета — список выбранных строк (в порядке пользователя)
      // и готовые тексты для тех из них, которые натив сам посчитать не может.
      widgetItems: activeWidgetItems().join(','),
      widgetSize: normalizeWidgetLayoutValue(state.widgetLayout).size,
      weightLine: widgetWeightLine(),
      dayPlanLine: widgetDayPlanLine(),
      moodLine: widgetMoodLine(),
      workoutLine: widgetWorkoutLine(),
      activityLine: widgetActivityLine(activityMinutes)
    }));
  } catch (e) {
    console.warn('Не удалось обновить Android-виджет:', e);
  }
}

