function getWeightHistoryForPeriod(period = activeWeightPeriod) {
  const history = normalizeWeightHistory(state.profileSettings.weightHistory);
  if (period === 'all') return history;
  const days = period === 'week' ? 7 : 30;
  const start = new Date();
  start.setHours(0, 0, 0, 0);
  start.setDate(start.getDate() - (days - 1));
  const startKey = `${start.getFullYear()}-${String(start.getMonth() + 1).padStart(2, '0')}-${String(start.getDate()).padStart(2, '0')}`;
  return history.filter((entry) => entry.date >= startKey);
}

function formatWeightDate(dateKey) {
  return new Intl.DateTimeFormat('ru-RU', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(`${dateKey}T12:00:00`));
}

/* Общая отрисовка графика веса в переданный SVG (подробный вид и мини-вид) */
function drawWeightChartInto(wrap, chart, history) {
  if (!wrap || !chart) return;
  if (!history || history.length === 0) { wrap.hidden = true; chart.innerHTML = ''; return; }

  const width = 320, height = 150, left = 38, right = 12, top = 12, bottom = 28;
  const values = history.map((entry) => entry.weightKg);
  const rawMin = Math.min(...values), rawMax = Math.max(...values);
  const padding = Math.max(rawMax - rawMin, 1) * 0.15;
  const min = rawMin - padding, max = rawMax + padding;
  const plotWidth = width - left - right, plotHeight = height - top - bottom;
  const point = (entry, index) => {
    const x = history.length === 1 ? left + plotWidth / 2 : left + (index / (history.length - 1)) * plotWidth;
    const y = top + ((max - entry.weightKg) / (max - min)) * plotHeight;
    return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 };
  };
  const points = history.map(point);
  const line = points.map((item) => `${item.x},${item.y}`).join(' ');
  const label = (weight) => `${Number(weight.toFixed(1)).toLocaleString('ru-RU')} кг`;
  const firstDate = formatWeightDate(history[0].date);
  const lastDate = formatWeightDate(history[history.length - 1].date);
  // Записи за один день: одна дата, без странного диапазона «3 авг — 3 авг».
  const sameDay = firstDate === lastDate;
  chart.setAttribute('aria-label', `График веса: от ${label(rawMin)} до ${label(rawMax)}, ${history.length} записей`);
  chart.innerHTML = `
    <line x1="${left}" y1="${top}" x2="${width - right}" y2="${top}" class="weight-grid" />
    <line x1="${left}" y1="${top + plotHeight / 2}" x2="${width - right}" y2="${top + plotHeight / 2}" class="weight-grid" />
    <line x1="${left}" y1="${top + plotHeight}" x2="${width - right}" y2="${top + plotHeight}" class="weight-grid" />
    <text x="2" y="${top + 4}" class="weight-axis-label">${label(rawMax)}</text>
    <text x="2" y="${top + plotHeight}" class="weight-axis-label">${label(rawMin)}</text>
    ${history.length > 1 ? `<polyline points="${line}" class="weight-line" />` : ''}
    ${points.map((item, index) => `<circle cx="${item.x}" cy="${item.y}" r="4" class="weight-point"><title>${formatWeightDate(history[index].date)} · ${label(history[index].weightKg)}</title></circle>`).join('')}
    <text x="${left}" y="${height - 7}" class="weight-date-label">${escapeHtml(firstDate)}</text>
    ${sameDay ? '' : `<text x="${width - right}" y="${height - 7}" text-anchor="end" class="weight-date-label">${escapeHtml(lastDate)}</text>`}`;
  wrap.hidden = false;
}

function renderWeightChart(history) {
  drawWeightChartInto($('#weight-chart-wrap'), $('#weight-chart'), history);
}

/* Мини-график веса на общем экране Статистики — за последние ~3 месяца */
function renderStatsWeightChart() {
  if (typeof document === 'undefined') return;
  const wrap = $('#stats-weight-chart-wrap');
  const chart = $('#stats-weight-chart');
  if (!wrap || !chart) return;
  const all = normalizeWeightHistory(state.profileSettings.weightHistory);
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - 92);
  const cutoffKey = `${cutoff.getFullYear()}-${String(cutoff.getMonth() + 1).padStart(2, '0')}-${String(cutoff.getDate()).padStart(2, '0')}`;
  const recent = all.filter((entry) => entry.date >= cutoffKey);
  const shown = recent.length ? recent : all.slice(-8);
  const caption = $('#stats-weight-chart-caption');
  if (caption) {
    const sameDay = shown.length > 0 && shown[0].date === shown[shown.length - 1].date;
    caption.textContent = !all.length
      ? ''
      : (shown.length < 5 || sameDay)
        ? 'График охватывает последние 3 месяца — записей пока мало, он заполнится по мере регулярных взвешиваний.'
        : 'По записям за последние 3 месяца.';
  }
  // 0.4.15 (аудит А3): одна точка — не график, а честный текст.
  const distinctWeightDates = new Set(shown.map((entry) => entry.date));
  if (shown.length < 2 || distinctWeightDates.size < 2) {
    chart.innerHTML = '';
    if (caption) caption.textContent = shown.length
      ? 'Пока одна запись веса (' + formatWeightDate(shown[shown.length - 1].date) + ') — добавьте ещё одну, появится линия динамики.'
      : 'Записей веса пока нет — добавьте первую на Главной.';
    return;
  }
  drawWeightChartInto(wrap, chart, shown);
}

/* 0.4.15 (аудит А2/А3): «компактный план» — одна строка вместо подробного списка,
   по желанию; вид главной по умолчанию не меняется. */
function isDayPlanCollapsed() { try { return localStorage.getItem('fitflow:dayplan-collapsed') === '1'; } catch (e) { return false; } }
function toggleDayPlanCollapsed() { try { localStorage.setItem('fitflow:dayplan-collapsed', isDayPlanCollapsed() ? '0' : '1'); } catch (e) { } renderDayPlan(); }

/* «План дня» — объединённая карточка (0.3.11, идея пользователя):
   чек-лист и задания дня выглядели слишком похоже — теперь это одно
   «сердце дня» на Главной. Видны те секции, чьи функции включены. */
function renderDayPlan() {
  if (typeof document === 'undefined') return;
  const card = $('#day-plan-card');
  if (!card) return;
  const shown = isHomeCardShown('day-plan'); // хотя бы одна функция включена И карточка не скрыта в порядке
  card.hidden = !shown;
  renderDayMoodCard();
  renderHomeQuickNav();
  if (!shown) return;

  const showChecklist = (state.homeDensity === 'normal' || state.homeDensity === 'full') || !!(state.dayChecklist && state.dayChecklist.enabled);
  const showTasks = !!(state.gameMode && state.gameMode.enabled);

  // --- Секция чек-листа: авто-отметки по записям дня ---
  let checklistItems = '';
  if (showChecklist) {
    /* Единый критерий с заданиями (замечание пользователя: «цель по воде не
       достигнута, а галочка уже стоит» — чек-лист раньше отмечал при 80%,
       задание — при 100%; теперь галочка = полный план, без расхождений). */
    const waterOk = state.water.total >= state.water.goal && state.water.goal > 0;
    const foodKcal = state.food.items.reduce((sum, item) => sum + (Number(item.kcal) || 0), 0);
    const foodOk = computeMealsEatenToday() >= 3 || (foodKcal >= state.food.goal && state.food.goal > 0);
    const activityOk = (Array.isArray(state.workouts) ? state.workouts : [])
      .filter((w) => w.date === todayKey()).length > 0;
    // 0.8.25: скрытая карточка = выключенный показатель, строки в Плане дня нет
    const showWaterRow = isTrackerEnabled('water');
    const showFoodRow = isTrackerEnabled('food');

    const itemMark = (ok) => ok ? '<span class="checklist-icon done">✓</span>' : '<span class="checklist-icon pending">○</span>';
    const itemText = (ok) => ok ? 'checklist-item done' : 'checklist-item';

    const waterText = waterOk ? 'цель достигнута' : fmt(state.water.total) + ' из ' + fmt(state.water.goal) + ' мл';
    // 0.3.32 (кейс пользователя): «11 зап.» при заполненных завтраке и обеде —
    // цифра была числом ПРОДУКТОВ, а не записей. Честно: столько-то приёмов
    // (заполненные завтрак/обед/ужин) и столько-то позиций в них.
    const foodItemsLogged = state.food.items.length;
    const foodMealsLogged = computeMealsEatenToday();
    const foodText = foodOk ? 'основной рацион учтён' : (foodItemsLogged > 0
      ? 'в процессе (' + (foodMealsLogged > 0
          ? foodMealsLogged + ' ' + ruForms(foodMealsLogged, ['приём', 'приёма', 'приёмов']) + ' · ' : '')
        + foodItemsLogged + ' ' + ruForms(foodItemsLogged, ['позиция', 'позиции', 'позиций']) + ')'
      : 'ничего не добавлено');
    const activityText = activityOk ? 'отмечена' : 'сегодня без активности';

    // Пункт «Сон» — когда включён чек-ин сна: кликабельная строка, открывает диалог.
    let sleepRow = '';
    if (state.sleepCheckin && state.sleepCheckin.enabled) {
      const entry = getTodaySleepEntry();
      const bits = [];
      if (entry && entry.durationMin != null) bits.push(formatWorkoutDuration(entry.durationMin));
      if (entry && entry.rating != null) bits.push(`оценка ${entry.rating}/5`);
      const sleepText = entry ? (bits.join(' · ') || 'отмечен') : 'не отмечен — оценить';
      // 0.5.1 (вопрос владельца «что значит серая галочка у сна при зелёной
      // активности»): вместо загадочной серой ✓ — сама оценка сна эмодзи в кружке;
      // цвет честно повторяет ВАШУ оценку (4–5 зелёный, 3 нейтральный, 1–2 янтарный).
      let sleepMark = '<span class="checklist-icon pending">○</span>';
      const SLEEP_MARK_EMOJIS = { 1: '😫', 2: '🙁', 3: '😐', 4: '🙂', 5: '🚀' };
      if (entry && entry.rating != null && SLEEP_MARK_EMOJIS[entry.rating]) {
        const markCls = entry.rating >= 4 ? 'mark-good' : (entry.rating === 3 ? 'mark-mid' : 'mark-low');
        sleepMark = `<span class="checklist-icon ${markCls}">${SLEEP_MARK_EMOJIS[entry.rating]}</span>`;
      } else if (entry) {
        sleepMark = '<span class="checklist-icon noted">✓</span>'; // отмечен без оценки
      }
      sleepRow = `<button type="button" class="${entry ? 'checklist-item noted' : 'checklist-item'} checklist-sleep-btn" data-sleep-open>${sleepMark} Сон — ${sleepText}</button>`;
    }

    checklistItems = `<div class="checklist-items">
      ${sleepRow}
      ${showWaterRow ? `<span class="${itemText(waterOk)}">${itemMark(waterOk)} Вода — ${waterText}</span>` : ''}
      ${showFoodRow ? `<span class="${itemText(foodOk)}">${itemMark(foodOk)} Питание — ${foodText}</span>` : ''}
      <span class="${itemText(activityOk)}">${itemMark(activityOk)} Активность — ${activityText}</span>
    </div>`;
  }

  // --- Секция заданий дня (игровой режим) ---
  let tasksHtml = '';
  let headerNote = '';
  if (showTasks) {
    const tasks = computeGameTasks();
    const doneCount = tasks.filter((t) => t.cur >= t.target).length;
    if (!tasks.length) headerNote = ''; // 0.8.25: все показатели скрыты — заданий нет
    if (tasks.length) headerNote = `<span class="game-tasks-note">Задания: ${doneCount} из ${tasks.length}</span>`;
    tasksHtml = tasks.map((t) => {
      const done = t.cur >= t.target;
      const pct = Math.min(100, Math.round((t.cur / Math.max(1, t.target)) * 100));
      return `<div class="game-task-row${done ? ' done' : ''}">
      <span class="game-task-icon">${t.icon || t.emoji}</span>
      <div class="game-task-info">
        <div class="game-task-title">${t.title}</div>
        <div class="game-task-numbers">${fmt(t.cur)} из ${fmt(t.target)} ${t.unit}</div>
        <div class="game-task-bar"><span style="width:${pct}%"></span></div>
      </div>
      <span class="game-task-state">${done ? '✓' : pct + '%'}</span>
    </div>`;
    }).join('') + `
    ${tasks.length && doneCount === tasks.length ? '<div class="game-win">🏆 Все задания дня выполнены — отличный день!</div>' : ''}
    <div class="game-tasks-footer">
      <span class="game-tasks-note">Отметки ставятся сами по вашим записям</span>
      <button class="btn btn-secondary" type="button" data-game-medals-open style="font-size:0.74rem;padding:6px 12px">🏅 Медали</button>
    </div>`;
  }

  // 0.3.30: строки «Моего курса» — ручные отметки приёмов (не вычисляются
  // из других записей, в отличие от воды/питания — только подтверждение).
  // 0.4.15: свёрнутый вид — одна честная сводная строка.
  if (isDayPlanCollapsed()) {
    const foodKcalNow = state.food.items.reduce((sum, item) => sum + (Number(item.kcal) || 0), 0);
    const actNow = (Array.isArray(state.workouts) ? state.workouts : [])
      .filter((w) => w.date === todayKey()).reduce((sum, w) => sum + (Number(w.durationMinutes) || 0), 0);
    // 0.8.25: в свёрнутой строке — только те показатели, что ведутся
    const collapsedBits = [];
    if (isTrackerEnabled('water')) collapsedBits.push(`💧 ${fmt(state.water.total)}/${fmt(state.water.goal)} мл`);
    if (isTrackerEnabled('food')) collapsedBits.push(`🔥 ${fmt(foodKcalNow)}/${fmt(state.food.goal)} ккал`);
    collapsedBits.push(`🏃 ${actNow} мин`);
    card.innerHTML = `<div class="card checklist-card" aria-label="План дня">
    <div class="checklist-header"><span>📋 План дня</span>${headerNote}<button class="day-plan-toggle" type="button" data-dayplan-toggle aria-label="Развернуть план дня" title="Развернуть">▸</button></div>
    <p class="day-plan-collapsed-line">${collapsedBits.join(' · ')}</p>
  </div>`;
    return;
  }
  const coursesPlanHtml = buildCoursesPlanHtml();
  card.innerHTML = `<div class="card checklist-card" aria-label="План дня">
    <div class="checklist-header"><span>📋 План дня</span>${headerNote}<button class="day-plan-toggle" type="button" data-dayplan-toggle aria-label="Свернуть план дня" title="Свернуть">▾</button></div>
    ${checklistItems}
    ${coursesPlanHtml}
    ${(showChecklist || coursesPlanHtml) && showTasks ? '<hr class="day-plan-divider">' : ''}
    ${tasksHtml}
  </div>`;
}

/* Старые имена оставлены обёртками: они вызываются из многих мест
   (вода, питание, активность, чек-ин сна, статистика) и рисуют
   одну объединённую карточку «План дня». */
function renderDayChecklist() { renderDayPlan(); }

/* Самочувствие — отдельная секция (до 0.2.9 была пунктом чек-листа):
   общая оценка всего дня подряд, удобнее отмечать вечером. */
function renderDayMoodCard() {
  if (typeof document === 'undefined') return;
  const card = $('#day-mood-card');
  if (!card) return;
  const shown = isHomeCardShown('day-mood');
  if (!shown) { card.hidden = true; return; }
  const mood = getTodayMood();
  const emojis = { 1: '😞', 2: '🙁', 3: '😐', 4: '🙂', 5: '😄' };
  const labels = { 1: 'тяжёлый', 2: 'слабый', 3: 'обычный', 4: 'хороший', 5: 'отличный' };
  const buttons = [1, 2, 3, 4, 5].map((n) =>
    `<button type="button" class="mood-inline-btn${mood === n ? ' active' : ''}" data-mood-inline="${n}" title="${n} из 5 — ${labels[n]}" aria-label="Оценить день на ${n} из 5">${emojis[n]}</button>`).join('');
  const evening = new Date().getHours() >= 17;
  const note = mood
    ? `${emojis[mood]} ${mood}/5 · ${labels[mood]}`
    : (evening ? 'как прошёл день?' : 'оцените день');
  card.hidden = false;
  // 0.5.8: строка 1 — «🌗 Самочувствие» + знак «?» (справка);
  //        строка 2 — кнопки 1–5 + статус оценки
  card.innerHTML = `<div class="card checklist-card mood-card" aria-label="Самочувствие за день">
    <div class="mood-card-row mood-compact-row">
      <div class="mood-compact-top">
        <span class="mood-compact-label">🌗 Самочувствие</span>
        <span class="help-dot mood-help-dot" role="button" tabindex="0" onclick="openHelpTopicDialog('day-mood')" data-help="day-mood" aria-label="Справка о самочувствии" title="Зачем отмечать самочувствие?">?</span>
      </div>
      <div class="mood-compact-bottom">
        <span class="mood-inline-row">${buttons}</span>
        <span class="mood-compact-note">${note}</span>
      </div>
    </div>
  </div>`;
}

function renderDayMood() {
  renderDayMoodCard();
}

function renderDayChecklistSettings() {
  if (typeof document === 'undefined') return;
  const toggle = $('#day-checklist-toggle');
  const status = $('#day-checklist-status');
  if (!toggle || !status) return;
  toggle.checked = state.dayChecklist.enabled;
  status.textContent = state.dayChecklist.enabled
    ? 'Чек-лист показывается на Главной.'
    : 'Чек-лист скрыт.';
}

function updateDayChecklistEnabled(enabled) {
  state.dayChecklist.enabled = enabled;
  saveState();
  renderDayChecklist();
  renderDayChecklistSettings();
  toast(enabled ? 'Чек-лист дня включён' : 'Чек-лист дня скрыт');
}

/* ============================================================
   🎮 Игровой режим (включается в Настройках → «Общее»):
   задания дня на Главной, медали/рекорды по истории и
   сравнение текущего периода с прошлым в Статистике.
   Отметки заданий — автоматические, из реальных данных дня:
   честно и без лишних нажатий.
============================================================ */

/* Иконки заданий — инлайн-SVG в едином стиле приложения (видны в любой теме,
   не зависят от системного набора эмодзи). */
const GAME_TASK_ICONS = {
  water: '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 3.2c3.4 3.7 5.7 6.8 5.7 9.5a5.7 5.7 0 1 1-11.4 0c0-2.7 2.3-5.8 5.7-9.5Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg>',
  food: '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4.5 12h15a7.5 7.5 0 0 1-15 0Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M8.5 8.5c1-1.8 3.5-2.4 5.4-1.4M12 6.5V4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>',
  activity: '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M3 12h4l2-5 4 10 2-5h6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>'
};

/* Задание «3 записи питания» — это ПРИЁМЫ ПИЩИ, а не число продуктов
   (замечание пользователя 0.3.17→0.3.18: «завтрак йогурт-бутерброд-банан
   считался за 3 записи — некорректно»). Считаем уникальные основные
   приёмы дня: завтрак/обед/ужин. Перекусы (полдник, поздний перекус,
   пользовательские типы) прогресс задания не дают. */
const MAIN_MEAL_IDS = ['breakfast', 'lunch', 'dinner'];
function computeMealsEatenToday(items) {
  const list = Array.isArray(items) ? items : (state.food.items || []);
  const eaten = new Set();
  list.forEach((item) => {
    if (item && MAIN_MEAL_IDS.includes(item.mealTypeId)) eaten.add(item.mealTypeId);
  });
  return eaten.size; // 0..3
}

function computeGameTasks() {
  const waterTotal = Number(state.water.total) || 0;
  const waterGoal = Number(state.water.goal) || DEFAULTS.water.goal;
  const mealsEaten = computeMealsEatenToday();
  const activityMinutes = (Array.isArray(state.workouts) ? state.workouts : [])
    .filter((w) => w.date === todayKey())
    .reduce((sum, w) => sum + (Number(w.durationMinutes) || 0), 0);
  // 0.8.25: задания только по тем показателям, которые ведутся (скрытая
  // карточка исключает и задание — иначе «выполнено 2 из 3» стало бы
  // недостижимым по показателю, который владелец сознательно выключил).
  return [
    { id: 'water', emoji: '💧', icon: GAME_TASK_ICONS.water, title: 'Норма воды', cur: waterTotal, target: waterGoal, unit: 'мл' },
    { id: 'food', emoji: '🥑', icon: GAME_TASK_ICONS.food, title: 'Завтрак, обед и ужин', cur: mealsEaten, target: 3, unit: 'приём' },
    { id: 'activity', emoji: '🏃', icon: GAME_TASK_ICONS.activity, title: '30 минут активности', cur: activityMinutes, target: 30, unit: 'мин' }
  ].filter((task) => isTrackerEnabled(task.id));
}

function renderGameMode() { renderDayPlan(); }

/* Докрутка к полю/кнопкам — СНОВА ВКЛЮЧЕНА (0.3.17), теперь окончательно
   оправданная: эксперимент 0.3.15–0.3.16 показал, что баг «клавиатура со 2-го
   тапа + молчит GBoard» идентичен и с выключенным компаньоном, и без модалки
   вообще (ИИ-центр = обычный экран) — наш скролл НЕ был причиной. А выключенная
   докрутка оставила реальный недостаток: клавиатура перекрывает поле ввода.
   IME-безопасность сохранена: скролл либо по факту visualViewport.resize
   (клавиатура реально показалась), либо ОДИН запасной мгновенный шаг через
   500 мс после фокуса — уже после окна анимации IME (~300 мс). */
const KEYBOARD_SHIFT_ASSIST = true;

/* IME-БЕЗОПАСНАЯ докрутка (0.3.13, расследование бага GBoard):
   скроллим только по факту изменения видимого viewport (когда клавиатура
   реально меняет раскладку), МГНОВЕННЫМ шагом и не более 2 раз за один фокус.
   Прежний подход (плавный scrollIntoView по таймеру фокуса) гонялся с
   анимацией появления клавиатуры — у части устройств/WebView IME-сессия
   рвалась: клавиатура «не открывалась с первого тапа», а в такой сессии
   голосовой ввод GBoard молчал («Говорите», но текст не вставлялся). */
let keyboardShiftState = { field: null, left: 0, raf: 0, timer: 0 };

function scheduleKeyboardShift(field) {
  // Скролла в самом focusin нет: показ клавиатуры занимает ~250–350 мс, и
  // скролл старше этого окна рискован для IME. Два безопасных триггера:
  // 1) visualViewport.resize — клавиатура реально изменила раскладку;
  // 2) запасной ОДИНОЧНЫЙ мгновенный шаг через 500 мс (уже после анимации
  //    показа) — страховка на случай, если resize не приходит
  //    (текущий нативный режим adjustPan; с манифест-патчем adjustResize
  //    основным станет п.1).
  keyboardShiftState.field = field;
  keyboardShiftState.left = 2; // максимум две мягкие докрутки на один фокус
  clearTimeout(keyboardShiftState.timer);
  keyboardShiftState.timer = setTimeout(() => {
    ensureFieldActionsVisible(keyboardShiftState.field);
  }, 500);
}

function cancelKeyboardShift() {
  keyboardShiftState.field = null;
  keyboardShiftState.left = 0;
  cancelAnimationFrame(keyboardShiftState.raf);
  clearTimeout(keyboardShiftState.timer);
  keyboardShiftState.timer = 0;
}

function queueKeyboardShift() {
  const st = keyboardShiftState;
  cancelAnimationFrame(st.raf);
  st.raf = requestAnimationFrame(() => ensureFieldActionsVisible(st.field));
}

/* Докручиваем МГНОВЕННО и на минимум: чтобы последняя кнопка действий под полем
   («Разобрать», «Сохранить») оказалась над клавиатурой, но само поле не уехало
   за шапку. Без scrollIntoView/smooth — именно они провоцировали гонку с IME. */
function ensureFieldActionsVisible(field) {
  if (!KEYBOARD_SHIFT_ASSIST) return;
  const st = keyboardShiftState;
  if (!field || !field.isConnected || document.activeElement !== field || st.left <= 0) return;
  const scope = field.closest('form, .card, .ai-tab-panel, .settings-view, .app-dialog-backdrop') || field.parentElement;
  let target = field;
  if (scope) {
    const buttonsAfter = Array.from(scope.querySelectorAll('button'))
      .filter((b) => b.offsetParent !== null
        && (field.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING));
    if (buttonsAfter.length) target = buttonsAfter[buttonsAfter.length - 1];
  }
  const vh = (window.visualViewport && window.visualViewport.height) || window.innerHeight;
  const r = target.getBoundingClientRect();
  let delta = Math.round(r.bottom - (vh - 24));
  // Ограничитель: поле не должно быть утащено вверх за шапку приложения.
  const fr = field.getBoundingClientRect();
  delta = Math.min(delta, Math.max(0, Math.round(fr.top - 56)));
  if (delta > 8) {
    st.left--;
    window.scrollBy(0, delta); // мгновенный шаг без анимации — IME-safe
  }
}

function renderGameModeSettings() {
  if (typeof document === 'undefined') return;
  const toggle = $('#game-mode-toggle');
  const status = $('#game-mode-status');
  if (!toggle || !status) return;
  toggle.checked = state.gameMode.enabled;
  status.textContent = state.gameMode.enabled
    ? 'Задания дня на Главной включены; в Статистике видно сравнение с прошлым периодом.'
    : 'Задания дня и медали скрыты.';
}

function updateGameModeEnabled(enabled) {
  state.gameMode.enabled = enabled;
  saveState();
  renderGameMode();
  renderGameModeSettings();
  renderStats();
  toast(enabled ? '🎮 Игровой режим включён' : 'Игровой режим скрыт');
}

/* ============================================================
   😴 Чек-ин сна — UI. Утром (05:00–12:00) при открытии приложения
   появляется диалог: оценка сна в 1 тап; опционально «лёг/встал»
   и «что делал перед сном». Если лёг/встал дальше ±30 мин от
   режима (Настройки → Общее), день считается «режим сбит» —
   так пользователь видит, что регулярность влияет на качество.
============================================================ */
const SLEEP_RATING_EMOJI = ['', '😫', '🙁', '😐', '🙂', '🚀'];
const SLEEP_RATING_LABEL = ['', 'ужасно', 'плохо', 'нормально', 'хорошо', 'отлично'];

let sleepDialogDraft = { rating: null, tags: [] };

function renderSleepDialogControls() {
  if (typeof document === 'undefined') return;
  $$('#sleep-rating-row [data-sleep-rating]').forEach((btn) => {
    const r = Number(btn.dataset.sleepRating);
    btn.classList.toggle('active', r === sleepDialogDraft.rating);
    btn.setAttribute('aria-pressed', String(r === sleepDialogDraft.rating));
  });
  $$('#sleep-tags [data-sleep-tag]').forEach((chip) => {
    const on = sleepDialogDraft.tags.includes(chip.dataset.sleepTag);
    chip.classList.toggle('active', on);
    chip.setAttribute('aria-pressed', String(on));
  });
}

function renderSleepDialogSummary() {
  if (typeof document === 'undefined') return;
  const el = $('#sleep-summary');
  if (!el) return;
  const s = getSleepCheckinSummary(7);
  if (!s) {
    el.textContent = 'Это будет ваша первая отметка сна. Через неделю здесь появится средняя длительность и оценка.';
    return;
  }
  const parts = [`за 7 дней отмечено ночей: ${s.nights}`];
  if (s.avgDurationMin != null) parts.push(`средний сон: ${formatWorkoutDuration(s.avgDurationMin)}`);
  if (s.avgRating != null) parts.push(`оценка ${s.avgRating}/5`);
  if (s.scheduleTotal > 0) parts.push(`режим соблюдён ${s.onScheduleCount} из ${s.scheduleTotal}`);
  el.textContent = '📈 ' + parts.join(' · ') + '.';
}

function openSleepCheckinDialog() {
  const dialog = $('#sleep-checkin-dialog');
  if (!dialog) return;
  const entry = getTodaySleepEntry();
  sleepDialogDraft = { rating: entry ? entry.rating : null, tags: entry ? entry.tags.slice() : [] };
  const bedInput = $('#sleep-bed-input');
  const wakeInput = $('#sleep-wake-input');
  if (bedInput) bedInput.value = (entry && entry.bedTime) || '';
  if (wakeInput) wakeInput.value = (entry && entry.wakeTime) || '';
  const extra = $('#sleep-extra');
  const extraToggle = $('#sleep-extra-toggle');
  // Если поля уже заполнены (правка записи) — доп-блок раскрыт сразу.
  const hasDetails = !!(entry && (entry.bedTime || entry.wakeTime || (entry.tags && entry.tags.length)));
  if (extra) extra.hidden = !hasDetails;
  if (extraToggle) extraToggle.setAttribute('aria-expanded', String(hasDetails));
  renderSleepDialogControls();
  renderSleepDialogSummary();
  dialog.hidden = false;
}

function closeSleepCheckinDialog() {
  const dialog = $('#sleep-checkin-dialog');
  if (dialog) dialog.hidden = true;
}

/* Сохранение записи сна за сегодня (upsert по дате). */
function saveSleepCheckinDialog() {
  const sc = state.sleepCheckin;
  const bedTime = ($('#sleep-bed-input') && $('#sleep-bed-input').value) || sc.targetBed;
  const wakeTime = ($('#sleep-wake-input') && $('#sleep-wake-input').value) || sc.targetWake;
  const hasTimes = !!(sleepTimeToMinutes($('#sleep-bed-input') && $('#sleep-bed-input').value)
    || sleepTimeToMinutes($('#sleep-wake-input') && $('#sleep-wake-input').value));
  // Пользователь заполнил только одно время — второе берём из режима, так честнее, чем терять пару.
  const effectiveBed = sleepTimeToMinutes(bedTime) != null ? bedTime : sc.targetBed;
  const effectiveWake = sleepTimeToMinutes(wakeTime) != null ? wakeTime : sc.targetWake;
  const useTimes = hasTimes || !!getTodaySleepEntry();
  const entry = {
    id: (getTodaySleepEntry() || {}).id || uid(),
    date: todayKey(),
    rating: sleepDialogDraft.rating,
    bedTime: useTimes ? effectiveBed : null,
    wakeTime: useTimes ? effectiveWake : null,
    tags: sleepDialogDraft.tags.slice(0, 6),
    createdAt: (getTodaySleepEntry() || {}).createdAt || Date.now()
  };
  entry.durationMin = computeSleepDurationMin(entry.bedTime, entry.wakeTime);
  entry.onSchedule = evaluateSleepOnSchedule(entry.bedTime, entry.wakeTime, sc.targetBed, sc.targetWake);
  const idx = sc.log.findIndex((e) => e.date === entry.date);
  if (idx >= 0) sc.log[idx] = entry; else sc.log.push(entry);
  sc.log.sort((a, b) => a.date.localeCompare(b.date));
  sc.skipped = null;
  saveState();
  closeSleepCheckinDialog();
  renderDayChecklist();
  if (typeof renderStats === 'function') renderStats();
  const bits = [];
  if (entry.durationMin != null) bits.push(formatWorkoutDuration(entry.durationMin));
  if (entry.rating != null) bits.push(`оценка ${entry.rating}/5 (${SLEEP_RATING_LABEL[entry.rating]})`);
  if (entry.onSchedule === true) bits.push('в режиме ✓');
  else if (entry.onSchedule === false) bits.push('режим сбит (±30 мин от цели)');
  toast('😴 Сон записан' + (bits.length ? ': ' + bits.join(' · ') : ''));
}

function skipSleepCheckin() {
  state.sleepCheckin.skipped = todayKey();
  saveState();
  closeSleepCheckinDialog();
}

/* Утренний автопоказ: включён чек-ин, время 05:00–12:00, записи за сегодня
   нет, сегодня не нажимали «Позже», условия приняты и нет открытых диалогов. */
function maybeShowSleepCheckin() {
  if (!state.sleepCheckin || !state.sleepCheckin.enabled) return;
  if (!isSleepWindowNow(new Date(), state.sleepCheckin.windowStart, state.sleepCheckin.windowEnd)) return;
  if (getTodaySleepEntry() || state.sleepCheckin.skipped === todayKey()) return;
  if (!hasAcceptedTerms()) return;
  if ($$('.app-dialog-backdrop').some((el) => !el.hidden)) return;
  openSleepCheckinDialog();
}

function renderSleepCheckinSettings() {
  if (typeof document === 'undefined') return;
  const toggle = $('#sleep-checkin-toggle');
  const status = $('#sleep-checkin-status');
  const targets = $('#sleep-targets-row');
  const windowRow = $('#sleep-window-row');
  if (!toggle || !status) return;
  const sc = state.sleepCheckin;
  toggle.checked = sc.enabled;
  if (targets) targets.hidden = !sc.enabled;
  if (windowRow) windowRow.hidden = !sc.enabled;
  const bedInput = $('#sleep-target-bed');
  const wakeInput = $('#sleep-target-wake');
  const winStartInput = $('#sleep-window-start');
  const winEndInput = $('#sleep-window-end');
  if (bedInput && document.activeElement !== bedInput) bedInput.value = sc.targetBed;
  if (wakeInput && document.activeElement !== wakeInput) wakeInput.value = sc.targetWake;
  if (winStartInput && document.activeElement !== winStartInput) winStartInput.value = sc.windowStart;
  if (winEndInput && document.activeElement !== winEndInput) winEndInput.value = sc.windowEnd;
  status.textContent = sc.enabled
    ? `Один раз за утро (окно ${sc.windowStart}–${sc.windowEnd}, можно изменить ниже) приложение спросит про сон: оценка в 1 тап, время и «что было перед сном» — по желанию. Режим: отбой ${sc.targetBed}, подъём ${sc.targetWake} — отклонение больше 30 мин отметим как «режим сбит».`
    : 'Чек-ин сна выключен.';
}

function updateSleepCheckinEnabled(enabled) {
  state.sleepCheckin.enabled = enabled;
  saveState();
  renderSleepCheckinSettings();
  renderDayChecklist();
  toast(enabled ? '😴 Чек-ин сна включён — спрошу утром' : 'Чек-ин сна выключен');
}

function saveSleepTargets() {
  const sc = state.sleepCheckin;
  const bed = $('#sleep-target-bed');
  const wake = $('#sleep-target-wake');
  if (bed && sleepTimeToMinutes(bed.value) != null) sc.targetBed = bed.value;
  if (wake && sleepTimeToMinutes(wake.value) != null) sc.targetWake = wake.value;
  saveState();
  renderSleepCheckinSettings();
}

/* Окно показа утреннего диалога сна. Совпавшие границы («с» = «до») отклоняем:
   по логике isSleepWindowNow это «окна нет», но хранить такой мусор не стоит. */
function saveSleepWindow() {
  const sc = state.sleepCheckin;
  const start = $('#sleep-window-start');
  const end = $('#sleep-window-end');
  const sv = start ? String(start.value || '') : '';
  const ev = end ? String(end.value || '') : '';
  if (sleepTimeToMinutes(sv) != null && sleepTimeToMinutes(ev) != null && sv !== ev) {
    sc.windowStart = sv;
    sc.windowEnd = ev;
    saveState();
  }
  renderSleepCheckinSettings();
}

/* Рекорды по истории dailyHistory + сегодняшний день. */
function computeGameRecords() {
  const history = (Array.isArray(state.dailyHistory) ? state.dailyHistory : []).slice();
  const today = currentDaySummary();
  const idx = history.findIndex((d) => d.date === today.date);
  if (idx >= 0) history[idx] = today; else history.push(today);
  const days = history
    .filter((d) => d && d.date)
    .sort((a, b) => a.date.localeCompare(b.date));
  const nonEmpty = days.filter((d) => d.waterTotal > 0 || d.foodTotal > 0 || d.activityMinutes > 0);
  const isVictory = (d) => d.waterTotal > 0 && d.waterGoal > 0 && d.waterTotal >= d.waterGoal
    && d.activityMinutes >= 30 && d.foodTotal > 0;

  let maxWater = null;
  let maxActivity = null;
  days.forEach((d) => {
    if (d.waterTotal > 0 && (!maxWater || d.waterTotal > maxWater.value)) maxWater = { value: d.waterTotal, date: d.date };
    if (d.activityMinutes > 0 && (!maxActivity || d.activityMinutes > maxActivity.value)) maxActivity = { value: d.activityMinutes, date: d.date };
  });

  let bestStreak = 0;
  let run = 0;
  days.forEach((d) => { run = isVictory(d) ? run + 1 : 0; if (run > bestStreak) bestStreak = run; });
  let currentStreak = 0;
  for (let i = days.length - 1; i >= 0; i--) {
    if (isVictory(days[i])) currentStreak++;
    else if (days[i].date !== today.date) break; // сегодня может быть ещё «в процессе» — серию не рвём
    else continue;
  }

  return { nonEmptyDays: nonEmpty.length, maxWater, maxActivity, bestStreak, currentStreak };
}

/* ============================================================
   Медали: полный список достижений (экран «Медали»).
   Бег и шаги — ЧЕСТНЫЕ ОЦЕНКИ из минут активности (шагомера в
   приложении нет): бег ≈ 0,15 км/мин (9 км/ч), ходьба ≈ 100
   шагов/мин — такие медали помечены знаком ≈ и подписью «по оценке».
   Снижение веса считается по истории взвешиваний профиля.
============================================================ */
const GAME_RUN_KM_PER_MIN = 0.15;
const GAME_STEPS_PER_MIN = 100;

/* «Марафонец» — только бег: лучший день по суммарным минутам КАРДИО.
   Силовая, прогулка и прочие виды не считаются (замечание пользователя:
   час силовой не должен давать беговую медаль). Аргумент позволяет
   тестировать чисто: computeMaxCardioDayMinutes(workouts). */
function computeMaxCardioDayMinutes(workouts) {
  const list = Array.isArray(workouts) ? workouts
    : (Array.isArray(state.workouts) ? state.workouts : []);
  const byDay = new Map();
  list.forEach((w) => {
    if (!w || w.type !== 'cardio' || !w.date) return;
    byDay.set(w.date, (byDay.get(w.date) || 0) + (Number(w.durationMinutes) || 0));
  });
  const max = { value: 0, date: null };
  byDay.forEach((value, date) => { if (value > max.value) max.value = value, max.date = date; });
  return max;
}

function computeRunKmTotal() {
  return (Array.isArray(state.workouts) ? state.workouts : [])
    .filter((w) => w.type === 'cardio')
    .reduce((sum, w) => sum + (Number(w.durationMinutes) || 0), 0) * GAME_RUN_KM_PER_MIN;
}

function computeStepsTotal() {
  return (Array.isArray(state.workouts) ? state.workouts : [])
    .filter((w) => w.type === 'walk')
    .reduce((sum, w) => sum + (Number(w.durationMinutes) || 0), 0) * GAME_STEPS_PER_MIN;
}

function computeWeightLostKg() {
  const history = normalizeWeightHistory(state.profileSettings && state.profileSettings.weightHistory);
  if (history.length < 2) return 0;
  const maxStart = history.reduce((m, h) => Math.max(m, h.kg), 0);
  const last = history[history.length - 1].kg;
  return Math.max(0, Math.round((maxStart - last) * 10) / 10);
}

/* Единый SVG-значок медали: цифра/цель — часть самого значка.
   Заработанная — «золотая», закрытая — приглушённая. */
function medalBadgeSvg(medal) {
  const gid = `mg-${medal.id}`.replace(/[^a-z0-9-]/gi, '');
  const [c1, c2, line] = medal.earned
    ? ['#ffd76a', '#e8a020', 'rgba(255,255,255,0.65)']
    : ['#9aa4b2', '#6b7280', 'rgba(255,255,255,0.35)'];
  return `<svg viewBox="0 0 72 92" class="medal-badge-svg" aria-hidden="true">
    <defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/>
    </linearGradient></defs>
    <path d="M24 2h9l3 10 3-10h9l-12 20z" fill="${medal.earned ? '#e05252' : '#8a93a1'}"/>
    <circle cx="36" cy="56" r="30" fill="url(#${gid})"/>
    <circle cx="36" cy="56" r="23" fill="none" stroke="${line}" stroke-width="1.6" stroke-dasharray="4 3"/>
    <text x="36" y="61" text-anchor="middle" font-size="15" font-weight="800" fill="#fff" font-family="inherit">${medal.badgeText}</text>
  </svg>`;
}

function computeGameMedals() {
  const r = computeGameRecords();
  const waterGoal = Number(state.water.goal) || DEFAULTS.water.goal;
  const fmtDate = (d) => d.split('-').reverse().join('.');
  const runKm = Math.round(computeRunKmTotal() * 10) / 10;
  const steps = Math.round(computeStepsTotal());
  const lostKg = computeWeightLostKg();
  const cardioDay = computeMaxCardioDayMinutes();

  const habits = [
    {
      id: 'first-day', badgeText: '1', name: 'Первый шаг', earned: r.nonEmptyDays >= 1,
      desc: r.nonEmptyDays >= 1 ? `Заполнено дней: ${r.nonEmptyDays}` : 'Заполните первый день (вода, еда или активность)',
      cur: Math.min(1, r.nonEmptyDays), target: 1
    },
    {
      id: 'water-day', badgeText: '💧', name: 'Водная волна', earned: !!(r.maxWater && r.maxWater.value >= waterGoal),
      desc: r.maxWater
        ? `Рекорд воды за день: ${fmt(r.maxWater.value)} мл (${fmtDate(r.maxWater.date)})` + (r.maxWater.value >= waterGoal ? ' — норма выполнена!' : ` — до нормы ${fmt(waterGoal)} мл`)
        : 'Рекорд воды появится, когда вы отметите первый стакан',
      cur: r.maxWater ? r.maxWater.value : 0, target: waterGoal
    },
    {
      id: 'marathon-day', badgeText: '60', name: 'Марафонец', earned: cardioDay.value >= 60,
      desc: cardioDay.value > 0
        ? `Лучший день бега (кардио): ${cardioDay.value} мин (${fmtDate(cardioDay.date)})` + (cardioDay.value >= 60 ? ' — больше часа бега за день!' : ` — до медали ещё ${fmt(60 - cardioDay.value)} мин бега`)
        : 'День с 60+ минутами бега. Учитывается только бег (кардио) — силовая, прогулка и другие виды не считаются',
      cur: cardioDay.value, target: 60
    },
    {
      id: 'streak-3', badgeText: '×3', name: 'Горячая серия', earned: r.bestStreak >= 3,
      desc: r.bestStreak > 0
        ? `Лучшая серия полных дней: ${r.bestStreak} дн.` + (r.currentStreak > 0 ? ` Сейчас: ${r.currentStreak} дн. подряд` : '')
        : 'Выполните все 3 задания 3 дня подряд',
      cur: Math.min(3, r.bestStreak), target: 3
    },
    {
      id: 'streak-7', badgeText: '×7', name: 'Неделя героя', earned: r.bestStreak >= 7,
      desc: r.bestStreak >= 7 ? `Невероятно: ${r.bestStreak} дн. подряд все задания!` : '7 дней подряд со всеми заданиями дня',
      cur: Math.min(7, r.bestStreak), target: 7
    }
  ];

  const runMedals = [1, 5, 10, 25].map((km) => ({
    id: `run-${km}`, badgeText: `${km}`, name: `Пробежка: первые ${km} км`, earned: runKm >= km, estimate: true,
    desc: runKm >= km
      ? `Суммарно пробежано ≈ ${runKm} км (оценка по минутам бега)`
      : `Пробежано ≈ ${runKm} из ${km} км (оценка: минуты бега × ${GAME_RUN_KM_PER_MIN} км)`,
    cur: runKm, target: km
  }));

  const stepMedals = [10000, 50000, 100000].map((s) => ({
    id: `steps-${s}`, badgeText: s >= 100000 ? '100К' : `${Math.round(s / 1000)}К`, name: `Пройдено ${fmt(s)} шагов`, earned: steps >= s, estimate: true,
    desc: steps >= s
      ? `Суммарно пройдено ≈ ${fmt(steps)} шагов (оценка по минутам ходьбы)`
      : `Пройдено ≈ ${fmt(steps)} из ${fmt(s)} шагов (оценка: минуты ходьбы × ${GAME_STEPS_PER_MIN})`,
    cur: steps, target: s
  }));

  const weightMedals = [1, 3, 5, 10].map((kg) => ({
    id: `weight-${kg}`, badgeText: `−${kg}`, name: `Сброшено ${kg} кг`, earned: lostKg >= kg,
    desc: lostKg >= kg
      ? `Вес снижен на ${lostKg} кг от максимального — отличная работа!`
      : `Сейчас снижение: ${lostKg} из ${kg} кг (по истории взвешиваний)`,
    cur: lostKg, target: kg
  }));

  // 0.8.6: силовые уровни — карточка на упражнение (лестница порогов).
  const strengthMedals = (computeStrengthRecords(state.strengthSessions) || [])
    .slice(0, 8)
    .map((r) => {
      const lvl = computeStrengthLevel(r.name, r.best1RM);
      return {
        id: 'str-' + r.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 40),
        badgeText: lvl.level >= 1 ? 'Lv' + lvl.level : fmt(lvl.nextTarget),
        name: r.name,
        earned: lvl.level >= 1,
        desc: lvl.level >= 1
          ? `Уровень ${lvl.level} · 1RM ≈ ${fmt(r.best1RM)} кг · до следующего ${fmt(lvl.nextTarget)} кг`
          : `1RM ≈ ${fmt(r.best1RM)} кг · первый уровень с ${fmt(lvl.nextTarget)} кг (осталось ${fmt(lvl.nextDelta)} кг)`,
        cur: r.best1RM, target: lvl.nextTarget
      };
    });
  if (!strengthMedals.length) {
    strengthMedals.push({
      id: 'str-empty', badgeText: '🏋️', name: 'Силовые уровни', earned: false,
      desc: 'Начните дневник силовых (вес × повторы) — появятся уровни по упражнениям',
      cur: 0, target: 1
    });
  }

  return [
    { id: 'habits', title: 'Привычки', hint: 'За регулярные записи и полные дни', medals: habits },
    { id: 'run', title: '🏃 Бег (по оценке)', hint: 'Километры считаются из минут бега: расстояние не измеряется напрямую', medals: runMedals },
    { id: 'steps', title: '👟 Шаги (по оценке)', hint: 'Шаги считаются из минут ходьбы: ≈100 шагов за минуту', medals: stepMedals },
    { id: 'weight', title: WEIGHT_SCALE_SVG_SM + ' Снижение веса', hint: 'Разница между максимальным и текущим весом в истории профиля', medals: weightMedals },
    { id: 'strength', title: '🏋️ Сила (уровни)', hint: 'Бета: уровни считаются по расчётному 1RM, а не по реальному максимуму — это шкала для сравнения с собой, а не норматив', medals: strengthMedals }
  ];
}

function renderGameMedalsView() {
  if (typeof document === 'undefined') return;
  const grid = $('#game-medals-grid');
  if (!grid) return;
  const groups = computeGameMedals();
  const totalEarned = groups.reduce((s, g) => s + g.medals.filter((m) => m.earned).length, 0);
  const totalCount = groups.reduce((s, g) => s + g.medals.length, 0);
  const counter = $('#game-medals-count');
  if (counter) counter.textContent = `Получено ${totalEarned} из ${totalCount}`;
  grid.innerHTML = groups.map((group) => `
    <p class="settings-label game-medals-group-title">${group.title}</p>
    <p class="settings-hint game-medals-group-hint">${group.hint}</p>
    <div class="game-medals-row">
      ${group.medals.map((m) => {
        const pct = Math.min(100, Math.round((Number(m.cur) || 0) / Math.max(1, Number(m.target) || 1) * 100));
        return `<div class="medal-tile${m.earned ? ' earned' : ' locked'}">
          ${medalBadgeSvg(m)}
          <div class="medal-tile-name">${m.name}</div>
          <div class="medal-tile-desc">${m.estimate ? '≈ ' : ''}${m.desc}</div>
          ${m.earned ? '' : `<div class="medal-tile-bar"><span style="width:${pct}%"></span></div>`}
        </div>`;
      }).join('')}
    </div>`).join('');
}

/* Сравнение текущего периода (7/30 дней) с предыдущим таким же — только
   при включённом игровом режиме и при наличии данных обоих периодов. */
function renderStatsCompare() {
  if (typeof document === 'undefined') return;
  const section = $('#stats-compare-section');
  if (!section) return;
  const period = activeStatsPeriod;
  const show = state.gameMode.enabled && period !== 'day';
  section.hidden = !show;
  if (!show) return;

  const count = statsPeriodDays(period);
  const historyByDate = new Map((Array.isArray(state.dailyHistory) ? state.dailyHistory : [])
    .map((day) => [day.date, day]));
  const blank = (date) => ({ date, waterTotal: 0, waterGoal: DEFAULTS.water.goal, foodTotal: 0, foodGoal: DEFAULTS.food.goal, activityMinutes: 0 });
  const prev = [];
  for (let offset = count * 2 - 1; offset >= count; offset--) {
    const date = statsDateKey(offset);
    prev.push(historyByDate.get(date) || blank(date));
  }
  const cur = getStatsDays(period);
  const sum = (days, key) => days.reduce((s, d) => s + (Number(d[key]) || 0), 0);
  const prevHasData = prev.some((d) => d.waterTotal > 0 || d.foodTotal > 0 || d.activityMinutes > 0);
  if (!prevHasData) {
    section.hidden = false;
    $('#stats-compare-text').textContent = 'Прошлый период пока пуст — сравнение появится, когда вы позаписываете дни подряд.';
    $('#stats-compare-motivation').textContent = '';
    return;
  }

  const pct = (curV, prevV) => (prevV > 0 ? Math.round(((curV - prevV) / prevV) * 100) : (curV > 0 ? 100 : 0));
  const arrow = (p) => (p > 4 ? `▲ +${p}%` : (p < -4 ? `▼ −${Math.abs(p)}%` : '≈ без изменений'));
  const rows = [
    { emoji: '💧', label: 'вода', cur: sum(cur, 'waterTotal'), prev: sum(prev, 'waterTotal'), unit: 'мл' },
    { emoji: '🍽️', label: 'калории', cur: sum(cur, 'foodTotal'), prev: sum(prev, 'foodTotal'), unit: 'ккал' },
    { emoji: '🏃', label: 'активность', cur: sum(cur, 'activityMinutes'), prev: sum(prev, 'activityMinutes'), unit: 'мин' }
  ];
  $('#stats-compare-text').innerHTML = rows.map((row) => {
    const p = pct(row.cur, row.prev);
    return `${row.emoji} ${row.label}: <b>${fmt(row.cur)}</b> ${row.unit} против ${fmt(row.prev)} ${row.unit} — <b>${arrow(p)}</b>`;
  }).join('<br>');

  // Вода и активность «больше — лучше»; для калорий сравниваем ровность попадания в цель.
  const betterCount = rows.filter((row) => pct(row.cur, row.prev) > 4).length;
  const worseCount = rows.filter((row) => pct(row.cur, row.prev) < -4).length;
  const motivation = betterCount === 3
    ? `В этом ${period === 'month' ? 'месяце' : 'периоде'} вы эффективнее прошлого по всем направлениям — так держать! 💪`
    : betterCount > worseCount
      ? `Прогресс по ${betterCount} из 3 направлений — движение в правильную сторону!`
      : worseCount > betterCount
        ? 'Этот период честно слабее прошлого — начните с малого: один стакан воды прямо сейчас 💧'
        : 'Периоды идут вровень — ровность тоже результат ✊';
  $('#stats-compare-motivation').textContent = motivation;
}

function saveDayMood(rating) {
  state.dayMood = { date: todayKey(), rating };
  saveState();
  renderDayChecklist();
  renderStats();
  toast(`Самочувствие: ${rating}/5 сохранено`);
}

function getMoodCorrelations() {
  const history = Array.isArray(state.dailyHistory) ? [...state.dailyHistory] : [];
  const today = currentDaySummary();
  const todayMood = getTodayMood();
  if (todayMood) {
    history.unshift({ ...today, mood: todayMood });
  }
  history.sort((a, b) => b.date.localeCompare(a.date));

  const rated = history.filter((d) => d.mood != null && d.mood >= 1);
  if (rated.length < 3) return null;

  const waterThreshold = DEFAULTS.water.goal;
  const goodWater = rated.filter((d) => (d.waterTotal || 0) >= (d.waterGoal || waterThreshold));
  const badWater = rated.filter((d) => (d.waterTotal || 0) < (d.waterGoal || waterThreshold));
  const goodActivity = rated.filter((d) => (d.activityMinutes || 0) > 0);
  const badActivity = rated.filter((d) => (d.activityMinutes || 0) === 0);

  const avg = (arr) => arr.length ? Math.round(arr.reduce((s, d) => s + d.mood, 0) / arr.length * 10) / 10 : null;
  const perc = (arr, threshold) => arr.length ? Math.round(arr.filter((d) => d.mood >= threshold).length / arr.length * 100) : null;

  return {
    total: rated.length,
    avg: avg(rated),
    waterAvg: { good: avg(goodWater), bad: avg(badWater) },
    waterGood4: perc(goodWater, 4),
    waterBad4: perc(badWater, 4),
    activityAvg: { good: avg(goodActivity), bad: avg(badActivity) },
    activityGood4: perc(goodActivity, 4),
    activityBad4: perc(badActivity, 4),
  };
}

function renderMoodCorrelations() {
  if (typeof document === 'undefined') return;
  const el = $('#stats-mood');
  if (!el) return;
  const corr = getMoodCorrelations();
  if (!corr) { el.innerHTML = ''; return; }
  const fmtAvg = (v) => v != null ? String(v).replace('.', ',') : '—';
  const fmtPct = (v) => v != null ? v + '%' : '—';
  el.innerHTML = '<section class="stats-section stats-mood" aria-labelledby="stats-mood-title"><h3 id="stats-mood-title">📊 Связь привычек и настроения</h3><p>На основе ' + corr.total + ' дней с оценкой. Среднее: ' + fmtAvg(corr.avg) + '/5.</p>' +
    (corr.waterAvg.good != null || corr.waterAvg.bad != null ? '<p>💧 Вода: <span class="mood-correlation good">с водой ' + fmtAvg(corr.waterAvg.good) + '/5</span> <span class="mood-correlation bad">без воды ' + fmtAvg(corr.waterAvg.bad) + '/5</span> · 4–5 баллов: ' + fmtPct(corr.waterGood4) + ' с водой vs ' + fmtPct(corr.waterBad4) + ' без</p>' : '') +
    (corr.activityAvg.good != null || corr.activityAvg.bad != null ? '<p>🌿 Активность: <span class="mood-correlation good">с активностью ' + fmtAvg(corr.activityAvg.good) + '/5</span> <span class="mood-correlation bad">без ' + fmtAvg(corr.activityAvg.bad) + '/5</span> · 4–5 баллов: ' + fmtPct(corr.activityGood4) + ' с активностью vs ' + fmtPct(corr.activityBad4) + ' без</p>' : '') +
    '</section>';
}
function renderWeightSettings() {
  const current = $('#weight-current');
  const dateInput = $('#weight-history-date');
  const weightInput = $('#weight-history-input');
  const list = $('#weight-history-list');
  if (!current || !dateInput || !weightInput || !list) return;
  const history = normalizeWeightHistory(state.profileSettings.weightHistory);
  const currentWeight = state.profileSettings.weightKg;
  current.textContent = currentWeight ? `Текущий вес: ${Number(currentWeight).toLocaleString('ru-RU')} кг` : 'Вес пока не записан';
  if (document.activeElement !== weightInput) weightInput.value = currentWeight || '';
  if (!dateInput.value) dateInput.value = todayKey();

  const periodHistory = getWeightHistoryForPeriod();
  renderWeightChart(periodHistory);
  const first = periodHistory[0];
  const last = periodHistory[periodHistory.length - 1];
  const hint = $('#weight-history-hint');
  if (hint) {
    if (!last) hint.textContent = 'Запишите вес, чтобы увидеть историю и график этого профиля.';
    else if (periodHistory.length === 1) hint.textContent = `${formatWeightDate(last.date)} · ${Number(last.weightKg).toLocaleString('ru-RU')} кг. Добавьте следующую запись для динамики.`;
    else {
      const delta = Math.round((last.weightKg - first.weightKg) * 10) / 10;
      const sign = delta > 0 ? '+' : '';
      hint.textContent = `Изменение за период: ${sign}${Number(delta).toLocaleString('ru-RU')} кг · последняя запись ${formatWeightDate(last.date)}.`;
    }
  }
  $$('#weight-periods button').forEach((button) => button.classList.toggle('active', button.dataset.weightPeriod === activeWeightPeriod));
  list.innerHTML = history.slice().reverse().slice(0, 12).map((entry) => `
    <li><span>${escapeHtml(formatWeightDate(entry.date))}</span><strong>${Number(entry.weightKg).toLocaleString('ru-RU')} кг</strong><button type="button" class="weight-edit-btn" data-edit-weight="${entry.date}" aria-label="Изменить запись веса за ${escapeHtml(formatWeightDate(entry.date))}">✏️</button><button type="button" data-remove-weight="${entry.date}" aria-label="Удалить запись веса за ${escapeHtml(formatWeightDate(entry.date))}">×</button></li>`).join('') || '<li class="weight-history-empty">Записей веса пока нет.</li>';
}

function renderWeightOverview() {
  const history = normalizeWeightHistory(state.profileSettings.weightHistory);
  const currentWeight = state.profileSettings.weightKg;
  const latest = history[history.length - 1];
  const shownWeight = currentWeight || (latest ? latest.weightKg : null);
  const first = history[0];
  const delta = first && latest && history.length > 1 ? Math.round((latest.weightKg - first.weightKg) * 10) / 10 : null;
  const deltaText = delta == null ? 'Записей веса пока нет' : `Изменение за всё время: ${delta > 0 ? '+' : ''}${Number(delta).toLocaleString('ru-RU')} кг`;

  const homeCurrent = $('#home-weight-current');
  const homeTrend = $('#home-weight-trend');
  if (homeCurrent) homeCurrent.textContent = shownWeight ? `${Number(shownWeight).toLocaleString('ru-RU')} кг` : '—';
  if (homeTrend) homeTrend.textContent = latest
    ? (delta == null ? `Последняя запись: ${formatWeightDate(latest.date)}` : deltaText)
    : 'Записей веса пока нет';

  const statsTotal = $('#stats-weight-total');
  const statsHint = $('#stats-weight-hint');
  if (statsTotal) statsTotal.textContent = shownWeight ? `${Number(shownWeight).toLocaleString('ru-RU')} кг` : '—';
  // 0.4.15 (аудит А3): крупная дельта за 30 дней — самый читаемый показатель.
  const cutoff30 = new Date(); cutoff30.setDate(cutoff30.getDate() - 30);
  const key30 = `${cutoff30.getFullYear()}-${String(cutoff30.getMonth() + 1).padStart(2, '0')}-${String(cutoff30.getDate()).padStart(2, '0')}`;
  const base30 = history.filter((entry) => entry.date >= key30)[0];
  const d30 = (base30 && latest && base30.date !== latest.date) ? Math.round((latest.weightKg - base30.weightKg) * 10) / 10 : null;
  const d30Text = d30 == null ? '' : ' · 30 дн: ' + (d30 > 0 ? '+' : '') + Number(d30).toLocaleString('ru-RU') + ' кг';
  if (statsHint) statsHint.textContent = latest
    ? (delta == null ? `Последняя запись: ${formatWeightDate(latest.date)}` : `${deltaText} · ${history.length} зап.${d30Text}`)
    : 'Добавьте запись веса на Главной или откройте подробный график.';
}

function openQuickWeightDialog() {
  $('#weight-quick-date').value = todayKey();
  $('#weight-quick-input').value = state.profileSettings.weightKg || '';
  $('#weight-quick-dialog').hidden = false;
  setTimeout(() => $('#weight-quick-input').focus(), 100);
}
function closeQuickWeightDialog() { $('#weight-quick-dialog').hidden = true; }
function saveQuickWeight() {
  const date = $('#weight-quick-date').value;
  const weight = Number(String($('#weight-quick-input').value).replace(',', '.'));
  if (!saveWeightRecord(date, weight)) return;
  closeQuickWeightDialog();
  toast(date === todayKey() ? 'Вес за сегодня сохранён' : 'Историческая запись веса сохранена');
}

/* ============================================================
   0.5.0 «Доверие данным»: редактирование записей, дни задним
   числом и системная отмена. Принципы: даты — не позже сегодня;
   пустое поле диалога дня = «без изменений»; отмена возвращает
   ровно то состояние, что было до операции.
   ============================================================ */

let undoSnackTimer = null;
let undoSnackRestore = null;

function hideUndoSnack() {
  if (typeof document === 'undefined') return;
  const el = $('#undo-snackbar');
  if (!el) return;
  el.classList.remove('show');
  el.hidden = true;
  undoSnackRestore = null;
  clearTimeout(undoSnackTimer);
}

function showUndoSnack(message, restore) {
  if (typeof document === 'undefined') return;
  const el = $('#undo-snackbar');
  if (!el) return;
  $('#undo-snackbar-text').textContent = message;
  undoSnackRestore = typeof restore === 'function' ? restore : null;
  el.hidden = false;
  el.classList.add('show');
  clearTimeout(undoSnackTimer);
  undoSnackTimer = setTimeout(hideUndoSnack, 6500);
}

function validPastOrTodayDate(date) {
  return typeof date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(date) && date <= todayKey();
}

/* recordDailySummary(pastDate) занизил бы воду/еду прошлого дня нулями (живые
   журналы есть только у «сегодня») — поэтому прошлые сводки правим точечно.
   Минуты активности читаются из журнала тренировок, они правдивы всегда. */
function syncPastDaySummary(date) {
  if (!validPastOrTodayDate(date) || date === todayKey()) return;
  const minutes = activityMinutesForDate(date);
  const history = Array.isArray(state.dailyHistory) ? state.dailyHistory : [];
  const index = history.findIndex((day) => day.date === date);
  if (index >= 0) {
    history[index].activityMinutes = minutes;
  } else if (minutes > 0) {
    history.push({ date, waterTotal: 0, waterGoal: DEFAULTS.water.goal, foodTotal: 0, foodGoal: DEFAULTS.food.goal, foodP: 0, foodF: 0, foodC: 0, activityMinutes: minutes });
  }
  state.dailyHistory = history;
  normalizeDailyHistory();
}

function openFoodEditDialog(id) {
  const item = state.food.items.find((it) => it.id === id);
  if (!item) return;
  $('#food-edit-id').value = item.id;
  $('#food-edit-name').value = item.name || '';
  $('#food-edit-kcal').value = Math.round(Number(item.kcal) || 0);
  $('#food-edit-p').value = item.p || '';
  $('#food-edit-f').value = item.f || '';
  $('#food-edit-c').value = item.c || '';
  $('#food-edit-dialog').hidden = false;
  setTimeout(() => $('#food-edit-name').focus(), 100);
}
function closeFoodEditDialog() { $('#food-edit-dialog').hidden = true; }

function saveFoodEdit() {
  const id = $('#food-edit-id').value;
  const item = state.food.items.find((it) => it.id === id);
  if (!item) { closeFoodEditDialog(); return; }
  const name = String($('#food-edit-name').value || '').trim().slice(0, 80);
  const kcal = Math.round(Number(String($('#food-edit-kcal').value).replace(',', '.')));
  if (!name) { toast('Название не должно быть пустым'); return; }
  if (!Number.isFinite(kcal) || kcal < 0 || kcal > 5000) { toast('Калории: от 0 до 5000'); return; }
  const macro = (selector, max) => {
    const raw = String($(selector).value || '').trim();
    if (raw === '') return 0;
    const num = Number(raw.replace(',', '.'));
    return Number.isFinite(num) ? Math.min(max, Math.max(0, Math.round(num * 10) / 10)) : 0;
  };
  item.name = name;
  item.kcal = kcal;
  item.p = macro('#food-edit-p', 500);
  item.f = macro('#food-edit-f', 500);
  item.c = macro('#food-edit-c', 800);
  item.editedAt = Date.now();
  saveState();
  renderFood();
  closeFoodEditDialog();
  toast('Запись питания изменена');
}

function openWorkoutEditDialog(id) {
  const workout = (Array.isArray(state.workouts) ? state.workouts : []).find((w) => w.id === id);
  if (!workout) return;
  const select = $('#workout-edit-type');
  select.innerHTML = Object.entries(ACTIVITY_TYPES).map(([key, t]) =>
    `<option value="${key}"${key === workout.type ? ' selected' : ''}>${t.emoji} ${t.label}</option>`).join('');
  $('#workout-edit-id').value = workout.id;
  $('#workout-edit-minutes').value = workout.durationMinutes;
  const dateInput = $('#workout-edit-date');
  dateInput.max = todayKey();
  dateInput.value = workout.date;
  $('#workout-edit-note').value = workout.note || '';
  $('#workout-edit-dialog').hidden = false;
  setTimeout(() => $('#workout-edit-minutes').focus(), 100);
}
function closeWorkoutEditDialog() { $('#workout-edit-dialog').hidden = true; }

async function saveWorkoutEdit() {
  const id = $('#workout-edit-id').value;
  const workout = (Array.isArray(state.workouts) ? state.workouts : []).find((w) => w.id === id);
  if (!workout) { closeWorkoutEditDialog(); return; }
  const minutes = Math.round(Number(String($('#workout-edit-minutes').value).replace(',', '.')));
  if (!Number.isFinite(minutes) || minutes < 5 || minutes > 1440) { toast('Длительность: от 5 минут до 24 часов'); return; }
  const date = $('#workout-edit-date').value;
  if (!validPastOrTodayDate(date)) { toast('Дата — не позже сегодняшней'); return; }
  const typeValue = $('#workout-edit-type').value;
  const oldDate = workout.date;
  workout.type = ACTIVITY_TYPES[typeValue] ? typeValue : workout.type;
  workout.durationMinutes = minutes;
  workout.note = normalizeOptionalNote($('#workout-edit-note').value);
  workout.date = date;
  workout.editedAt = Date.now();
  if (oldDate !== todayKey()) syncPastDaySummary(oldDate);
  if (date !== todayKey()) syncPastDaySummary(date);
  saveState();
  renderTraining();
  if (oldDate === todayKey() || date === todayKey()) await syncTrainingReminderForToday();
  closeWorkoutEditDialog();
  toast('Активность обновлена');
}

function openWeightEditForDate(date) {
  const entry = normalizeWeightHistory(state.profileSettings.weightHistory).find((e) => e.date === date);
  if (!entry) return;
  $('#weight-quick-date').value = entry.date;
  $('#weight-quick-input').value = entry.weightKg;
  $('#weight-quick-dialog').hidden = false;
  setTimeout(() => $('#weight-quick-input').focus(), 100);
}

/* Поле даты в форме активности (0.5.0): по умолчанию сегодня, не позже. */
function renderWorkoutDateField() {
  if (typeof document === 'undefined') return;
  const input = $('#workout-date');
  if (!input) return;
  input.max = todayKey();
  if (!input.value) input.value = todayKey();
}

function openDayEditDialog() {
  const dateInput = $('#day-edit-date');
  dateInput.max = todayKey();
  if (!dateInput.value) {
    const y = new Date();
    y.setDate(y.getDate() - 1);
    dateInput.value = `${y.getFullYear()}-${String(y.getMonth() + 1).padStart(2, '0')}-${String(y.getDate()).padStart(2, '0')}`;
  }
  $('#day-edit-water').value = '';
  $('#day-edit-kcal').value = '';
  $('#day-edit-minutes').value = '';
  $('#day-edit-dialog').hidden = false;
  setTimeout(() => dateInput.focus(), 100);
}
function closeDayEditDialog() { $('#day-edit-dialog').hidden = true; }

function saveDayEdit() {
  const date = $('#day-edit-date').value;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date || '')) { toast('Выберите дату'); return; }
  if (date >= todayKey()) {
    toast('Этот диалог — для прошлых дней. Сегодняшние записи правятся в разделах «Вода», «Питание», «Активность».');
    return;
  }
  const readNum = (selector, max) => {
    const raw = String($(selector).value || '').trim();
    if (raw === '') return null;
    const num = Math.round(Number(raw.replace(',', '.')));
    if (!Number.isFinite(num) || num < 0 || num > max) return undefined;
    return num;
  };
  const water = readNum('#day-edit-water', 10000);
  const kcal = readNum('#day-edit-kcal', 10000);
  const minutes = readNum('#day-edit-minutes', 1440);
  if (water === undefined || kcal === undefined || minutes === undefined) { toast('Проверьте числа: вода/ккал до 10000, минуты до 1440'); return; }
  if (water === null && kcal === null && minutes === null) { toast('Все поля пустые — без изменений'); return; }
  const history = Array.isArray(state.dailyHistory) ? state.dailyHistory : [];
  const index = history.findIndex((day) => day.date === date);
  const prev = index >= 0 ? { ...history[index] } : null;
  const summary = prev || { date, waterTotal: 0, waterGoal: state.water.goal || DEFAULTS.water.goal, foodTotal: 0, foodGoal: state.food.goal || DEFAULTS.food.goal, foodP: 0, foodF: 0, foodC: 0, activityMinutes: 0 };
  if (water !== null) summary.waterTotal = water;
  if (kcal !== null) summary.foodTotal = kcal;
  if (minutes !== null) summary.activityMinutes = minutes;
  if (index >= 0) history[index] = summary; else history.push(summary);
  state.dailyHistory = history;
  normalizeDailyHistory();
  saveState();
  renderStats();
  renderWaterDetails();
  renderFoodDetails();
  closeDayEditDialog();
  showUndoSnack(`Итог за ${date.split('-').reverse().join('.')} обновлён`, () => {
    const list = Array.isArray(state.dailyHistory) ? state.dailyHistory : [];
    const at = list.findIndex((day) => day.date === date);
    if (prev) { if (at >= 0) list[at] = prev; else list.push(prev); }
    else if (at >= 0) list.splice(at, 1);
    state.dailyHistory = list;
    normalizeDailyHistory();
    saveState();
    renderStats();
    renderWaterDetails();
    renderFoodDetails();
    toast('Правка дня отменена');
  });
}

function upsertWeightHistory(date, weightKg) {
  const history = normalizeWeightHistory(state.profileSettings.weightHistory).filter((entry) => entry.date !== date);
  history.push({ date, weightKg: Math.round(weightKg * 10) / 10, updatedAt: Date.now() });
  state.profileSettings.weightHistory = normalizeWeightHistory(history);
}

function saveWeightRecord(date, weight) {
  if (!isValidWeightDate(date) || date > todayKey()) { toast('Укажите дату не позже сегодняшней'); return false; }
  if (!Number.isFinite(weight) || weight < 25 || weight > 300) { toast('Укажите вес от 25 до 300 кг'); return false; }
  upsertWeightHistory(date, weight);
  if (date === todayKey()) state.profileSettings.weightKg = Math.round(weight * 10) / 10;
  saveState();
  renderWeightSettings();
  renderWeightOverview();
  renderStats();
  renderProfiles();
  renderTraining();
  return true;
}

function saveWeightFromSettings() {
  const date = $('#weight-history-date').value;
  const weight = Number(String($('#weight-history-input').value).replace(',', '.'));
  if (!saveWeightRecord(date, weight)) return;
  toast(date === todayKey() ? 'Вес за сегодня сохранён' : 'Историческая запись веса сохранена');
}

function removeWeightRecord(date) {
  const prevEntry = normalizeWeightHistory(state.profileSettings.weightHistory)
    .find((entry) => entry.date === date) || null;
  const prevCurrent = state.profileSettings.weightKg;
  const history = normalizeWeightHistory(state.profileSettings.weightHistory).filter((entry) => entry.date !== date);
  state.profileSettings.weightHistory = history;
  if (date === todayKey()) {
    const recordsToToday = history.filter((entry) => entry.date <= todayKey());
    const latest = recordsToToday[recordsToToday.length - 1];
    state.profileSettings.weightKg = latest ? latest.weightKg : null;
  }
  saveState();
  renderWeightSettings();
  renderWeightOverview();
  renderStats();
  renderProfiles();
  renderTraining();
  // 0.5.0: удаление обратимо — снекбар с «Отменить»
  showUndoSnack('Запись веса удалена', () => {
    if (prevEntry) {
      const restored = normalizeWeightHistory(state.profileSettings.weightHistory)
        .filter((entry) => entry.date !== date);
      restored.push(prevEntry);
      state.profileSettings.weightHistory = normalizeWeightHistory(restored);
      if (date === todayKey()) state.profileSettings.weightKg = prevCurrent;
      saveState();
      renderWeightSettings();
      renderWeightOverview();
      renderStats();
      renderProfiles();
      renderTraining();
    }
    toast('Запись веса восстановлена');
  });
}

function applyHomeLayout() {
  if (typeof document === 'undefined') return;
  const container = $('#home-cards');
  if (!container) return;
  const layout = normalizeHomeLayoutValue(state.homeLayout);
  state.homeLayout = layout;
  layout.order.forEach((id) => {
    const card = $(`#${id}-card`);
    if (!card) return;
    card.hidden = !isHomeCardShown(id, layout);
    container.appendChild(card);
  });
  renderHomeQuickNav();
}

/* ===== Быстрый переход по разделам Главной (прилипающие чипы) ===== */
/* Короткие подписи чипов быстрого перехода (по карточкам Главной). */
const QUICKNAV_LABELS = {
  'day-plan': 'День',
  'day-mood': 'Самочувствие',
  'steps': 'Шаги',
  'water': 'Вода',
  'food': 'Питание',
  'weight': 'Вес'
};

/* 0.8.16: чипы строятся из РЕАЛЬНО видимых карточек (в их DOM-порядке) —
   «Шаги» и «Самочувствие» учтены, плотность экрана (свёрнуто/обычно/полно)
   учитывается сама: скрытые карточки просто не попадают в панель. */
function renderHomeQuickNav() {
  if (typeof document === 'undefined') return;
  const nav = $('#home-quicknav');
  if (!nav) return;
  /* 0.8.25 (найдено node-прогоном DOM): id элемента — «food-card», а в HOME_CARDS
     лежит «food». Сравнение el.id === h.id не совпадало НИКОГДА, поэтому панель
     быстрого перехода с 0.8.16 молча строилась пустой (nav.hidden = true).
     Сопоставляем по id карточки, а не по id элемента. */
  const cardsEl = $('#home-cards');
  const cards = cardsEl
    ? Array.from(cardsEl.children)
        .filter((el) => el && !el.hidden)
        .map((el) => ({ el, meta: HOME_CARDS.find((h) => `${h.id}-card` === el.id) }))
        .filter((x) => !!x.meta)
    : [];
  let html = '';
  cards.forEach(({ el, meta }) => {
    const label = QUICKNAV_LABELS[meta.id] || meta.label;
    /* 0.8.26 (п.1 владельца): в пилюле только текст. Иконка съедала ширину, и
       длинные названия («Самочувствие») обрезались многоточием. */
    html += `<button type="button" class="quicknav-chip" data-jump="${el.id}">${escapeHtml(label)}</button>`;
  });
  if (nav.innerHTML !== html) nav.innerHTML = html;
  nav.hidden = html === '';
  syncQuickNavTop(); // держим оффсеты актуальными (высота шапки/панели могла измениться)
  updateHomeQuickNavActive();
}

/* Низ прилипающей панели в «прилипшем» состоянии = шапка + высота панели.
   ЕДИНАЯ константа и для порога подсветки, и для прокрутки по клику — иначе
   они разъезжаются (история 0.8.3–0.8.15). */
function quicknavStuckBottom() {
  if (typeof document === 'undefined') return 120;
  const topbar = document.querySelector('.topbar');
  const nav = $('#home-quicknav');
  const topbarH = topbar ? topbar.offsetHeight : 0;
  const navH = nav ? nav.offsetHeight : 44;
  return topbarH + navH;
}

/* Активный чип — последний раздел, чья карточка прошла верхнюю зону экрана.
   Особый случай — самый низ страницы: карточка может физически не добраться
   до порога (последний экран), тогда активен последний видимый раздел. */
function updateHomeQuickNavActive() {
  if (typeof document === 'undefined') return;
  const nav = $('#home-quicknav');
  if (!nav || nav.hidden) return;
  // 0.8.1: не считаем подсветку, пока Главная скрыта — у скрытых карточек
  // getBoundingClientRect() отдаёт 0, и «активным» ошибочно становился
  // последний чип при переключении на другой экран и обратно.
  const homeView = $('#home-view');
  if (homeView && homeView.hidden) return;
  const chips = Array.from(nav.querySelectorAll('[data-jump]'));
  if (!chips.length) return;
  // Карточки в их фактическом порядке на экране; чипы строятся из тех же
  // карточек (renderHomeQuickNav), поэтому соответствие 1:1.
  const cardsEl = $('#home-cards');
  const cards = cardsEl ? Array.from(cardsEl.children).filter((el) => el && !el.hidden) : [];
  if (!cards.length) return;

  /* 0.8.26 (п.2 владельца: «поднимаюсь к самочувствию, а подсвечен другой раздел»).
     Было: активной считалась ПОСЛЕДНЯЯ карточка, чей верх прошёл порог. При
     прокрутке снизу вверх это врёт: у карточки, которую пользователь уже
     разглядывает, верх ещё не дошёл до порога, поэтому подсвеченной оставалась
     карточка ниже — та, что почти ушла с экрана. Тогда критерий сменили на
     «максимум видимой площади».

     0.9.1 (п.1 владельца: «нажимаю чип — подсвечивается соседний»). «Максимум
     площади» врёт на клике: scrollIntoView ставит верх нажатой карточки на
     линию порога, и если карточка низкая (Вес ~90px), а следующая под ней
     высокая (Питание ~400px), по площади побеждает соседка — подсвечивается
     не тот чип, который нажали.

     Стало: активна карточка, ПЕРЕСЕКАЮЩАЯ линию порога (верх выше линии, низ
     ниже). Это ровно та карточка, которая «стоит под панелью», — она же цель
     scrollIntoView, поэтому клик всегда подсвечивает нажатый чип. Для прокрутки
     руками критерий тоже честен и одинаков в обе стороны: линию пересекает то,
     что пользователь читает. Запас +8px — на дробные пиксели scroll-margin. */
  let activeId = null;
  const doc = document.documentElement;
  const scrollTop = window.scrollY || doc.scrollTop || 0;
  const viewTop = quicknavStuckBottom();          // экран начинается под панелью
  const viewBottom = window.innerHeight || doc.clientHeight || 0;
  const atBottom = (viewBottom + scrollTop) >= (doc.scrollHeight - 8);
  /* 0.9.5 (владелец: «поднимаюсь на самый верх — подсвечен „День“, хотя первая
     карточка „Шаги“»). Наверху страницы верх первой карточки стоит ЧУТЬ НИЖЕ
     линии порога (её собственный отступ), поэтому линию не пересекает никто —
     срабатывал запасной критерий «максимум площади», и высокая вторая карточка
     («План дня») перевешивала невысокую первую («Шаги»). Симметрично низу
     страницы: если прокрутка в самом верху, активна первая карточка. */
  const atTop = scrollTop <= 8;
  if (atTop) {
    activeId = cards[0].id;
  } else if (atBottom) {
    // Самый низ страницы: последняя карточка может физически не дотянуться до
    // верха экрана, но пользователь смотрит именно на неё.
    activeId = cards[cards.length - 1].id;
  } else {
    const line = viewTop + 8;
    for (const card of cards) {
      const r = card.getBoundingClientRect();
      if (r.top <= line && r.bottom > line) { activeId = card.id; break; }
    }
    if (!activeId) {
      // Линию никто не пересёк (промежуток между карточками или экран короче
      // панели) — берём максимум видимой площади как запасной критерий.
      let bestSeen = 0;
      for (const card of cards) {
        const r = card.getBoundingClientRect();
        const seen = Math.min(r.bottom, viewBottom) - Math.max(r.top, viewTop);
        if (seen > bestSeen) { bestSeen = seen; activeId = card.id; }
      }
    }
    if (!activeId) activeId = cards[0].id;
  }
  chips.forEach((c) => c.classList.toggle('active', c.dataset.jump === activeId));
}

let quicknavScrollScheduled = false;
function onHomeQuickNavScroll() {
  if (quicknavScrollScheduled) return;
  quicknavScrollScheduled = true;
  requestAnimationFrame(() => {
    quicknavScrollScheduled = false;
    updateHomeQuickNavActive();
  });
}

/* Высота шапки → сдвиг прилипающей панели перехода */
function syncQuickNavTop() {
  if (typeof document === 'undefined') return;
  const topbar = document.querySelector('.topbar');
  if (topbar) document.documentElement.style.setProperty('--quicknav-top', `${topbar.offsetHeight}px`);
  // 0.8.16: scroll-margin для прокрутки по клику — тот же низ панели, что и
  // порог подсветки (минус небольшой запас, чтобы карточка точно подсветилась).
  document.documentElement.style.setProperty('--quicknav-scroll-margin', `${Math.max(0, quicknavStuckBottom() - 4)}px`);
}

function renderHomeLayoutSettings() {
  const status = $('#home-layout-status');
  if (!status) return;
  const layout = normalizeHomeLayoutValue(state.homeLayout);
  const visibleCount = Object.values(layout.visible).filter(Boolean).length;
  status.textContent = `Показывается: ${visibleCount} из ${HOME_CARDS.length}`;
}

function renderHomeLayoutDialog() {
  const list = $('#home-layout-list');
  if (!list) return;
  const layout = normalizeHomeLayoutValue(state.homeLayout);
  list.innerHTML = layout.order.map((id, index) => {
    const card = HOME_CARDS.find((item) => item.id === id);
    if (!card) return '';
    return `<div class="home-layout-row">
      <div class="home-layout-card-name"><span aria-hidden="true">${homeCardIcon(card.id)}</span><strong>${card.label}</strong></div>
      <div class="home-layout-controls">
        <label class="switch" title="Показывать ${card.label} на Главной">
          <input type="checkbox" data-home-card-visible="${card.id}" ${layout.visible[card.id] ? 'checked' : ''}>
          <span class="switch-track" aria-hidden="true"><span class="switch-thumb"></span></span>
          <span class="sr-only">Показывать ${card.label} на Главной</span>
        </label>
        <div class="home-layout-order" aria-label="Изменить порядок ${card.label}">
          <button type="button" data-home-card-move="${card.id}" data-home-card-direction="-1" ${index === 0 ? 'disabled' : ''} aria-label="Переместить ${card.label} выше">↑</button>
          <button type="button" data-home-card-move="${card.id}" data-home-card-direction="1" ${index === layout.order.length - 1 ? 'disabled' : ''} aria-label="Переместить ${card.label} ниже">↓</button>
        </div>
      </div>
    </div>`;
  }).join('');
}

function openHomeLayoutDialog() {
  renderHomeLayoutDialog();
  $('#home-layout-dialog').hidden = false;
}
function closeHomeLayoutDialog() { $('#home-layout-dialog').hidden = true; }

function updateHomeCardVisibility(id, visible) {
  const layout = normalizeHomeLayoutValue(state.homeLayout);
  if (!HOME_CARDS.some((card) => card.id === id)) return;
  if (!visible && Object.values(layout.visible).filter(Boolean).length <= 1) {
    toast('Оставьте хотя бы одну карточку на Главной');
    renderHomeLayoutDialog();
    return;
  }
  layout.visible[id] = visible;
  state.homeLayout = layout;
  saveState();
  applyHomeLayout();
  renderHomeLayoutSettings();
  renderHomeLayoutDialog();
}

function moveHomeCard(id, direction) {
  const layout = normalizeHomeLayoutValue(state.homeLayout);
  const from = layout.order.indexOf(id);
  const to = from + Number(direction);
  if (from < 0 || to < 0 || to >= layout.order.length) return;
  [layout.order[from], layout.order[to]] = [layout.order[to], layout.order[from]];
  state.homeLayout = layout;
  saveState();
  applyHomeLayout();
  renderHomeLayoutDialog();
}

/* ------------------------------------------------------------
   0.9.4 — конфигуратор Android-виджета (настройки + диалог).
   Логика лимита: у каждого размера фиксированный бюджет строк,
   каждый элемент стоит 1 или 2 строки. Не влезающий элемент
   не включается, а сообщает, сколько он занимает и сколько
   свободно — «молча ничего не произошло» быть не должно.
------------------------------------------------------------- */
function renderWidgetLayoutSettings() {
  const status = $('#widget-layout-status');
  if (!status) return;
  const layout = normalizeWidgetLayoutValue(state.widgetLayout);
  const size = widgetSizeById(layout.size);
  const shownItems = layout.items.filter(isWidgetItemAvailable);
  const shown = shownItems.length;
  const hidden = layout.items.length - shown;
  if (!layout.items.length) {
    status.textContent = `${size.label}: ничего не выбрано`;
    return;
  }
  // Считаем по тому, что реально попадёт на виджет: выключенные в приложении
  // показатели не занимают строк и не должны раздувать счётчик.
  let text = `${size.label}: ${shown} ${ruForms(shown, ['элемент', 'элемента', 'элементов'])} · занято ${widgetUnitsUsed(shownItems)} из ${size.units}`;
  if (hidden > 0) text += ` · ${hidden} ${ruForms(hidden, ['скрыт', 'скрыто', 'скрыто'])} (выключено в приложении)`;
  status.textContent = text;
}

function renderWidgetLayoutDialog() {
  const list = $('#widget-layout-list');
  if (!list) return;
  const layout = normalizeWidgetLayoutValue(state.widgetLayout);
  const size = widgetSizeById(layout.size);
  const used = widgetUnitsUsed(layout.items);

  const sizeBox = $('#widget-size-segmented');
  if (sizeBox) {
    sizeBox.querySelectorAll('[data-widget-size]').forEach((button) => {
      const on = button.dataset.widgetSize === layout.size;
      button.classList.toggle('active', on);
      button.setAttribute('aria-checked', on ? 'true' : 'false');
    });
  }

  const counter = $('#widget-layout-counter');
  if (counter) counter.textContent = `Занято ${used} из ${size.units} ${ruForms(size.units, ['строки', 'строк', 'строк'])}`;

  // Сначала выбранные — в порядке пользователя, затем остальные.
  const rest = WIDGET_ITEMS.filter((item) => !layout.items.includes(item.id)).map((item) => item.id);
  const order = layout.items.concat(rest);
  list.innerHTML = order.map((id, index) => {
    const item = widgetItemById(id);
    if (!item) return '';
    const checked = layout.items.includes(id);
    const available = isWidgetItemAvailable(id);
    const fits = checked || used + item.units <= size.units;
    const cost = `${item.units} ${ruForms(item.units, ['строка', 'строки', 'строк'])}`;
    const note = !available
      ? 'выключено в приложении'
      : (checked ? cost : (fits ? cost : `не помещается · ${cost}`));
    return `<div class="home-layout-row widget-layout-row${checked ? ' on' : ''}${available ? '' : ' off'}">
      <div class="home-layout-card-name">
        <span aria-hidden="true">${item.icon}</span>
        <div class="widget-layout-text"><strong>${item.label}</strong><span class="widget-layout-cost">${note}</span></div>
      </div>
      <div class="home-layout-controls">
        <label class="switch" title="Показывать ${item.label} на виджете">
          <input type="checkbox" data-widget-item="${item.id}" ${checked ? 'checked' : ''}>
          <span class="switch-track" aria-hidden="true"><span class="switch-thumb"></span></span>
          <span class="sr-only">Показывать ${item.label} на виджете</span>
        </label>
        <div class="home-layout-order" aria-label="Изменить порядок ${item.label}">
          <button type="button" data-widget-move="${item.id}" data-widget-direction="-1" ${(!checked || index === 0) ? 'disabled' : ''} aria-label="Переместить ${item.label} выше">↑</button>
          <button type="button" data-widget-move="${item.id}" data-widget-direction="1" ${(!checked || index >= layout.items.length - 1) ? 'disabled' : ''} aria-label="Переместить ${item.label} ниже">↓</button>
        </div>
      </div>
    </div>`;
  }).join('');
}

function openWidgetLayoutDialog() {
  renderWidgetLayoutDialog();
  $('#widget-layout-dialog').hidden = false;
}
function closeWidgetLayoutDialog() { $('#widget-layout-dialog').hidden = true; }

function setWidgetSize(sizeId) {
  const size = widgetSizeById(sizeId);
  const layout = normalizeWidgetLayoutValue(state.widgetLayout);
  const before = layout.items.length;
  state.widgetLayout = normalizeWidgetLayoutValue({ size: size.id, items: layout.items });
  const dropped = before - state.widgetLayout.items.length;
  saveState();
  renderWidgetLayoutSettings();
  renderWidgetLayoutDialog();
  if (dropped > 0) {
    toast(`${size.label}: помещается ${size.units} ${ruForms(size.units, ['строка', 'строки', 'строк'])} — ${dropped} ${ruForms(dropped, ['элемент убран', 'элемента убрано', 'элементов убрано'])}`);
  }
}

function updateWidgetItem(id, enabled) {
  const item = widgetItemById(id);
  if (!item) return;
  const layout = normalizeWidgetLayoutValue(state.widgetLayout);
  const size = widgetSizeById(layout.size);
  if (enabled) {
    if (!isWidgetItemAvailable(id)) {
      toast(`«${item.label}» выключено в приложении — сначала включите этот показатель`);
      renderWidgetLayoutDialog();
      return;
    }
    const free = size.units - widgetUnitsUsed(layout.items);
    if (item.units > free) {
      // Требование владельца: не «тихий отказ», а объяснение с цифрами.
      toast(`Не помещается: «${item.label}» занимает ${item.units} ${ruForms(item.units, ['строку', 'строки', 'строк'])}, свободно ${free} из ${size.units}`);
      renderWidgetLayoutDialog();
      return;
    }
    layout.items.push(id);
  } else {
    layout.items = layout.items.filter((itemId) => itemId !== id);
  }
  state.widgetLayout = layout;
  saveState();
  renderWidgetLayoutSettings();
  renderWidgetLayoutDialog();
}

function moveWidgetItem(id, direction) {
  const layout = normalizeWidgetLayoutValue(state.widgetLayout);
  const from = layout.items.indexOf(id);
  const to = from + Number(direction);
  if (from < 0 || to < 0 || to >= layout.items.length) return;
  [layout.items[from], layout.items[to]] = [layout.items[to], layout.items[from]];
  state.widgetLayout = layout;
  saveState();
  renderWidgetLayoutDialog();
}

/* 0.9.5 (п.3, оценка «делать, но узко»). Ставит текст и, ЕСЛИ значение
   реально изменилось, коротко «толкает» число. Проверка на изменение
   обязательна: без неё анимация запускалась бы на каждой перерисовке
   (а renderWater зовётся и по таймерам, и при открытии экрана) и
   превратилась бы в мельтешение. Системный режим «уменьшить движение»
   гасит анимацию глобальным правилом в style.css. */
function setValueAnimated(el, text, cls) {
  if (!el) return;
  const next = String(text);
  const changed = el.textContent !== next && el.textContent !== '';
  el.textContent = next;
  if (!changed) return;
  const klass = cls || 'value-bump';
  el.classList.remove(klass);
  void el.offsetWidth;              // рестарт анимации: нужен реальный reflow
  el.classList.add(klass);
  setTimeout(() => el.classList.remove(klass), 400);
}

function renderWater() {
  const { total, goal } = state.water;
  const pct = Math.min(1, goal > 0 ? total / goal : 0);

  setValueAnimated($('#water-total'), fmt(total));
  $('#water-ring-fg').style.strokeDashoffset =
    String(RING_CIRCUMFERENCE * (1 - pct));

  const card = $('#water-card');
  card.classList.toggle('goal-reached', total >= goal);

  const reached = total >= goal;
  const wasReached = $('#water-status') && /Цель достигнута/.test($('#water-status').textContent || '');
  $('#water-status').innerHTML = reached
    ? '<span style="color:var(--success);font-weight:700">Цель достигнута! 🎉</span>'
    : `из ${fmt(goal)} мл`;
  /* 0.9.5 (п.3): «пух» только в МОМЕНТ достижения цели, а не на каждой
     перерисовке уже достигнутой цели — иначе значок дёргался бы весь день. */
  if (reached && !wasReached) {
    const badge = $('#water-status').firstElementChild;
    if (badge) {
      badge.classList.add('check-pop');
      setTimeout(() => badge.classList.remove('check-pop'), 400);
    }
  }

  $('#water-undo').style.opacity = total > 0 ? '1' : '0.45';
  renderDayChecklist();
}


/* ============================================================
   🏃 Health Connect & Шагомер (0.7.0)
   ------------------------------------------------------------
   Трёхуровневая система приоритета источников без задвоения:
   1) Health Connect (часы / Zepp / Amazfit / Garmin / Samsung);
   2) Аппаратный шагомер телефона (TYPE_STEP_COUNTER);
   3) Ручной ввод.
   ============================================================ */
function normalizeHealthSync() {
  const source = state.healthSync || {};
  state.healthSync = {
    enabled: source.enabled === true,
    priority: ['auto', 'phone_only', 'health_connect_only'].includes(source.priority) ? source.priority : 'auto',
    includeInDailyBudget: source.includeInDailyBudget === true,
    dailyGoal: Math.max(1000, Math.min(50000, Number(source.dailyGoal) || 8000)),
    lastSyncTs: Number(source.lastSyncTs) || null,
    lastSteps: Math.max(0, Number(source.lastSteps) || 0),
    lastKcal: Math.max(0, Number(source.lastKcal) || 0),
    lastSource: typeof source.lastSource === 'string' ? source.lastSource : null,
    watchLastTs: Math.max(0, Number(source.watchLastTs) || 0),
    watchWorkouts: normalizeWatchWorkouts(source.watchWorkouts),
    stepsHistory: normalizeStepsHistory(source.stepsHistory)
  };
}

/* 0.8.7 (P28): история шагов по дням — снапшот «сколько шагов за день» при
   каждом разрешении данных. Для статистики 7/30 дней. Заполняется вперёд
   (день пишется, пока он «сегодня»); обратная заливка прошлых дней из
   Health Connect — отдельная нативная задача (вне этого JS-пакета). */
function normalizeStepsHistory(list) {
  if (!Array.isArray(list)) return [];
  const byDate = new Map();
  list.forEach((e) => {
    if (!e || !/^\d{4}-\d{2}-\d{2}$/.test(e.date)) return;
    byDate.set(e.date, { // поздняя запись дня побеждает (шаги за день только растут)
      date: e.date,
      steps: Math.max(0, Math.round(Number(e.steps) || 0)),
      source: typeof e.source === 'string' ? e.source : ''
    });
  });
  return Array.from(byDate.values())
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(-730); // держим до 2 лет
}

function recordStepsSnapshot(steps, source) {
  const value = Math.max(0, Math.round(Number(steps) || 0));
  if (!value) return; // нули в историю не пишем — «нет данных» ≠ «0»
  normalizeHealthSync();
  const list = normalizeStepsHistory(state.healthSync.stepsHistory);
  const today = todayKey();
  const idx = list.findIndex((e) => e.date === today);
  const entry = { date: today, steps: value, source: String(source || '') };
  if (idx >= 0) list[idx] = entry; else list.push(entry);
  state.healthSync.stepsHistory = normalizeStepsHistory(list);
}

function getPhoneSteps() {
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.getPhoneStepsToday === 'function') {
      return Math.max(0, Number(window.FitFlowExport.getPhoneStepsToday()) || 0);
    }
  } catch (e) { }
  return 0;
}

/* 0.7.10: единый распознаватель источника шагов по приоритету.
   hcSteps — шаги С ЧАСОВ (из Health Connect, отфильтрованы по источнику),
   phoneSteps — шаги аппаратного шагомера телефона.
   0.7.12: «Авто» = часы приоритет, если за сегодня есть шаги с часов; иначе
   телефон. Возраст данных НЕ переключает источник (Zepp синхронизируется с
   Health Connect с задержкой, поэтому «данные часов с утра» ≠ «часы сняты») —
   возраст показывается подсказкой на карточке. Снятые на весь день часы дают
   0 шагов за сегодня → «Авто» сам переходит на телефон. Чистая функция:
   не читает state, чтобы её можно было проверять node-тестом. */
function resolveHealthSteps(priority, hcSteps, phoneSteps, watchLastTs, now) {
  const watch = Math.max(0, Number(hcSteps) || 0);
  const phone = Math.max(0, Number(phoneSteps) || 0);

  if (priority === 'phone_only') {
    return { steps: phone, source: 'шагомер телефона' };
  }
  if (priority === 'health_connect_only') {
    return { steps: watch, source: watch > 0 ? 'часы / Health Connect' : 'часы / Health Connect (нет данных)' };
  }
  // auto: часы → телефон
  if (watch > 0) return { steps: watch, source: 'часы / Health Connect' };
  if (phone > 0) return { steps: phone, source: 'шагомер телефона' };
  return { steps: 0, source: 'нет данных' };
}

/* ============================================================
   ⌚ Импорт тренировок с часов (0.8.0, шаг 1)
   Нативный мост читает ExerciseSessionRecord из Health Connect,
   JS показывает честную подсказку «нашли тренировку — добавить?»
   с подтверждением (правдивость: конкретные упражнения ненадёжны,
   а факт и длительность сессии — надёжны).
============================================================ */
/* Приводим сессию часов к каноничному виду. */
function normalizeWatchWorkouts(list) {
  if (!Array.isArray(list)) return [];
  const seen = new Set();
  const out = [];
  for (const s of list) {
    if (!s || !s.recordId) continue;
    const id = String(s.recordId).slice(0, 120);
    if (seen.has(id)) continue;
    seen.add(id);
    out.push({
      recordId: id,
      type: typeof s.type === 'string' ? s.type : '',
      title: typeof s.title === 'string' ? s.title.slice(0, 120) : '',
      start: Number(s.start) || 0,
      end: Number(s.end) || 0,
      minutes: Math.max(0, Math.min(1440, Math.round(Number(s.minutes) || 0))),
      date: typeof s.date === 'string' ? s.date : todayKey(),
      imported: s.imported === true,
      ignored: s.ignored === true,
      autoImported: s.autoImported === true // 0.8.25: добавлено само, можно отменить
    });
  }
  return out;
}

/* Тип сессии часов → наш тип активности (по строке типа из натива + по заголовку). */
function mapWatchWorkoutType(typeStr, title) {
  const t = (String(typeStr || '') + ' ' + String(title || '')).toLowerCase();
  if (/плаван|swim|pool|open[-\s]?water/iu.test(t)) return 'swim';
  if (/велосипед|вело|cycl|bike|bicycl|сайклинг/iu.test(t)) return 'bike';
  if (/бег|пробеж|jog|run|кардио|cardio|бегов/iu.test(t)) return 'cardio';
  if (/ходьб|прогулк|walk|hik|треккинг|поход|trek/iu.test(t)) return 'walk';
  if (/йог|растяж|пилатес|yoga|stretch|pilates|стретчинг/iu.test(t)) return 'stretch';
  // 0.8.2: силовая — широкий словарь + generic «тренировка/workout» (трекеры часто
  // пишут OTHER_WORKOUT с заголовком «Workout»/«Тренировка» — это обычно зал).
  if (/силов|тренаж|зал|фитнес|кроссфит|функциональн|тренинг|тренировк|strength|weight|гир|штанга|lift|barbell|dumbbell|power|gym|workout|training|crossfit/iu.test(t)) return 'strength';
  // OTHER_WORKOUT без внятного заголовка — по умолчанию зал (силовая).
  if (String(typeStr || '').toLowerCase() === 'other') return 'strength';
  return 'other';
}

/* Запрос сессий часов у нативного моста (если он есть). */
function requestWatchWorkoutsSync() {
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.syncHealthWorkoutsNow === 'function') {
      window.FitFlowExport.syncHealthWorkoutsNow();
    }
  } catch (e) { }
}

/* 0.8.25: дата сессии часов — по времени НАЧАЛА тренировки, а не по дню
   получения данных. Раньше сессия, пришедшая поздно вечером или доехавшая
   с задержкой синхронизации, помечалась «сегодня» и в дневник попадала не
   в тот день. */
/* 0.8.25: сколько суток показывать кнопку «Отменить» у авто-добавленной тренировки. */
const WATCH_AUTO_UNDO_DAYS = 3;

function watchWorkoutDateKey(startMs, fallback) {
  const ms = Number(startMs) || 0;
  if (!ms) return fallback || todayKey();
  const d = new Date(ms);
  if (isNaN(d.getTime())) return fallback || todayKey();
  return courseDateKey(d);
}

/* Нативный мост вернул JSON со списком сессий. Сливаем с известными (дедуп по recordId). */
function onHealthWorkoutsReceived(json) {
  let list = [];
  try { list = JSON.parse(json) || []; } catch (e) { return; }
  if (!Array.isArray(list) || !list.length) return;
  normalizeHealthSync();
  const today = todayKey();
  const existing = normalizeWatchWorkouts(state.healthSync.watchWorkouts);
  const byId = new Map(existing.map((s) => [s.recordId, s]));
  let changed = false;
  for (const raw of list) {
    const recId = String((raw && raw.recordId) || (raw && raw.id) || '');
    if (!recId) continue;
    const minutes = Math.max(0, Math.round(Number(raw.minutes) || 0));
    if (minutes < 5) continue; // шум/нажатия — не тренировка
    if (byId.has(recId)) continue; // уже знаем (в т.ч. импортированные/игнорированные)
    const start = Number(raw.start) || 0;
    existing.unshift({
      recordId: recId,
      type: String(raw.type || ''),
      title: String(raw.title || '').slice(0,120),
      start,
      end: Number(raw.end) || 0,
      minutes: Math.min(1440, minutes),
      date: watchWorkoutDateKey(start, today),
      imported: false,
      ignored: false
    });
    changed = true;
  }
  if (!changed) return;
  state.healthSync.watchWorkouts = normalizeWatchWorkouts(existing);
  saveState();
  autoImportStaleWatchWorkouts(); // 0.8.25: вчерашние сессии не теряются
  renderWatchWorkoutsSuggest();
}

/* ------------------------------------------------------------
   0.8.25: авто-добавление «зависших» тренировок с часов.
   Проблема владельца: сессия, которую не успел добавить кнопкой,
   на следующий день пропадала из подсказки и оставалась только
   в памяти — тренировку приходилось вносить руками.
   Решение: сессии за ПРОШЛЫЕ дни (не сегодня), которые не
   импортированы и не отклонены, добавляются в дневник сами,
   с пометкой «с часов (авто)» и возможностью отменить.
   Сегодняшние сессии по-прежнему ждут ручного решения — пока
   день идёт, у владельца есть шанс поправить тип или пропустить.
------------------------------------------------------------ */
function isWatchWorkoutStale(session, today = todayKey()) {
  if (!session || session.imported || session.ignored) return false;
  const date = String(session.date || '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return false;
  return date < today;
}

/* Чистая часть (тестируется node-прогоном): какие сессии пора добавить сами. */
function pickStaleWatchWorkouts(list, today = todayKey()) {
  return (Array.isArray(list) ? list : []).filter((s) => isWatchWorkoutStale(s, today));
}

function autoImportStaleWatchWorkouts() {
  normalizeHealthSync();
  const list = normalizeWatchWorkouts(state.healthSync.watchWorkouts);
  const today = todayKey();
  const stale = pickStaleWatchWorkouts(list, today);
  if (!stale.length) return 0;
  let added = 0;
  for (const s of stale) {
    const type = mapWatchWorkoutType(s.type, s.title);
    const label = ACTIVITY_TYPES[type] || ACTIVITY_TYPES.other;
    const title = s.title || label.label;
    state.workouts.unshift({
      id: uid(),
      date: s.date || today,
      type,
      title,
      note: 'с часов (авто)',
      intensity: 'medium',
      durationMinutes: s.minutes,
      createdAt: Date.now(),
      watchRecordId: s.recordId // 0.8.25: связь с сессией — для отмены
    });
    s.imported = true;
    s.autoImported = true;
    added++;
  }
  state.healthSync.watchWorkouts = list;
  saveState();
  if (typeof document !== 'undefined') {
    renderTraining();
    updateNativeWidget();
    renderWatchWorkoutsSuggest();
    const first = stale[0];
    const firstLabel = first ? (first.title || (ACTIVITY_TYPES[mapWatchWorkoutType(first.type, first.title)] || ACTIVITY_TYPES.other).label) : '';
    toast(added === 1
      ? `⌚ Добавлена тренировка с часов за ${fmtCourseDate(first.date)}: ${firstLabel}`
      : `⌚ Добавлено тренировок с часов: ${added} (за прошлые дни)`);
  }
  return added;
}

/* Добавить сессию часов в дневник тренировок. */
function importWatchWorkout(recordId) {
  normalizeHealthSync();
  const list = normalizeWatchWorkouts(state.healthSync.watchWorkouts);
  const s = list.find((x) => x.recordId === recordId && !x.imported && !x.ignored);
  if (!s) return;
  const type = mapWatchWorkoutType(s.type, s.title);
  const label = ACTIVITY_TYPES[type] || ACTIVITY_TYPES.other;
  const title = s.title || label.label;
  state.workouts.unshift({
    id: uid(),
    date: s.date || todayKey(),
    type,
    title,
    note: 'с часов (импорт)',
    intensity: 'medium',
    durationMinutes: s.minutes,
    createdAt: Date.now()
  });
  s.imported = true;
  state.healthSync.watchWorkouts = list;
  saveState();
  renderTraining();
  renderWatchWorkoutsSuggest();
  updateNativeWidget();
  toast('✓ Добавлено с часов: ' + title + ' · ' + formatWorkoutDuration(s.minutes));
}

/* Пропустить подсказку по сессии (без записи в дневник). */
function dismissWatchWorkout(recordId) {
  normalizeHealthSync();
  const list = normalizeWatchWorkouts(state.healthSync.watchWorkouts);
  const s = list.find((x) => x.recordId === recordId);
  if (s) { s.ignored = true; s.imported = false; state.healthSync.watchWorkouts = list; }
  saveState();
  renderWatchWorkoutsSuggest();
}

/* 0.8.25: отменить авто-добавленную тренировку — убираем запись из дневника
   и помечаем сессию отклонённой, чтобы она не вернулась при следующем синке. */
function undoAutoWatchWorkout(recordId) {
  normalizeHealthSync();
  const list = normalizeWatchWorkouts(state.healthSync.watchWorkouts);
  const s = list.find((x) => x.recordId === recordId);
  if (!s) return;
  state.workouts = (Array.isArray(state.workouts) ? state.workouts : [])
    .filter((w) => w.watchRecordId !== recordId);
  s.imported = false;
  s.autoImported = false;
  s.ignored = true;
  state.healthSync.watchWorkouts = list;
  saveState();
  renderTraining();
  renderWatchWorkoutsSuggest();
  updateNativeWidget();
  toast('Тренировка с часов убрана из дневника');
}

/* Баннер «нашли тренировки с часов» в разделе Активность. */
function renderWatchWorkoutsSuggest() {
  if (typeof document === 'undefined') return;
  const box = $('#watch-workouts-suggest');
  if (!box) return;
  normalizeHealthSync();
  const today = todayKey();
  /* 0.8.25: сегодняшние сессии ждут решения владельца, а всё, что за прошлые
     дни, уже добавлено автоматически — по нему показываем строку отмены
     (сутки), чтобы «само добавилось» никогда не было сюрпризом. */
  const all = state.healthSync.watchWorkouts || [];
  const pending = all.filter((s) => !s.imported && !s.ignored && s.date === today);
  /* Окно показа отмены — WATCH_AUTO_UNDO_DAYS суток: старые авто-записи уже
     «прижились», незачем держать баннер вечно (он бы рос с каждой тренировкой). */
  const undoFrom = courseDateKey(new Date(Date.now() - WATCH_AUTO_UNDO_DAYS * 86400000));
  const autoAdded = all.filter((s) => s.autoImported && s.imported && !s.ignored && String(s.date || '') >= undoFrom);
  if (!pending.length && !autoAdded.length) { box.hidden = true; box.innerHTML = ''; return; }
  box.hidden = false;
  const rows = pending.map((s) => {
    const type = mapWatchWorkoutType(s.type, s.title);
    const label = ACTIVITY_TYPES[type] || ACTIVITY_TYPES.other;
    const title = s.title || label.label;
    const clock = s.start ? new Date(s.start).toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' }) : '';
    return `
      <div class="watch-workout">
        <div class="watch-workout-row">
          <span class="watch-workout-emoji" aria-hidden="true">${label.emoji}</span>
          <div class="watch-workout-info">
            <strong>${escapeHtml(title)}</strong>
            <span>${formatWorkoutDuration(s.minutes)}${clock ? ' · ' + clock : ''} · с часов · тип можно изменить после добавления</span>
          </div>
        </div>
        <div class="watch-workout-actions">
          <button class="watch-btn watch-btn-add" type="button" data-watch-import="${escapeHtml(s.recordId)}">Добавить</button>
          <button class="watch-btn watch-btn-ghost" type="button" data-watch-ignore="${escapeHtml(s.recordId)}">Игнорировать</button>
        </div>
      </div>`;
  }).join('');
  const autoRows = autoAdded.map((s) => {
    const type = mapWatchWorkoutType(s.type, s.title);
    const label = ACTIVITY_TYPES[type] || ACTIVITY_TYPES.other;
    const title = s.title || label.label;
    return `
      <div class="watch-workout watch-workout-auto">
        <div class="watch-workout-row">
          <span class="watch-workout-emoji" aria-hidden="true">${label.emoji}</span>
          <div class="watch-workout-info">
            <strong>${escapeHtml(title)}</strong>
            <span>${formatWorkoutDuration(s.minutes)} · ${fmtCourseDate(s.date)} · добавлено автоматически</span>
          </div>
        </div>
        <div class="watch-workout-actions">
          <button class="watch-btn watch-btn-ghost" type="button" data-watch-undo="${escapeHtml(s.recordId)}">Отменить</button>
        </div>
      </div>`;
  }).join('');
  const pendingBlock = rows
    ? '<p class="watch-workout-hint">⌚ Нашли тренировки с часов — добавить в дневник?</p>' + rows
    : '';
  const autoBlock = autoRows
    ? '<p class="watch-workout-hint">⌚ Тренировки с часов за прошлые дни добавлены сами — можно отменить</p>' + autoRows
    : '';
  box.innerHTML = pendingBlock + autoBlock;
}

/* 0.8.11: обратная заливка истории шагов (P28) — нативный мост вернул JSON
   [{date, steps}]. Сливаем только ПРОШЛЫЕ дни, которых ещё нет в истории
   (вперёд-снапшоты честнее — они записаны в тот день). */
/* Чистое слияние backfill с текущей историей (тестируется node-прогоном):
   добавляются только прошлые дни, которых ещё нет; вперёд-снапшоты не перезаписываются. */
function mergeStepsBackfill(existing, incoming, today) {
  const byDate = new Map(normalizeStepsHistory(existing).map((e) => [e.date, e]));
  for (const row of (Array.isArray(incoming) ? incoming : [])) {
    const date = String(row && row.date || '');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || date >= today) continue;
    const steps = Math.max(0, Math.round(Number(row.steps) || 0));
    if (!steps || byDate.has(date)) continue;
    byDate.set(date, { date, steps, source: 'Health Connect' });
  }
  return normalizeStepsHistory(Array.from(byDate.values()));
}

/* 0.8.23: слияние веса с умных весов с историей. Чистая функция (тестируется):
   добавляются только даты, которых ещё нет (не перезаписываем ручной ввод),
   сортировка по возрастанию. */
function mergeWeightsFromMetrics(history, weights) {
  const byDate = new Map(normalizeWeightHistory(history).map((e) => [e.date, e]));
  (Array.isArray(weights) ? weights : []).forEach((w) => {
    const date = String(w && w.date || '');
    const kg = Number(w && w.kg);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || date > todayKey()) return;
    if (!Number.isFinite(kg) || kg < 25 || kg > 300) return;
    if (byDate.has(date)) return;
    byDate.set(date, { date, weightKg: Math.round(kg * 10) / 10, updatedAt: Date.now() });
  });
  return [...byDate.values()].sort((a, b) => a.date.localeCompare(b.date));
}

function onHealthBodyMetricsReceived(json) {
  let data = {};
  try { data = JSON.parse(json) || {}; } catch (e) { return; }
  const weights = Array.isArray(data.weights) ? data.weights : [];
  const heightM = Number(data.heightM) || 0;
  let changed = false;
  let addedWeight = 0;
  let addedHeight = false;

  if (weights.length) {
    const merged = mergeWeightsFromMetrics(state.profileSettings.weightHistory, weights);
    const before = normalizeWeightHistory(state.profileSettings.weightHistory).length;
    if (merged.length !== before) {
      state.profileSettings.weightHistory = merged;
      addedWeight = merged.length - before;
      changed = true;
      // Если текущего веса нет — берём последний по дате.
      if (!state.profileSettings.weightKg && merged.length) {
        state.profileSettings.weightKg = merged[merged.length - 1].weightKg;
      }
    }
  }
  if (heightM > 0 && !state.profileSettings.heightCm) {
    state.profileSettings.heightCm = Math.round(heightM * 100);
    addedHeight = true;
    changed = true;
  }
  if (!changed) return;
  saveState();
  if (typeof document !== 'undefined') {
    renderWeightOverview();
    renderProfileBasics();
    const bits = [];
    if (addedWeight) bits.push(`вес с весов: +${addedWeight} зап.`);
    if (addedHeight) bits.push('рост подставлен');
    toast('⚖️ ' + bits.join(', '));
  }
}

function onHealthStepsHistoryReceived(json) {
  let list = [];
  try { list = JSON.parse(json) || []; } catch (e) { return; }
  if (!Array.isArray(list) || !list.length) return;
  normalizeHealthSync();
  const merged = mergeStepsBackfill(state.healthSync.stepsHistory, list, todayKey());
  state.healthSync.stepsHistory = merged;
  saveState();
  if (typeof document !== 'undefined') renderStats();
}

/* 0.8.11: экспорт тренировки в Health Connect (нативный мост). */
function exportWorkoutToHealthConnect(workoutId) {
  const w = (Array.isArray(state.workouts) ? state.workouts : []).find((x) => x.id === workoutId);
  if (!w) return;
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.exportWorkoutToHealthConnect === 'function') {
      const end = Date.now();
      const start = end - (Number(w.durationMinutes) || 0) * 60000;
      window.FitFlowExport.exportWorkoutToHealthConnect(JSON.stringify({
        title: w.title || (ACTIVITY_TYPES[w.type] || ACTIVITY_TYPES.other).label,
        type: w.type,
        start,
        end
      }));
      toast('⤴ Экспорт в Health Connect запущен…');
      return;
    }
  } catch (e) { }
  toast('Экспорт в Health Connect доступен в Android-сборке');
}

function onWorkoutExported(ok, message) {
  if (ok) toast('✓ Тренировка записана в Health Connect');
  else toast('⚠️ Health Connect: ' + String(message || 'не удалось записать'));
}

if (typeof window !== 'undefined') {
  window.onHealthWorkoutsReceived = onHealthWorkoutsReceived;
  window.importWatchWorkout = importWatchWorkout;
  window.dismissWatchWorkout = dismissWatchWorkout;
  window.onHealthStepsHistoryReceived = onHealthStepsHistoryReceived;
  window.exportWorkoutToHealthConnect = exportWorkoutToHealthConnect;
  window.onWorkoutExported = onWorkoutExported;
}

function openHealthConnectSettings() {
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.openHealthConnectSettings === 'function') {
      window.FitFlowExport.openHealthConnectSettings();
      return;
    }
  } catch (e) { }
  toast('Health Connect доступен в Android-сборке на телефоне');
}

function requestActivityRecognition() {
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.requestActivityRecognition === 'function') {
      window.FitFlowExport.requestActivityRecognition();
      toast('Запрос разрешения на шагомер отправлен');
      return;
    }
  } catch (e) { }
  toast('Шагомер доступен в Android-сборке на телефоне');
}

function renderStepsCard() {
  if (typeof document === 'undefined') return;
  const countEl = $('#steps-card-count');
  const goalEl = $('#steps-card-goal');
  const barEl = $('#steps-card-progress');
  const sourceEl = $('#steps-card-source');
  const kcalEl = $('#steps-card-kcal');
  const hintEl = $('#steps-card-sync-hint');
  if (!countEl) return;

  normalizeHealthSync();
  const goal = (state.healthSync && state.healthSync.dailyGoal) || 8000;
  const steps = (state.healthSync && state.healthSync.lastSteps) || getPhoneSteps() || 0;
  const kcal = (state.healthSync && state.healthSync.lastKcal) || Math.round(steps * 0.04);
  const src = (state.healthSync && state.healthSync.lastSource) || 'датчик телефона';

  countEl.textContent = fmt(steps);
  if (goalEl) goalEl.textContent = `из ${fmt(goal)} шагов`;
  if (sourceEl) sourceEl.textContent = src; // короткий источник в шапке
  if (kcalEl) kcalEl.textContent = `🔥 ≈ ${fmt(Math.round(kcal))} ккал`;

  // 0.7.13: краткая строка обновления под кнопкой синхронизации.
  // Если источник — часы и их данные устарели (Zepp давно не синхронизировался),
  // показываем время последних шагов с часов, чтобы число не выглядело «застрявшим».
  if (hintEl) {
    const clock = (t) => new Date(t).toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });
    let text = '';
    if (!state.healthSync.enabled) {
      // 0.7.14: карточка не должна выглядеть «мёртвой», когда синхронизация выключена
      text = 'Синхронизация выключена — включите в Настройках → Шаги';
    } else {
      const parts = [];
      const ts = (state.healthSync && state.healthSync.lastSyncTs) || 0;
      if (ts) parts.push('обновлено ' + clock(ts));
      const watchTs = (state.healthSync && state.healthSync.watchLastTs) || 0;
      if (watchTs > 0 && src.includes('Health Connect') && (Date.now() - watchTs) > 3600000) {
        parts.push('часы: ' + clock(watchTs));
      }
      text = parts.join(' · ');
    }
    hintEl.textContent = text;
    hintEl.hidden = !text;
  }

  if (barEl) {
    const pct = Math.min(100, Math.round((steps / Math.max(1, goal)) * 100));
    barEl.style.width = `${pct}%`;
  }
}

function changeStepsGoal(delta) {
  normalizeHealthSync();
  const cur = (state.healthSync && state.healthSync.dailyGoal) || 8000;
  const next = Math.max(1000, Math.min(50000, cur + delta));
  state.healthSync.dailyGoal = next;
  saveState();
  renderStepsCard();
  toast(`Цель шагов: ${fmt(next)} в день`);
}

function renderHealthSyncSettings() {
  if (typeof document === 'undefined') return;
  const toggle = $('#health-sync-toggle');
  const budgetToggle = $('#health-budget-toggle');
  const statusEl = $('#health-sync-status');
  const opts = $('#health-sync-options');
  if (!toggle) return;
  normalizeHealthSync();
  toggle.checked = state.healthSync.enabled;
  if (budgetToggle) budgetToggle.checked = state.healthSync.includeInDailyBudget;
  if (opts) opts.hidden = !state.healthSync.enabled;
  
  $$('#health-priority-choices button').forEach((btn) => {
    btn.classList.toggle('active', btn.dataset.healthPriority === state.healthSync.priority);
  });
  
  if (statusEl) {
    if (!state.healthSync.enabled) {
      statusEl.textContent = 'Синхронизация шагов и активности выключена.';
    } else {
      const steps = state.healthSync.lastSteps || getPhoneSteps() || 0;
      const src = state.healthSync.lastSource || 'датчик телефона';
      statusEl.textContent = `Синхронизация активна. Шагов сегодня: ${fmt(steps)} (${src}).`;
    }
  }
  renderStepsCard();
}

function updateHealthSyncEnabled(enabled) {
  normalizeHealthSync();
  state.healthSync.enabled = enabled;
  saveState();
  renderHealthSyncSettings();
  if (enabled) {
    requestActivityRecognition();
    syncHealthDataNow();
    toast('🏃 Синхронизация шагов включена');
  } else {
    toast('Синхронизация шагов выключена');
  }
}

function updateHealthPriority(priority) {
  normalizeHealthSync();
  state.healthSync.priority = priority;
  saveState();
  renderHealthSyncSettings();
  syncHealthDataNow();
  updateNativeWidget(); // 0.7.13: приоритет сразу уезжает в SharedPreferences для фонового виджета
  toast('Приоритет обновлён: ' + (priority === 'auto' ? 'Авто (Часы → Телефон)' : (priority === 'phone_only' ? 'Только телефон' : 'Только часы')));
}

function updateHealthIncludeInBudget(include) {
  normalizeHealthSync();
  state.healthSync.includeInDailyBudget = include;
  saveState();
  renderFood();
  toast(include ? 'Сожжённые калории учитываются в балансе питания' : 'Баланс питания считает только базовую цель');
}

let lastHealthDiagnosticsText = '';

function openHealthDiagnostics() {
  const dialog = $('#health-diag-dialog');
  const content = $('#health-diag-content');
  if (!dialog || !content) return;
  dialog.hidden = false;

  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.syncHealthConnectNow === 'function') {
      window.FitFlowExport.syncHealthConnectNow();
      requestWatchWorkoutsSync(); // 0.8.0: сессии тренировок тоже
      setTimeout(() => {
        if (!dialog.hidden) renderHealthDiagnosticsContent();
      }, 1500);
    }
  } catch (e) { }

  renderHealthDiagnosticsContent();
}

function renderHealthDiagnosticsContent() {
  const dialog = $('#health-diag-dialog');
  const content = $('#health-diag-content');
  if (!dialog || !content) return;

  let rawDiag = null;
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.getHealthDiagnosticsJson === 'function') {
      const raw = window.FitFlowExport.getHealthDiagnosticsJson();
      if (raw) rawDiag = JSON.parse(raw);
    }
  } catch (e) { }

  const phoneSteps = getPhoneSteps();
  const today = todayKey();
  
  const hasBridge = !!(window.FitFlowExport);
  const isAndroid14Plus = rawDiag && rawDiag.androidApi >= 34;
  const androidApi = rawDiag && rawDiag.androidApi ? rawDiag.androidApi : (hasBridge ? 'Да' : 'Веб-режим');
  const model = rawDiag ? `${rawDiag.manufacturer || ''} ${rawDiag.model || ''}`.trim() : 'Браузер / WebView';
  const actPerm = rawDiag ? (rawDiag.activityRecognitionGranted ? '✓ Выдано' : '⚠️ Не выдано (нажмите «Разрешить»)') : 'Не требуется';
  const stepSensor = rawDiag ? (rawDiag.hasStepCounterSensor ? '✓ Найден (аппаратный сопроцессор)' : '⚠️ Нет аппаратного датчика') : 'Не доступен';
  const hcApp = isAndroid14Plus ? '✓ Встроен в систему (Android 14+)' : (rawDiag ? (rawDiag.hasHealthConnectApp ? '✓ Доступен в системе' : '⚠️ Не найден') : 'Только в APK');
  const phoneStepsToday = rawDiag ? (rawDiag.phoneStepsToday || phoneSteps || 0) : phoneSteps;
  // 0.7.10: честно показываем отдельно «все источники Health Connect» и «только часы».
  // Новые сборки отдают hcTotalStepsToday (все) + hcWatchStepsToday (часы);
  // старые — только hcStepsToday (сумму всех источников, часы отдельно не выделялись).
  const hcTotalToday = rawDiag ? (rawDiag.hcTotalStepsToday || rawDiag.hcStepsToday || 0) : (state.healthSync.lastSource && state.healthSync.lastSource.includes('Health Connect') ? state.healthSync.lastSteps : 0);
  const hcWatchToday = rawDiag ? (rawDiag.hcWatchStepsToday !== undefined ? rawDiag.hcWatchStepsToday : (rawDiag.hcStepsToday || 0)) : 0;
  // 0.7.11: если в Health Connect есть шаги, но «часов» не распознано — честно подсказываем,
  // что источник (браслет/часы) не из известного списка и надо сообщить пакет приложения.
  const unknownWatchSource = (hcTotalToday > 0 && hcWatchToday === 0);
  // Health Connect error state from Kotlin helper
  let hcLastError = '';
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.getHealthConnectLastError === 'function') {
      hcLastError = window.FitFlowExport.getHealthConnectLastError() || '';
    }
  } catch (e) { }

  const lastSyncStr = (rawDiag && rawDiag.lastSyncTs) ? new Date(rawDiag.lastSyncTs).toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' }) : 'нет';

  const sleepEntry = ((state.sleepCheckin && state.sleepCheckin.history) ? state.sleepCheckin.history[today] : null)
    || ((state.sleepCheckin && state.sleepCheckin.log) ? state.sleepCheckin.log.find((e) => e.date === today) : null);
  const hcSleepMin = sleepEntry ? (sleepEntry.durationMinutes || sleepEntry.durationMin || 0) : 0;
  const isSleepFromHC = sleepEntry && sleepEntry.source && sleepEntry.source.includes('Health Connect');
  const sleepStr = hcSleepMin > 0
    ? `${Math.floor(hcSleepMin / 60)} ч ${hcSleepMin % 60 ? (hcSleepMin % 60 + ' мин') : ''} (${sleepEntry.bedTime || '23:48'} – ${sleepEntry.wakeTime || '06:08'}) [${isSleepFromHC ? 'часы / Health Connect' : 'Ручной чек-ин'}]`
    : 'нет данных за сегодня';

  const reportLines = [
    `=== ОТЧЁТ ДИАГНОСТИКИ FITFLOW (${today}) ===`,
    `Устройство: ${model} (Android API ${androidApi})`,
    `Нативный мост FitFlow: ${hasBridge ? 'Подключен' : 'Отсутствует (веб)'}`,
    `Разрешение на физическую активность: ${actPerm}`,
    `Аппаратный шагомер телефона: ${stepSensor}`,
    `Системный сервис Health Connect: ${hcApp}`,
    `Шагов насчитано телефоном: ${phoneStepsToday}`,
    `Шагов в Health Connect (все источники): ${hcTotalToday}`,
    `Шагов с часов: ${hcWatchToday}`,
    `Сон из Health Connect: ${sleepStr}`,
    `Последний синк: ${lastSyncStr}`,
    `Статус Health Connect: ${hcLastError || 'нет данных'}`,
    `Активный приоритет в FitFlow: ${state.healthSync.priority}`,
    `Учитывать калории в бюджете: ${state.healthSync.includeInDailyBudget ? 'Да' : 'Нет'}`,
    unknownWatchSource ? `⚠️ Источник часов не распознан (в HC есть шаги, но «часов» нет) — посмотрите «источники» в статусе выше.` : ''
  ].filter(Boolean);
  lastHealthDiagnosticsText = reportLines.join('\n');

  content.innerHTML = `
    <div style="margin-bottom:8px"><strong>📱 Устройство:</strong> ${escapeHtml(model || 'Android')} (API ${androidApi})</div>
    <div style="margin-bottom:8px"><strong>🔑 Разрешение активности:</strong> ${actPerm}</div>
    <div style="margin-bottom:8px"><strong>👟 Шагомер телефона:</strong> ${stepSensor}</div>
    <div style="margin-bottom:8px"><strong>⌚ Health Connect:</strong> ${hcApp}</div>
    <hr style="border:none; border-top:1px solid rgba(0,0,0,0.1); margin:8px 0;" />
    <div style="margin-bottom:6px"><strong>📊 Шагов телефоном за сегодня:</strong> ${fmt(phoneStepsToday)}</div>
    <div style="margin-bottom:6px"><strong>⌚ Шагов в Health Connect (все источники):</strong> ${fmt(hcTotalToday)}</div>
    <div style="margin-bottom:6px"><strong>⌚ Шагов с часов:</strong> ${fmt(hcWatchToday)}</div>
    ${unknownWatchSource ? '<div style="margin-bottom:8px; padding:8px; background:rgba(230,150,20,0.12); border-radius:6px; font-size:12px;"><strong>⚠️ Источник часов не распознан:</strong> в Health Connect есть шаги, но браслет/часы не из известного списка. Посмотрите «источники» в статусе выше и сообщите пакет приложения — добавим его в поддерживаемые.</div>' : ''}
    <div style="margin-bottom:6px"><strong>🌙 Сон (Health Connect):</strong> ${sleepStr}</div>
    <div style="margin-bottom:6px"><strong>⏱ Время последнего синка:</strong> ${lastSyncStr}</div>
    ${hcLastError && !String(hcLastError).toLowerCase().startsWith('ok') ? '<div style="margin-bottom:8px; padding:8px; background:rgba(220,50,50,0.1); border-radius:6px; font-size:12px;"><strong>⚠️ Health Connect статус:</strong> ' + escapeHtml(hcLastError) + '</div>' : ''}
    <div style="margin-bottom:8px; display:flex; flex-direction:column; gap:6px;">
      <button class="btn btn-secondary" type="button" onclick="requestHCPermissions()" style="font-size:12px; padding:6px 12px">🔓 Разрешить в Health Connect (FitFlow)</button>
      <button class="btn btn-ghost" type="button" onclick="openHCSettingsSystem()" style="font-size:12px; padding:6px 12px">⚙️ Открыть Health Connect в системе</button>
    </div>
    <div style="margin-top:10px; padding:10px; background:rgba(0,105,107,0.08); border-radius:8px; font-size:12px; line-height:1.45;">
      <strong>📌 Как передать шаги и сон с часов или браслета:</strong><br>
      1. Откройте официальное приложение ваших часов (Huawei Health, Zepp, Samsung Health, Mi Fitness и др.).<br>
      2. В его настройках найдите пункт передачи данных в <strong>Health Connect</strong> (часто: Профиль → Аккаунты/Доступ → Health Connect) и включите шаги и сон.<br>
      3. Синхронизируйте часы с этим приложением (обычно — свайп вниз на главном экране приложения).<br>
      4. Вернитесь в FitFlow — данные подхватятся сами, или нажмите «🔄 Загрузить данные из Health Connect».
    </div>
  `;
}

function requestHCPermissions() {
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.requestHealthConnectPermissions === 'function') {
      window.FitFlowExport.requestHealthConnectPermissions();
      toast('Открываю настройки разрешений Health Connect…');
    } else {
      toast('Health Connect доступен только в APK-сборке');
    }
  } catch (e) {
    toast('Не удалось открыть настройки: ' + (e.message || e));
  }
}

function openHCSettingsSystem() {
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.openHealthConnectSettings === 'function') {
      window.FitFlowExport.openHealthConnectSettings();
      toast('Открываю системное приложение Health Connect…');
    } else {
      toast('Health Connect доступен только в APK-сборке');
    }
  } catch (e) {
    toast('Не удалось открыть настройки: ' + (e.message || e));
  }
}
if (typeof window !== 'undefined') {
  window.requestHCPermissions = requestHCPermissions;
  window.openHCSettingsSystem = openHCSettingsSystem;
}

function closeHealthDiagnostics() {
  const dialog = $('#health-diag-dialog');
  if (dialog) dialog.hidden = true;
}

function copyHealthDiagnosticsReport() {
  if (!lastHealthDiagnosticsText) {
    toast('Отчёт пуст');
    return;
  }
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(lastHealthDiagnosticsText).then(() => {
      toast('✓ Отчёт скопирован в буфер обмена');
    }).catch(() => {
      fallbackCopyText(lastHealthDiagnosticsText);
    });
  } else {
    fallbackCopyText(lastHealthDiagnosticsText);
  }
}

function fallbackCopyText(text) {
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    toast('✓ Отчёт скопирован в буфер обмена');
  } catch (e) {
    toast('Не удалось скопировать отчёт');
  }
}

function requestHealthSyncNow() {
  normalizeHealthSync();
  if (!state.healthSync.enabled) {
    toast('Сначала включите тумблер синхронизации выше');
    return;
  }
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.syncHealthConnectNow === 'function') {
      window.FitFlowExport.syncHealthConnectNow();
      requestWatchWorkoutsSync(); // 0.8.0: сессии тренировок тоже
      toast('Запрос к Health Connect и датчикам отправлен...');
      return;
    }
  } catch (e) { }
  
  // Fallback: телефонный шагомер
  syncHealthDataNow();
  const steps = state.healthSync.lastSteps || getPhoneSteps() || 0;
  toast(steps > 0 ? `Шагов сегодня: ${fmt(steps)} (шагомер телефона)` : 'Данные шагомера обновлены (0 шагов)');
}

/* 0.7.12: авто-обновление шагов при входе в приложение и возврате в него.
   Сначала мгновенно показываем нативный кэш, затем асинхронно читаем свежие
   данные из Health Connect — не чаще раза в 5 минут, чтобы не дёргать HC
   (у него есть квоты) на каждый возврат. */
let lastHealthAutoReadAt = 0;
// 0.7.17: короткий дебаунс вместо 5 минут — возврат из Zepp/Health Connect должен
// сразу подхватывать свежие данные, а не требовать ручной кнопки «sync».
const HEALTH_AUTO_READ_MIN_INTERVAL = 30 * 1000;
// 0.7.15: флаг «синк запущен авто» — чтобы колбэк показывал тихую галочку,
// а не всплывающий toast при каждом входе в приложение.
let pendingAutoHealthSync = false;

function refreshHealthDataOnResume() {
  normalizeHealthSync();
  if (!state.healthSync.enabled) return;
  syncHealthDataNow();          // мгновенно: кэш из SharedPreferences
  renderStepsCard();
  const now = Date.now();
  if (now - lastHealthAutoReadAt < HEALTH_AUTO_READ_MIN_INTERVAL) return;
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.syncHealthConnectNow === 'function') {
      lastHealthAutoReadAt = now;
      pendingAutoHealthSync = true;
      window.FitFlowExport.syncHealthConnectNow();
    }
  } catch (e) { pendingAutoHealthSync = false; }
  requestWatchWorkoutsSync(); // 0.8.0: подтягиваем и сессии тренировок с часов
  autoImportStaleWatchWorkouts(); // 0.8.25: вчерашние сессии не теряются
  requestStepsHistorySync(); // 0.8.11: обратная заливка истории шагов (P28)
  requestBodyMetricsSync(); // 0.8.23: вес/рост с умных весов (P34)
}

/* 0.8.11: обратная заливка истории шагов — редко (раз в сутки), HC читаем
   за 30 дней, поэтому не дёргаем на каждый вход. */
let lastStepsHistorySyncAt = 0;
function requestStepsHistorySync() {
  const now = Date.now();
  if (now - lastStepsHistorySyncAt < 24 * 60 * 60 * 1000) return;
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.syncHealthStepsHistory === 'function') {
      lastStepsHistorySyncAt = now;
      window.FitFlowExport.syncHealthStepsHistory();
    }
  } catch (e) { }
}

/* 0.8.23: показатели тела (вес/рост с умных весов) — тоже раз в сутки. */
let lastBodyMetricsSyncAt = 0;
function requestBodyMetricsSync() {
  const now = Date.now();
  if (now - lastBodyMetricsSyncAt < 24 * 60 * 60 * 1000) return;
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.syncHealthBodyMetrics === 'function') {
      lastBodyMetricsSyncAt = now;
      window.FitFlowExport.syncHealthBodyMetrics();
    }
  } catch (e) { }
}

/* 0.7.15: тихая анимированная галочка в блоке «Шаги» вместо всплывающего toast. */
function showStepsSyncTick() {
  const el = $('#steps-sync-check');
  if (!el) return;
  el.hidden = false;
  el.classList.remove('pop');
  void el.offsetWidth; // перезапуск CSS-анимации
  el.classList.add('pop');
  clearTimeout(el._tickTimer);
  el._tickTimer = setTimeout(() => { el.hidden = true; }, 2200);
}

if (typeof window !== 'undefined') {
  window.onHealthConnectDataReceived = function(steps, kcal, sleepMin, bedTime, wakeTime, watchLastTs) {
    normalizeHealthSync();
    const receivedSteps = Math.max(0, Number(steps) || 0);
    const receivedSleepMin = Math.max(0, Number(sleepMin) || 0);

    // 0.7.10: приоритет источника решается здесь же — нативный мост отдаёт шаги С ЧАСОВ,
    // а телефон берём из аппаратного шагомера (не из суммы всех источников Health Connect).
    // 0.7.11: watchLastTs — время последней записи шагов с часов (показываем возраст подсказкой).
    const resolved = resolveHealthSteps(state.healthSync.priority, receivedSteps, getPhoneSteps(), watchLastTs);
    state.healthSync.lastSteps = resolved.steps;
    state.healthSync.lastKcal = Math.round(resolved.steps * 0.04);
    state.healthSync.lastSource = resolved.source;
    state.healthSync.lastSyncTs = Date.now();
    state.healthSync.watchLastTs = Math.max(0, Number(watchLastTs) || 0);
    recordStepsSnapshot(resolved.steps, resolved.source); // 0.8.7: история шагов (P28)

    // Сон: сохранение объективных данных из Health Connect (Zepp)
    if (receivedSleepMin > 0) {
      if (!state.sleepCheckin) state.sleepCheckin = { enabled: true, history: {}, log: [] };
      if (!state.sleepCheckin.history) state.sleepCheckin.history = {};
      if (!Array.isArray(state.sleepCheckin.log)) state.sleepCheckin.log = [];
      const today = todayKey();
      const existing = state.sleepCheckin.history[today] || {};
      state.sleepCheckin.history[today] = {
        ...existing,
        durationMinutes: receivedSleepMin,
        durationMin: receivedSleepMin,
        bedTime: bedTime || existing.bedTime || '23:48',
        wakeTime: wakeTime || existing.wakeTime || '06:08',
        source: 'часы / Health Connect',
        rating: existing.rating || 4
      };

      const logIdx = state.sleepCheckin.log.findIndex((e) => e.date === today);
      const logEntry = {
        id: logIdx >= 0 ? state.sleepCheckin.log[logIdx].id : uid(),
        date: today,
        durationMin: receivedSleepMin,
        bedTime: bedTime || (logIdx >= 0 ? state.sleepCheckin.log[logIdx].bedTime : '23:48'),
        wakeTime: wakeTime || (logIdx >= 0 ? state.sleepCheckin.log[logIdx].wakeTime : '06:08'),
        rating: logIdx >= 0 ? (state.sleepCheckin.log[logIdx].rating || 4) : 4,
        tags: logIdx >= 0 ? (state.sleepCheckin.log[logIdx].tags || []) : [],
        onSchedule: true,
        createdAt: Date.now()
      };
      if (logIdx >= 0) {
        state.sleepCheckin.log[logIdx] = logEntry;
      } else {
        state.sleepCheckin.log.push(logEntry);
      }

      renderStats();
    }

    saveState();
    renderHealthSyncSettings();
    renderFood();
    renderStepsCard();

    // 0.7.15: авто-синк — тихая галочка в блоке «Шаги»; ручной синк — обычный toast.
    const wasAuto = pendingAutoHealthSync;
    pendingAutoHealthSync = false;
    if (wasAuto) {
      showStepsSyncTick();
    } else {
      const parts = [];
      if (resolved.steps > 0) parts.push(`${fmt(resolved.steps)} шагов (${resolved.source})`);
      if (receivedSleepMin > 0) parts.push(`сон ${Math.floor(receivedSleepMin/60)} ч ${receivedSleepMin%60} мин`);
      toast(parts.length > 0 ? `✓ Данные получены: ${parts.join(', ')}` : 'Синхронизировано (данных за сегодня пока нет)');
    }
  };
}

function syncHealthDataNow() {
  normalizeHealthSync();
  if (!state.healthSync.enabled) return;

  // 1. Быстрое чтение фонового снимка из нативного кэша (0 мс задержки)
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.getHealthSyncSnapshot === 'function') {
      const raw = window.FitFlowExport.getHealthSyncSnapshot();
      if (raw && raw.length > 2) {
        const snap = JSON.parse(raw);
        if (snap && snap.date === todayKey()) {
          // 0.7.10: hcSteps — это шаги С ЧАСОВ (отфильтрованы нативно по источнику);
          // watchSteps — явное имя для новых сборок, hcSteps — совместимость со старыми.
          const hcSteps = Math.max(0, Number(snap.watchSteps !== undefined ? snap.watchSteps : snap.hcSteps) || 0);
          const phoneSteps = Math.max(0, Number(snap.phoneSteps) || 0);
          const watchLastTs = Math.max(0, Number(snap.watchLastTs) || 0);
          const resolved = resolveHealthSteps(state.healthSync.priority, hcSteps, phoneSteps, watchLastTs);
          state.healthSync.lastSteps = resolved.steps;
          state.healthSync.lastSource = resolved.source;
          state.healthSync.lastKcal = Math.round(resolved.steps * 0.04);
          state.healthSync.lastSyncTs = snap.lastSync || Date.now();
          state.healthSync.watchLastTs = watchLastTs;
          recordStepsSnapshot(resolved.steps, resolved.source); // 0.8.7: история шагов (P28)
          saveState();
          renderHealthSyncSettings();
          renderFood();
          return;
        }
      }
    }
  } catch (e) { }

  // 2. Прямой опрос телефонного датчика (приоритет решает тот же распознаватель)
  const phoneSteps = getPhoneSteps();
  if (phoneSteps > 0) {
    const resolved = resolveHealthSteps(state.healthSync.priority, 0, phoneSteps);
    state.healthSync.lastSteps = resolved.steps;
    state.healthSync.lastSource = resolved.source;
    state.healthSync.lastSyncTs = Date.now();
    recordStepsSnapshot(resolved.steps, resolved.source); // 0.8.7: история шагов (P28)
    saveState();
    renderHealthSyncSettings();
    renderFood();
  }
}

/* ============================================================
   🍽 Баланс питания с учётом активности (0.8.2, P31)
   Раньше калории тренировок в бюджете не считались (workout.kcal не
   хранился) и при этом шаги суммировались с тренировками — при беге
   шаги учитывались бы дважды. Теперь: тренировки по MET + шаги,
   минус шаги, пришедшиеся на «шагающие» тренировки (без двойного счёта).
============================================================ */
const STEP_KCAL_PER_STEP = 0.04;

/* Чистая функция бюджета активности (тестируется node-прогоном): тренировки по
   MET + шаги × 0,04, минус шаги, пришедшиеся на «шагающие» тренировки
   (бег 160 / ходьба 120 шагов в минуту) — без двойного счёта (P31). */
function computeFoodBudgetAdjustmentPure(workouts, steps, weightKg) {
  const weight = Number(weightKg) || 70;
  const list = (Array.isArray(workouts) ? workouts : []).filter((w) => w.date === todayKey());
  let workoutKcal = 0;
  let overlapSteps = 0;
  list.forEach((w) => {
    const met = (ACTIVITY_MET[w.type] || ACTIVITY_MET.other)[w.intensity || 'medium'];
    workoutKcal += Math.round(met * weight * ((Number(w.durationMinutes) || 0) / 60));
    const cad = w.type === 'cardio' ? 160 : (w.type === 'walk' ? 120 : 0);
    overlapSteps += cad * (Number(w.durationMinutes) || 0);
  });
  const stepsCount = Math.max(0, Number(steps) || 0);
  const stepsKcal = Math.round(stepsCount * STEP_KCAL_PER_STEP);
  const overlapKcal = Math.min(stepsKcal, Math.round(overlapSteps * STEP_KCAL_PER_STEP));
  return {
    workoutKcal,
    stepsKcal,
    overlapKcal,
    total: Math.max(0, workoutKcal + stepsKcal - overlapKcal)
  };
}

function computeFoodBudgetAdjustment() {
  return computeFoodBudgetAdjustmentPure(
    state.workouts,
    (state.healthSync && state.healthSync.lastSteps) || 0,
    (state.profileSettings && state.profileSettings.weightKg) || null
  );
}

function renderFood() {
  const { items, goal } = state.food;
  const total = items.reduce((s, it) => s + it.kcal, 0);
  const totalP = items.reduce((s, it) => s + (it.p || 0), 0);
  const totalF = items.reduce((s, it) => s + (it.f || 0), 0);
  const totalC = items.reduce((s, it) => s + (it.c || 0), 0);

  let effectiveGoal = goal;
  let budgetAdj = null;
  if (state.healthSync && state.healthSync.enabled && state.healthSync.includeInDailyBudget) {
    budgetAdj = computeFoodBudgetAdjustment();
    effectiveGoal = goal + budgetAdj.total;
  }

  const pct = Math.min(1, effectiveGoal > 0 ? total / effectiveGoal : 0);

  setValueAnimated($('#food-total'), fmt(total));   // 0.9.5 (п.3): отклик на изменение ккал
  $('#food-goal-label').textContent = fmt(effectiveGoal);
  $('#food-goal').textContent = `${fmt(goal)} ккал`;
  if (budgetAdj && budgetAdj.total > 0) {
    $('#food-goal-label').setAttribute('title',
      `Активность +${fmt(budgetAdj.total)} ккал: тренировки ≈${fmt(budgetAdj.workoutKcal)} + шаги ≈${fmt(budgetAdj.stepsKcal)} − пересечение ≈${fmt(budgetAdj.overlapKcal)} (без двойного счёта)`);
  } else {
    $('#food-goal-label').removeAttribute('title');
  }
  $('#food-progress-fill').style.width = `${pct * 100}%`;
  $('#food-progress').setAttribute('aria-valuenow', String(total));
  $('#food-progress').setAttribute('aria-valuemax', String(goal));

  const card = $('#food-card');
  card.classList.toggle('over-goal', total > goal);

  const status = $('#food-status');
  let statusText = '';
  if (total === 0) {
    statusText = 'Добавьте приём пищи, чтобы начать';
  } else if (total > goal) {
    statusText = `На ${fmt(total - goal)} ккал больше цели. Всё в порядке — вы заслужили!`;
  } else {
    statusText = `Осталось ${fmt(goal - total)} ккал до цели`;
  }
  if (budgetAdj && budgetAdj.total > 0) {
    statusText += ` · активность +${fmt(budgetAdj.total)} ккал`;
  }
  status.textContent = statusText;

  // БЖУ — полоска макронутриентов
  const macrosEl = $('#food-macros');
  if (macrosEl) {
    const macroSum = totalP + totalF + totalC || 1;
    const pp = Math.round((totalP / macroSum) * 100);
    const fp = Math.round((totalF / macroSum) * 100);
    const cp = Math.round((totalC / macroSum) * 100);
    macrosEl.innerHTML = total > 0
      ? `<span class="macro-bar-label">⚪ Белки ${fmt(totalP)}г</span>
         <span class="macro-bar-label">🟡 Жиры ${fmt(totalF)}г</span>
         <span class="macro-bar-label">🟢 Углеводы ${fmt(totalC)}г</span>
         <span class="macro-bar-track" aria-label="Распределение БЖУ: белки ${pp}%, жиры ${fp}%, углеводы ${cp}%">
           <span class="macro-bar-p" style="width:${pp}%"></span>
           <span class="macro-bar-f" style="width:${fp}%"></span>
           <span class="macro-bar-c" style="width:${cp}%"></span>
         </span>`
      : '';
  }

  renderFoodList();
  renderFavoriteMeals();
  renderComboChips();
  renderDayChecklist();
}

function statsDateKey(daysAgo) {
  const date = new Date();
  date.setHours(0, 0, 0, 0);
  date.setDate(date.getDate() - daysAgo);
  const p = (value) => String(value).padStart(2, '0');
  return `${date.getFullYear()}-${p(date.getMonth() + 1)}-${p(date.getDate())}`;
}

function statsPeriodDays(period = activeStatsPeriod) {
  if (period === 'day') return 1;
  if (period === 'month') return 30;
  return 7;
}

function currentDaySummary() {
  return {
    date: todayKey(),
    waterTotal: state.water.total,
    waterGoal: state.water.goal,
    foodTotal: state.food.items.reduce((sum, item) => sum + (Number(item.kcal) || 0), 0),
    foodGoal: state.food.goal,
    foodP: state.food.items.reduce((sum, item) => sum + (Number(item.p) || 0), 0),
    foodF: state.food.items.reduce((sum, item) => sum + (Number(item.f) || 0), 0),
    foodC: state.food.items.reduce((sum, item) => sum + (Number(item.c) || 0), 0),
    activityMinutes: (Array.isArray(state.workouts) ? state.workouts : [])
      .filter((workout) => workout.date === todayKey())
      .reduce((sum, workout) => sum + (Number(workout.durationMinutes) || 0), 0)
  };
}

function getStatsDays(period = activeStatsPeriod) {
  const count = statsPeriodDays(period);
  const historyByDate = new Map((Array.isArray(state.dailyHistory) ? state.dailyHistory : [])
    .map((day) => [day.date, day]));
  const days = [];
  for (let offset = count - 1; offset >= 0; offset--) {
    const date = statsDateKey(offset);
    days.push(date === todayKey()
      ? currentDaySummary()
      : (historyByDate.get(date) || {
        date, waterTotal: 0, waterGoal: DEFAULTS.water.goal,
        foodTotal: 0, foodGoal: DEFAULTS.food.goal,
        // 0.4.9: сводки дня может не быть (см. урок normalizeDailyHistory), но
        // журнал тренировок хранит даты сам — минуты активности показываем
        // правдиво (это факт журнала, не выдумка), вода/еда без сводки — нули.
        activityMinutes: activityMinutesForDate(date)
      }));
  }
  return days;
}

function statsDateLabel(dateKey, period) {
  if (period === 'day') return 'сегодня';
  return dateKey.slice(8, 10);
}

function formatActivityDuration(minutes) {
  if (!minutes) return '0 мин';
  return formatWorkoutDuration(minutes);
}

function formatSleepDuration(minutes) {
  if (!minutes || minutes <= 0) return '0 мин';
  const h = Math.floor(minutes / 60);
  const m = Math.round(minutes % 60);
  if (h > 0 && m > 0) return `${h} ч ${m} мин`;
  if (h > 0) return `${h} ч`;
  return `${m} мин`;
}

function formatSleepDurationShort(minutes) {
  if (!minutes || minutes <= 0) return '';
  const h = Math.floor(minutes / 60);
  const m = Math.round(minutes % 60);
  if (h > 0 && m > 0) return `${h}ч ${m}м`;
  if (h > 0) return `${h}ч`;
  return `${m}м`;
}

function renderStatsBars(container, days, valueKey, maxValue, period, formatFn) {
  const safeMax = Math.max(1, maxValue);
  container.innerHTML = days.map((day) => {
    const value = Number(day[valueKey]) || 0;
    const height = Math.max(2, Math.min(100, (value / safeMax) * 100));
    const valText = formatFn ? formatFn(value) : (value > 0 ? String(Math.round(value)) : '');
    const titleVal = formatFn ? formatFn(value) : String(Math.round(value));
    return `<div class="stats-bar-wrap" title="${statsDateLabel(day.date, period)}: ${titleVal || '0'}">
      <div class="stats-bar-col">
        ${period === 'week' && value > 0 ? `<span class="stats-bar-value">${valText}</span>` : ''}
        <div class="stats-bar${value > 0 ? '' : ' is-empty'}" style="height:${height}%"></div>
      </div>
      <span class="stats-bar-label">${statsDateLabel(day.date, period)}</span>
    </div>`;
  }).join('');
}

function renderStats() {
  if (typeof document === 'undefined') return;
  const days = getStatsDays();
  const period = activeStatsPeriod;
  /* 0.8.25: скрытый показатель исключается и из Статистики — раздел не
     показываем целиком, чтобы «выключено» значило одно и то же везде. */
  const statsSectionVisibility = { water: 'water', food: 'food', steps: 'steps', weight: 'weight' };
  Object.keys(statsSectionVisibility).forEach((cardId) => {
    const section = $(`#stats-${statsSectionVisibility[cardId]}-section`);
    if (section) section.hidden = !isTrackerEnabled(cardId);
  });
  const waterTotal = days.reduce((sum, day) => sum + day.waterTotal, 0);
  const waterGoal = days.reduce((sum, day) => sum + day.waterGoal, 0);
  const foodTotal = days.reduce((sum, day) => sum + day.foodTotal, 0);
  const foodGoal = days.reduce((sum, day) => sum + day.foodGoal, 0);
  const activityMinutes = days.reduce((sum, day) => sum + day.activityMinutes, 0);
  const count = days.length;

  const captions = { day: 'Итоги за сегодня', week: 'Итоги за 7 дней', month: 'Итоги за 30 дней' };
  $('#stats-period-caption').textContent = captions[period];
  // 0.5.0 (вопрос владельца «в статистике суммы за весь период: 3+ л воды,
  // 2+ ч активности»): крупное число недели/месяца — СРЕДНЕЕ за день, сумма
  // периода честно остаётся строкой-подсказкой. Для «Сегодня» — сама сумма.
  const isDay = period === 'day';
  // 0.4.15 (аудит А2/А3): «нет записи» — не «0». Средние и % цели считаем
  // по дням С ЗАПИСЯМИ; дни без записей честно показываем отдельно.
  const waterDataDays = days.filter((day) => day.waterTotal > 0);
  const wGoalData = waterDataDays.reduce((sum, day) => sum + day.waterGoal, 0);
  const wPct = Math.round(wGoalData ? (waterTotal / wGoalData) * 100 : 0);
  const wAvg = waterDataDays.length ? waterTotal / waterDataDays.length : 0;
  // 0.5.1 (п.5/6 владельца): средние у всех трёх разделов с «≈» (раньше — только
  // у активности, вода/еда выглядели «точными»); за сегодня честно подписано
  // «от сегодняшней цели». \u00A0 склеивает «цифру+единицу», чтобы пары не
  // разрывались переносом строки («всего за период» / «2 400 ккал»).
  const nbNum = (numText, unit) => `${numText} ${unit}`;
  const daysChunk = (n) => `записи ${n} из ${days.length} дн.`;
  $('#stats-water-total').textContent = isDay
    ? nbNum(fmt(waterTotal), 'мл')
    : (waterDataDays.length ? `≈ ${nbNum(fmt(wAvg), 'мл')} в день` : '—');
  $('#stats-water-hint').textContent = waterDataDays.length
    ? (isDay
      ? `${wPct}% от сегодняшней цели (${nbNum(fmt(state.water.goal), 'мл')})`
      : `${wPct}% от цели в дни с записями · всего ${nbNum(fmt(waterTotal), 'мл')}` + (waterDataDays.length < days.length ? ` · ${daysChunk(waterDataDays.length)}` : ''))
    : (isDay ? 'Записей о воде сегодня нет' : 'Записей о воде за период нет');
  const foodDataDays = days.filter((day) => day.foodTotal > 0);
  const fGoalData = foodDataDays.reduce((sum, day) => sum + day.foodGoal, 0);
  const fPct = Math.round(fGoalData ? (foodTotal / fGoalData) * 100 : 0);
  const fAvg = foodDataDays.length ? foodTotal / foodDataDays.length : 0;
  $('#stats-food-total').textContent = isDay
    ? nbNum(fmt(foodTotal), 'ккал')
    : (foodDataDays.length ? `≈ ${nbNum(fmt(fAvg), 'ккал')} в день` : '—');
  $('#stats-food-hint').textContent = foodDataDays.length
    ? (isDay
      ? `${fPct}% от сегодняшней цели (${nbNum(fmt(state.food.goal), 'ккал')})`
      : `${fPct}% от цели в дни с записями · всего ${nbNum(fmt(foodTotal), 'ккал')}` + (foodDataDays.length < days.length ? ` · ${daysChunk(foodDataDays.length)}` : ''))
    : (isDay ? 'Записей о питании сегодня нет' : 'Записей о питании за период нет');
  // Активность усредняем по ВСЕМ дням периода: дни отдыха — честные нули,
  // день отдыха не должен завышать средний ритм.
  const activityDataDays = days.filter((day) => day.activityMinutes > 0).length;
  $('#stats-activity-total').textContent = isDay
    ? formatActivityDuration(activityMinutes)
    : (activityMinutes ? `≈ ${formatActivityDuration(Math.round(activityMinutes / count))} в день` : '—');
  $('#stats-activity-hint').textContent = activityMinutes
    ? (isDay ? 'Активность за сегодня — в журнале ниже' : `Всего за период: ${formatActivityDuration(activityMinutes).replace(/ /g, ' ')} · ${daysChunk(activityDataDays)}`)
    : 'Пока нет отмеченной активности';

  renderStatsBars($('#stats-water-bars'), days, 'waterTotal', Math.max(...days.map((day) => day.waterGoal)), period);
  renderStatsBars($('#stats-food-bars'), days, 'foodTotal', Math.max(...days.map((day) => day.foodGoal)), period);
  renderStatsBars($('#stats-activity-bars'), days, 'activityMinutes', Math.max(...days.map((day) => day.activityMinutes), 30), period);

  // Сон и восстановление в Статистике (0.7.0)
  const sleepSection = $('#stats-sleep-section');
  if (sleepSection) {
    const sleepDays = days.map((day) => {
      const entry = ((state.sleepCheckin && state.sleepCheckin.history) ? state.sleepCheckin.history[day.date] : null)
        || ((state.sleepCheckin && state.sleepCheckin.log) ? state.sleepCheckin.log.find((e) => e.date === day.date) : null);
      return {
        date: day.date,
        durationMinutes: entry ? (entry.durationMinutes || (entry.durationMin || 0)) : 0,
        rating: entry ? (entry.rating || 0) : 0
      };
    });
    const sleepWithData = sleepDays.filter((d) => d.durationMinutes > 0 || d.rating > 0);
    const sleepTotalMin = sleepDays.reduce((sum, d) => sum + (d.durationMinutes || 0), 0);
    const avgSleepMin = sleepWithData.length && sleepTotalMin > 0 ? Math.round(sleepTotalMin / sleepWithData.length) : 0;
    
    const sleepTotalEl = $('#stats-sleep-total');
    const sleepHintEl = $('#stats-sleep-hint');
    const sleepBarsEl = $('#stats-sleep-bars');
    
    if (sleepTotalEl) {
      if (isDay) {
        const todayEntry = sleepDays[sleepDays.length - 1];
        const todaySleep = todayEntry ? todayEntry.durationMinutes : 0;
        sleepTotalEl.textContent = todaySleep > 0 ? formatSleepDuration(todaySleep) : '—';
      } else {
        sleepTotalEl.textContent = avgSleepMin > 0 
          ? `≈ ${formatSleepDuration(avgSleepMin)} в день`
          : (sleepWithData.length ? `${sleepWithData.length} чек-инов` : '—');
      }
    }
    if (sleepHintEl) {
      sleepHintEl.textContent = sleepWithData.length
        ? `Отмечено ${sleepWithData.length} из ${days.length} ночей · регулярность восстановления`
        : 'Данные о сне пока не отмечены';
    }
    if (sleepBarsEl) {
      renderStatsBars(sleepBarsEl, sleepDays, 'durationMinutes', 600, period, formatSleepDurationShort);
    }
  }

  // 👟 Шаги в статистике (0.8.7, P28): история шагов по дням
  const stepsSection = $('#stats-steps-section');
  if (stepsSection) {
    const stepsGoal = (state.healthSync && state.healthSync.dailyGoal) || 8000;
    const histMap = new Map((state.healthSync.stepsHistory || []).map((e) => [e.date, e]));
    const stepsDays = days.map((day) => ({
      date: day.date,
      steps: day.date === todayKey()
        ? ((state.healthSync.lastSteps) || (histMap.get(day.date) || {}).steps || 0)
        : (histMap.get(day.date) || {}).steps || 0
    }));
    const stepsWithData = stepsDays.filter((d) => d.steps > 0);
    const stepsTotal = stepsDays.reduce((sum, d) => sum + d.steps, 0);
    const stepsAvg = stepsWithData.length ? Math.round(stepsTotal / stepsWithData.length) : 0;
    const stepsMax = Math.max(stepsGoal, ...stepsDays.map((d) => d.steps), 1);
    const stepsTotalEl = $('#stats-steps-total');
    const stepsHintEl = $('#stats-steps-hint');
    if (stepsTotalEl) {
      if (isDay) {
        stepsTotalEl.textContent = fmt(stepsDays[stepsDays.length - 1].steps);
      } else {
        stepsTotalEl.textContent = stepsWithData.length ? `≈ ${fmt(stepsAvg)} в день` : '—';
      }
    }
    if (stepsHintEl) {
      stepsHintEl.textContent = stepsWithData.length
        ? (isDay
          ? `цель ${fmt(stepsGoal)} шагов · источник: ${state.healthSync.lastSource || '—'}`
          : `всего ${fmt(stepsTotal)} шагов · ${stepsWithData.length} из ${days.length} дн. с записями`)
        : (isDay ? `цель ${fmt(stepsGoal)} шагов · пока нет данных` : 'История шагов появится после дней с синхронизацией');
    }
    renderStatsBars($('#stats-steps-bars'), stepsDays, 'steps', stepsMax, period);
  }

  $$('#stats-periods button').forEach((button) =>
    button.classList.toggle('active', button.dataset.statsPeriod === period));
  renderStatsCompare();
  renderWeightOverview();
  renderStatsWeightChart();
}

function renderWaterDetails() {
  if (typeof document === 'undefined') return;
  const period = activeWaterDetailPeriod;
  const days = getStatsDays(period);
  const total = days.reduce((sum, day) => sum + day.waterTotal, 0);
  const goal = days.reduce((sum, day) => sum + day.waterGoal, 0);
  const achieved = days.filter((day) => day.waterTotal > 0 && day.waterTotal >= day.waterGoal).length;
  const captions = { day: 'Итоги за сегодня', week: 'Итоги за 7 дней', month: 'Итоги за 30 дней' };
  $('#water-details-caption').textContent = captions[period];
  $('#water-details-total').textContent = `${fmt(total)} мл`;
  const waterDataDays = days.filter((day) => day.waterTotal > 0);
  const waterDataGoal = waterDataDays.reduce((sum, day) => sum + day.waterGoal, 0);
  $('#water-details-average').textContent = waterDataDays.length
    ? `В среднем ${fmt(total / waterDataDays.length)} мл в дни с записями · ${Math.round(waterDataGoal ? total / waterDataGoal * 100 : 0)}% от цели` + (waterDataDays.length < days.length ? ` (записи: ${waterDataDays.length} из ${days.length} дн.)` : '')
    : 'Записей о воде за период нет';
  $('#water-details-insight').textContent = achieved
    ? `Цель по воде выполнена в ${achieved} из ${days.length} дней.`
    : 'Добавляйте воду на Главной — здесь появится история выполнения цели.';
  renderStatsBars($('#water-details-bars'), days, 'waterTotal', Math.max(...days.map((day) => day.waterGoal)), period);
  $$('#water-detail-periods button').forEach((button) => button.classList.toggle('active', button.dataset.detailPeriod === period));
}

function renderFoodDetails() {
  if (typeof document === 'undefined') return;
  const period = activeFoodDetailPeriod;
  const days = getStatsDays(period);
  const total = days.reduce((sum, day) => sum + day.foodTotal, 0);
  const goal = days.reduce((sum, day) => sum + day.foodGoal, 0);
  const withinGoal = days.filter((day) => day.foodTotal > 0 && day.foodTotal <= day.foodGoal).length;
  const captions = { day: 'Итоги за сегодня', week: 'Итоги за 7 дней', month: 'Итоги за 30 дней' };
  $('#food-details-caption').textContent = captions[period];
  $('#food-details-total').textContent = `${fmt(total)} ккал`;
  const foodDataDays = days.filter((day) => day.foodTotal > 0);
  const foodDataGoal = foodDataDays.reduce((sum, day) => sum + day.foodGoal, 0);
  $('#food-details-average').textContent = foodDataDays.length
    ? `В среднем ${fmt(total / foodDataDays.length)} ккал в дни с записями · ${Math.round(foodDataGoal ? total / foodDataGoal * 100 : 0)}% от цели` + (foodDataDays.length < days.length ? ` (записи: ${foodDataDays.length} из ${days.length} дн.)` : '')
    : 'Записей о питании за период нет';
  $('#food-details-insight').textContent = withinGoal
    ? `Цель по калориям не превышена в ${withinGoal} из ${days.length} дней с записями.`
    : 'Добавляйте питание на Главной — здесь появятся дневные итоги.';
  renderStatsBars($('#food-details-bars'), days, 'foodTotal', Math.max(...days.map((day) => day.foodGoal)), period);
  $$('#food-detail-periods button').forEach((button) => button.classList.toggle('active', button.dataset.detailPeriod === period));
}

let selectedMealTypeId = '';
let mealTypeTouched = false; // true после ручного выбора чипа; сбрасывается после сохранения записи

function getSelectedMealType() {
  return getMealTypes().find((type) => type.id === selectedMealTypeId) || null;
}

function syncAutoMealType() {
  if (mealTypeTouched) return;
  const autoId = getMealTypeIdByTime();
  if (autoId) selectedMealTypeId = autoId;
}

function resetMealTypeAfterSave() {
  mealTypeTouched = false;
  selectedMealTypeId = '';
  syncAutoMealType();
  renderMealTypePicker();
}

function renderMealTypePicker() {
  syncAutoMealType();
  const picker = $('#meal-type-picker');
  if (!picker) return;
  picker.innerHTML = [
    '<button class="chip chip-sm meal-type-chip active" type="button" data-meal-type="">Без типа</button>',
    ...getMealTypes().map((type) => `<button class="chip chip-sm meal-type-chip" type="button" data-meal-type="${type.id}">${escapeHtml(type.label)}</button>`)
  ].join('');
  $$('#meal-type-picker [data-meal-type]').forEach((button) =>
    button.classList.toggle('active', button.dataset.mealType === selectedMealTypeId));
  const current = $('#meal-type-current');
  if (current) {
    const type = getSelectedMealType();
    const autoMark = type && !mealTypeTouched ? ' <span class="meal-type-auto" title="Определено автоматически по времени суток">авто</span>' : '';
    current.innerHTML = type
      ? `Приём пищи: <b>${escapeHtml(type.label)}</b>${autoMark}`
      : 'Приём пищи: <b>Без типа</b>';
  }
}

function addCustomMealType() {
  const input = $('#custom-meal-type-name');
  const label = normalizeActivityName(input.value);
  if (!label) { toast('Введите название типа приёма пищи'); input.focus(); return; }
  const id = `custom-${uid()}`;
  state.customMealTypes.push({ id, label });
  normalizeCustomMealTypes();
  selectedMealTypeId = id;
  mealTypeTouched = true;
  input.value = '';
  $('#custom-meal-type-inline').classList.remove('is-open');
  saveState();
  renderMealTypePicker();
  renderMealRemindersSettings(); renderNotificationBudget();
  toast(`Тип «${label}» добавлен`);
}

function applySelectedMealType(items) {
  const type = getSelectedMealType();
  return items.map((item) => ({ ...item, mealTypeId: type ? type.id : null, mealTypeLabel: type ? type.label : null }));
}

function groupFoodItemsByMealType(items, mealTypes = getMealTypes()) {
  const groupsById = new Map();
  const extraGroups = [];
  const untyped = { id: '', label: 'Без типа', items: [] };
  const knownTypes = new Map(mealTypes.map((type) => [type.id, { id: type.id, label: type.label, items: [] }]));

  items.forEach((item) => {
    const typeId = String(item.mealTypeId || '');
    let group = knownTypes.get(typeId);
    // Сохраняем читаемую старую метку при импорте, даже если тип позже исчез из списка.
    if (!group && typeId && item.mealTypeLabel) {
      group = groupsById.get(typeId);
      if (!group) {
        group = { id: typeId, label: String(item.mealTypeLabel).trim() || 'Другой приём пищи', items: [] };
        groupsById.set(typeId, group);
        extraGroups.push(group);
      }
    }
    (group || untyped).items.push(item);
  });

  return [
    ...[...knownTypes.values()].filter((group) => group.items.length > 0),
    ...extraGroups.filter((group) => group.items.length > 0),
    ...(untyped.items.length ? [untyped] : [])
  ].map((group) => ({
    ...group,
    totalKcal: group.items.reduce((sum, item) => sum + (Number(item.kcal) || 0), 0)
  }));
}

function renderFoodItem(item) {
  const hasMacros = (item.p || 0) > 0 || (item.f || 0) > 0 || (item.c || 0) > 0;
  const macrosText = hasMacros
    ? `<span class="food-item-macros">Б: ${fmt(item.p || 0)} · Ж: ${fmt(item.f || 0)} · У: ${fmt(item.c || 0)}</span>`
    : '';
  return `
    <li class="food-item" data-id="${item.id}">
      <span class="food-item-dot" aria-hidden="true">🍴</span>
      <div class="food-item-info">
        <p class="food-item-name">${escapeHtml(item.name)}</p>
        <p class="food-item-desc">${escapeHtml(item.raw)}${macrosText ? ' · ' + macrosText : ''}</p>
      </div>
      <span class="food-item-kcal">${fmt(item.kcal)}</span>
      <button class="food-item-edit" data-edit-food="${item.id}" type="button" aria-label="Изменить запись ${escapeHtml(item.name)}" title="Изменить">✏️</button>
      <button class="food-item-remove" data-remove="${item.id}" type="button" aria-label="Удалить ${escapeHtml(item.name)}">
        <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M6 6l12 12M18 6 6 18" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
        </svg>
      </button>
    </li>`;
}

/* 0.3.31 (просьба пользователя: с большим завтраком «до веса крутить очень
   долго»): группы приёмов пищи сворачиваются. Правило уважительное: с 4+
   записями группа по умолчанию свёрнута (видна строка «N зап. · X ккал» —
   информация не теряется), короткие развёрнуты; заголовок — кнопка-шеврон,
   состояние живёт на время сессии приложения. Каруселью вправо-влево
   сознательно НЕ делаем: в основном дневном потоке свайпы конфликтуют с
   вертикальным скроллом и прячут контент; кандидат для карусели в будущем —
   галерейные блоки (медали), не дневник. */
let foodGroupCollapsed = {};
function isFoodGroupCollapsed(group) {
  const key = group.id || '_none';
  if (!(key in foodGroupCollapsed)) foodGroupCollapsed[key] = group.items.length >= 4;
  return foodGroupCollapsed[key];
}

function renderFoodList() {
  const list = $('#food-list');
  const { items } = state.food;

  if (items.length === 0) {
    list.innerHTML = `<li class="food-empty">Пока пусто. Добавьте еду текстом:
      «овсянка 80г, банан 1шт» 🍽️</li>`;
    return;
  }

  list.innerHTML = groupFoodItemsByMealType(items).map((group) => {
    const collapsed = isFoodGroupCollapsed(group);
    const gid = group.id || '_none';
    return `
    <li class="food-group${collapsed ? ' collapsed' : ''}">
      <button type="button" class="food-group-header" data-group-toggle="${gid}" aria-expanded="${!collapsed}" aria-label="${collapsed ? 'Развернуть' : 'Свернуть'} приём: ${escapeHtml(group.label)}">
        <h3>${escapeHtml(group.label)}</h3>
        <span class="food-group-meta">${group.items.length} зап. · <span aria-label="Итого ${fmt(group.totalKcal)} килокалорий">${fmt(group.totalKcal)} ккал</span></span>
        <span class="food-group-chevron" aria-hidden="true">▾</span>
      </button>
      <ul class="food-group-items" aria-label="${escapeHtml(group.label)}"${collapsed ? ' hidden' : ''}>
        ${group.items.map(renderFoodItem).join('')}
      </ul>
    </li>`;
  }).join('');
}

function escapeHtml(s) {
  if (typeof document === 'undefined') {
    // Режим Node (тесты парсера): ручная замена без DOM.
    return String(s ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
  }
  const div = document.createElement('div');
  div.textContent = s;
  return div.innerHTML;
}

/* ============================================================
   Действия: вода
   ============================================================ */
function addWater(ml) {
  state.water.total += ml;
  state.water.log.push({ ts: Date.now(), ml });
  state.water.lastAddedAt = Date.now(); // момент записи — для правила «записал — ближайшее напоминание молчит»
  saveState();
  renderWater();
  // 0.5.6: JS-фолбэк-планировщик перестраивает остаток сетки с пропуском ближайшего
  // слота (нативный ресивер пропускает сам на момент срабатывания, его не трогаем).
  try {
    const bridge = getNativeBridge();
    const nativeActive = bridge && typeof bridge.scheduleWaterRemindersNative === 'function';
    if (state.waterReminders.enabled && !nativeActive && getLocalNotifications()) {
      scheduleWaterReminders({ requestPermission: false }).catch(() => { });
    }
  } catch (e) { }
}

/* 0.5.5 → 0.5.6 (решение владельца): переключателя «пауза после записи воды»
   больше нет — «и так уже слишком много переключателей и настроек». Правило
   фиксированное и автоматическое: вода записана — БЛИЖАЙШЕЕ напоминание молчит,
   следующее приходит по обычной сетке (сетка не сдвигается). Порог — сам
   интервал сетки: пьёшь не реже, чем напоминает FitFlow, — не донимаем.
   Реализация: isWaterReminderSlotSkipped (JS-фолбэк) и WaterReminderReceiver
   (нативный путь, в зеркале tools/github-workflows/build.yml). */

function undoWater() {
  const last = state.water.log.pop();
  if (!last) return;
  state.water.total = Math.max(0, state.water.total - last.ml);
  saveState();
  renderWater();
  toast('Последнее добавление отменено');
}

function changeWaterGoal(delta) {
  const next = Math.min(10000, Math.max(500, state.water.goal + delta));
  if (next === state.water.goal) return;
  state.water.goal = next;
  saveState();
  renderWater();
  renderDayPlan(); // 0.4.15: План дня показывал старую цель (аудит)
}

/* ============================================================
   Действия: еда
   ============================================================ */
async function addFoodText(text) {
  const errorBox = $('#food-error');
  errorBox.hidden = true;

  let items = parseMealText(text);

  // Если локальный парсер не справился — пробуем ИИ (если настроен)
  if (items.length === 0) {
    items = await parseWithAI(text);
  }

  if (!items || items.length === 0) {
    errorBox.textContent = `Не удалось разобрать: «${text}».
      Попробуйте так: «картофель 150г, котлета 1шт». ИИ-разбор появится позже.`;
    errorBox.hidden = false;
    return;
  }

  items = applySelectedMealType(items);
  const totalKcal = items.reduce((s, it) => s + it.kcal, 0);
  state.food.items.push(...items);
  saveState();
  resetMealTypeAfterSave();
  renderFood();
  await syncMealRemindersForToday();
  toast(`Добавлено: ${items.map((i) => i.name).join(', ')} (+${fmt(totalKcal)} ккал)`);
}

function readManualMeal() {
  const name = normalizeActivityName($('#manual-food-name').value);
  // Важно: «1 400» с пробелом должно читаться как 1400
  const parseNum = (id) => Number(String($(id).value || '').replace(/\s+/g, '').replace(',', '.'));
  const kcal = Math.round(parseNum('#manual-food-kcal'));
  const p = Math.round((parseNum('#manual-food-p') || 0) * 10) / 10 || null;
  const f = Math.round((parseNum('#manual-food-f') || 0) * 10) / 10 || null;
  const c = Math.round((parseNum('#manual-food-c') || 0) * 10) / 10 || null;
  if (!name) {
    toast('Введите название блюда (от 2 символов)');
    $('#manual-food-name').focus();
    return null;
  }
  if (!String($('#manual-food-kcal').value).trim() || !Number.isFinite(kcal) || kcal < 1 || kcal > 5000) {
    toast('Укажите калорийность числом от 1 до 5 000 ккал');
    $('#manual-food-kcal').focus();
    return null;
  }
  return { name, kcal, p, f, c };
}

async function addManualFood() {
  const meal = readManualMeal();
  if (!meal) return;
  state.food.items.push({
    id: uid(), raw: meal.name, name: meal.name, amount: null, unit: 'порция',
    kcal: meal.kcal, p: meal.p, f: meal.f, c: meal.c,
    ...applySelectedMealType([{}])[0]
  });
  saveState();
  resetMealTypeAfterSave();
  $('#manual-food-name').value = '';
  $('#manual-food-kcal').value = '';
  $('#manual-food-p').value = '';
  $('#manual-food-f').value = '';
  $('#manual-food-c').value = '';
  renderFood();
  await syncMealRemindersForToday();
  toast(`${meal.name}: +${fmt(meal.kcal)} ккал`);
}

function saveFavoriteMeal() {
  const meal = readManualMeal();
  if (!meal) return;
  state.favoriteMeals.unshift({ id: uid(), ...meal });
  normalizeFavoriteMeals();
  saveState();
  renderFavoriteMeals();
  toast(`«${meal.name}» сохранено в мои блюда`);
}

async function addFavoriteMeal(id) {
  const meal = state.favoriteMeals.find((item) => item.id === id);
  if (!meal) return;
  state.food.items.push({
    id: uid(), raw: meal.name, name: meal.name, amount: null, unit: 'порция',
    kcal: meal.kcal, p: meal.p, f: meal.f, c: meal.c,
    ...applySelectedMealType([{}])[0]
  });
  saveState();
  resetMealTypeAfterSave();
  renderFood();
  await syncMealRemindersForToday();
  toast(`${meal.name}: +${fmt(meal.kcal)} ккал`);
}

function removeFavoriteMeal(id) {
  const meal = state.favoriteMeals.find((item) => item.id === id);
  if (!meal) return;
  state.favoriteMeals = state.favoriteMeals.filter((item) => item.id !== id);
  saveState();
  renderFavoriteMeals();
  toast(`«${meal.name}» удалено из моих блюд`);
}

function renderFavoriteMeals() {
  const container = $('#favorite-meals');
  if (!container) return;
  if (state.favoriteMeals.length === 0) {
    container.innerHTML = '<span class="favorite-meals-empty">Сохраните своё блюдо, чтобы добавлять его одним нажатием.</span>';
    return;
  }
  container.innerHTML = state.favoriteMeals.map((meal) => `
    <span class="favorite-meal">
      <button class="favorite-meal-use" type="button" data-favorite-meal="${meal.id}">${escapeHtml(meal.name)} · ${fmt(meal.kcal)} ккал</button>
      <button class="favorite-meal-remove" type="button" data-remove-favorite="${meal.id}" aria-label="Удалить «${escapeHtml(meal.name)}» из моих блюд">×</button>
    </span>`).join('');
}

/* ============================================================
   ⭐ Мои комбо (0.4.14, запрос пользователя: «завтрак одним тапом»).
   Комбо — сохранённая фраза умного ввода («овсянка 150 г, кофе с молоком»):
   тап по чипу — и всё записано по СВОЕМУ же разбору (пользователь видел его
   при сохранении комбо). Цифры на чипе и при записи всегда пересчитываются
   актуальным парсером (правдивость: обновилась база — обновились и ккал);
   каждое срабатывание пишется в журнал распознаваний как обычный разбор.
   ============================================================ */
const COMBOS_LIMIT = 12;
const COMBOS_CHIPS_VISIBLE = 5;
let editingComboId = null;

/* Чистая нормализация списка комбо (тестируется в node): валидация полей,
   авто-имя из первой позиции, дедуп по id, лимит. */
function normalizeCombos(rawList) {
  if (!Array.isArray(rawList)) return [];
  const ids = new Set();
  return rawList.map((raw) => {
    if (!raw || typeof raw !== 'object') return null;
    const text = String(raw.text || '').trim().slice(0, 300);
    if (!text) return null;
    const first = text.split(/[,;]/u)[0].trim().slice(0, 28);
    const name = String(raw.name || '').trim().slice(0, 40)
      || (first + (/[,;]/u.test(text) ? ' +' : ''));
    return {
      id: typeof raw.id === 'string' && raw.id ? raw.id.slice(0, 24) : uid(),
      name,
      text,
      uses: Math.max(0, Math.round(Number(raw.uses) || 0)),
      createdAt: Number(raw.createdAt) > 0 ? Number(raw.createdAt) : 0
    };
  }).filter((c) => c && c.name && !ids.has(c.id) && ids.add(c.id))
    .slice(0, COMBOS_LIMIT);
}

function normalizeCombosState() {
  state.combos = normalizeCombos(state.combos);
}

function getCombos() {
  if (!Array.isArray(state.combos)) state.combos = [];
  return state.combos;
}

/* Честная сводка для чипа: прогоняем текст комбо актуальным парсером. */
function comboSummary(combo) {
  let parsed = { food: [], waterMl: 0, activities: [] };
  try { parsed = parseSmartEntry(combo.text); } catch (e) { /* не роняем рендер */ }
  return {
    kcal: Math.round((parsed.food || []).reduce((sum, i) => sum + (Number(i.kcal) || 0), 0)),
    waterMl: Number(parsed.waterMl) || 0,
    acts: (parsed.activities || []).length
  };
}

function addCombo(name, text) {
  const list = getCombos();
  const cleaned = String(text || '').trim().slice(0, 300);
  if (!cleaned) { toast('Заполните текст комбо — именно он будет разбираться при записи'); return false; }
  if (list.length >= COMBOS_LIMIT) { toast('Максимум ' + COMBOS_LIMIT + ' комбо — удалите лишние кнопкой «Ещё…»'); return false; }
  // Честный гард: комбо-пустышку (парсер не поймёт) не сохраняем —
  // ложного чипа «ничего не запишется» в интерфейсе не будет.
  const probe = parseSmartEntry(cleaned);
  if (!probe.food.length && !probe.waterMl && !probe.activities.length) {
    toast('⚠️ Такой текст парсер не разбирает — комбо не сохранено. Проверьте фразу кнопкой «Разобрать».');
    return false;
  }
  const first = cleaned.split(/[,;]/u)[0].trim().slice(0, 28);
  list.push({
    id: uid(),
    name: String(name || '').trim().slice(0, 40) || (first + (/[,;]/u.test(cleaned) ? ' +' : '')),
    text: cleaned,
    uses: 0,
    createdAt: Date.now()
  });
  saveState();
  return true;
}

function removeComboById(id) {
  const combo = getCombos().find((c) => c.id === id);
  state.combos = getCombos().filter((c) => c.id !== id);
  saveState();
  renderComboChips();
  renderComboDialog();
  toast('⭐ Комбо «' + (combo ? combo.name : '') + '» удалено');
}

function startRenameCombo(id) {
  editingComboId = id;
  renderComboDialog();
  setTimeout(() => {
    const el = $('#combo-rename-input');
    if (el) { el.focus(); el.select(); }
  }, 80);
}

function saveComboRename(id, value) {
  const combo = getCombos().find((c) => c.id === id);
  const name = String(value || '').trim().slice(0, 40);
  editingComboId = null;
  if (combo && name) {
    combo.name = name;
    saveState();
    toast('⭐ Комбо переименовано');
  }
  renderComboChips();
  renderComboDialog();
}

/* Запись комбо одним тапом: актуальный парсер + журнал + честный тост.
   «Не молчать»: если в комбо что-то перестало распознаваться (устаревший
   текст), говорим об этом прямо. */
async function useCombo(id) {
  const combo = getCombos().find((c) => c.id === id);
  if (!combo) return;
  const parsed = parseSmartEntry(combo.text);
  if (!parsed.waterMl && !parsed.food.length && !(parsed.activities || []).length) {
    toast('⚠️ Комбо «' + combo.name + '» не разобралось — поправьте его текст (кнопка «Ещё…»)');
    return;
  }
  const logId = logParseEvent('text', combo.text, parsed, null);
  markParseLogSaved(logId);
  commitParsedEntry(parsed, 'Комбо: ' + combo.name);
  combo.uses += 1;
  saveState();
  renderAll();
  await syncMealRemindersForToday();
  await syncTrainingReminderForToday();
  const bits = [];
  const kcal = Math.round(parsed.food.reduce((sum, i) => sum + i.kcal, 0));
  if (kcal > 0) bits.push('+' + fmt(kcal) + ' ккал');
  if (parsed.waterMl > 0) bits.push('+' + fmt(parsed.waterMl) + ' мл воды');
  const actMin = (parsed.activities || []).reduce((sum, a) => sum + a.durationMinutes, 0);
  if (actMin > 0) bits.push('активность ' + actMin + ' мин');
  let msg = '⭐ «' + combo.name + '» записано: ' + bits.join(', ') + '. Детали — в дневнике.';
  const missed = Array.from(new Set(parsed.unparsed || []));
  if (missed.length) msg += ' ⚠️ Не разобрал: «' + missed.join('», «') + '».';
  toast(msg, 4500);
  renderComboChips();
  // Если диалог управления открыт (тап по ▶ внутри него) — обновить счётчики,
  // но не в процессе переименования: не рвём ввод пользователя.
  const dialog = typeof document !== 'undefined' ? $('#combo-dialog') : null;
  if (dialog && !dialog.hidden && !editingComboId) renderComboDialog();
}

function renderComboChips() {
  if (typeof document === 'undefined') return;
  const host = $('#combo-chips');
  if (!host) return;
  const combos = getCombos();
  const hint = $('#combo-hint');
  const manageBtn = $('#combo-manage-btn');
  if (!combos.length) {
    host.innerHTML = '';
    if (manageBtn) manageBtn.hidden = true;
    if (hint) hint.textContent = 'Сохраните фразу кнопкой «☆ В комбо» — она появится здесь и запишется одним тапом.';
    return;
  }
  if (manageBtn) manageBtn.hidden = false;
  if (hint) hint.textContent = '';
  host.innerHTML = combos.slice(0, COMBOS_CHIPS_VISIBLE).map((combo) => {
    const summary = comboSummary(combo);
    const bits = [];
    if (summary.kcal > 0) bits.push(fmt(summary.kcal) + ' ккал');
    if (summary.waterMl > 0) bits.push(fmt(summary.waterMl) + ' мл');
    if (summary.acts > 0) bits.push('активность');
    return '<button class="chip chip-sm combo-chip" type="button" data-combo-id="' + combo.id
      + '" title="' + escapeHtml(combo.text).replace(/"/g, '&quot;') + '">⭐ '
      + escapeHtml(combo.name) + (bits.length ? ' · ' + bits.join(' · ') : '') + '</button>';
  }).join('');
}

function renderComboDialog() {
  if (typeof document === 'undefined') return;
  const list = $('#combo-list');
  if (!list) return;
  const combos = getCombos();
  if (!combos.length) {
    list.innerHTML = '<p class="settings-hint">Пока пусто. Добавьте первое комбо ниже — или сохраните разобранную фразу из умного ввода кнопкой «☆ В комбо».</p>';
    return;
  }
  list.innerHTML = combos.map((combo) => {
    const summary = comboSummary(combo);
    const kcalText = summary.kcal > 0 ? '≈' + fmt(summary.kcal) + ' ккал' : '';
    const usesText = combo.uses > 0 ? 'использовано ' + combo.uses + '×' : '';
    const meta = [kcalText, usesText].filter(Boolean).join(' · ');
    if (editingComboId === combo.id) {
      return '<div class="combo-row">'
        + '<div class="combo-row-main">'
        + '<input id="combo-rename-input" type="text" maxlength="40" value="' + escapeHtml(combo.name).replace(/"/g, '&quot;') + '" aria-label="Новое имя комбо">'
        + '<p class="settings-hint combo-row-text">«' + escapeHtml(combo.text) + '»' + (meta ? ' · ' + meta : '') + '</p>'
        + '</div><div class="combo-row-actions">'
        + '<button class="icon-btn" type="button" data-combo-save-rename="' + combo.id + '" aria-label="Сохранить имя" title="Сохранить имя">✓</button>'
        + '<button class="icon-btn" type="button" data-combo-cancel-rename="1" aria-label="Отмена" title="Отмена">✕</button>'
        + '</div></div>';
    }
    return '<div class="combo-row">'
      + '<div class="combo-row-main"><b>' + escapeHtml(combo.name) + '</b>' + (meta ? ' <span class="settings-hint">' + meta + '</span>' : '')
      + '<p class="settings-hint combo-row-text">«' + escapeHtml(combo.text) + '»</p></div>'
      + '<div class="combo-row-actions">'
      + '<button class="icon-btn" type="button" data-combo-use="' + combo.id + '" aria-label="Записать «' + escapeHtml(combo.name).replace(/"/g, '&quot;') + '» в дневник" title="Записать в дневник">▶</button>'
      + '<button class="icon-btn" type="button" data-combo-rename="' + combo.id + '" aria-label="Переименовать" title="Переименовать">✏️</button>'
      + '<button class="icon-btn" type="button" data-combo-remove="' + combo.id + '" aria-label="Удалить" title="Удалить">🗑</button>'
      + '</div></div>';
  }).join('');
}

function openComboDialog() {
  const dialog = $('#combo-dialog');
  if (!dialog) return;
  editingComboId = null;
  if ($('#combo-new-name')) $('#combo-new-name').value = '';
  if ($('#combo-new-text')) $('#combo-new-text').value = '';
  renderComboDialog();
  dialog.hidden = false;
}

function closeComboDialog() {
  const dialog = $('#combo-dialog');
  if (dialog) dialog.hidden = true;
  editingComboId = null;
}

/* «☆ В комбо» из умного ввода: сохраняем ИСХОДНУЮ фразу — она и есть макрос. */
function saveComboFromSmartEntry() {
  const input = $('#smart-entry-input');
  const text = input ? (input.value || '').trim() : '';
  if (addCombo('', text)) {
    renderComboChips();
    const combos = getCombos();
    toast('⭐ Комбо «' + combos[combos.length - 1].name + '» сохранено — теперь записывается одним тапом из «Питания»');
    const comboBtn = $('#smart-entry-combo-btn');
    if (comboBtn) comboBtn.hidden = true;
  }
}

function removeFood(id) {
  const index = state.food.items.findIndex((it) => it.id === id);
  if (index < 0) return;
  const removed = state.food.items[index];
  state.food.items.splice(index, 1);
  saveState();
  renderFood();
  // 0.5.0: удаление обратимо — снекбар с «Отменить»
  showUndoSnack(`Запись «${removed.name}» удалена`, () => {
    state.food.items.splice(Math.min(index, state.food.items.length), 0, removed);
    saveState();
    renderFood();
    toast('Запись восстановлена');
  });
}

function changeFoodGoal(delta) {
  const next = Math.min(10000, Math.max(800, state.food.goal + delta));
  if (next === state.food.goal) return;
  state.food.goal = next;
  saveState();
  renderFood();
  renderDayPlan(); // 0.4.15
}

/* ============================================================
   Активность: история, готовые варианты и связь с напоминанием
   ============================================================ */
let selectedActivityType = 'walk';
let selectedActivityIntensity = 'medium';
let selectedDurationUnit = 'minutes';

function renderDurationUnit() {
  const label = $('#workout-duration-unit-label');
  if (label) label.textContent = selectedDurationUnit === 'hours' ? 'часы' : 'мин';
  $$('#duration-unit-choices button').forEach((button) => button.classList.toggle('active', button.dataset.durationUnit === selectedDurationUnit));
}

function openDurationUnitDialog() {
  $('#duration-unit-dialog').hidden = false;
  renderDurationUnit();
}
function closeDurationUnitDialog() { $('#duration-unit-dialog').hidden = true; }
function setDurationUnit(unit) {
  if (unit !== 'minutes' && unit !== 'hours') return;
  selectedDurationUnit = unit;
  closeDurationUnitDialog();
  renderDurationUnit();
  $('#workout-duration').placeholder = unit === 'hours' ? '0,5' : '30';
}

function parseWorkoutDuration(raw, unit = 'hours') {
  const normalized = String(raw || '').trim().replace(',', '.');
  if (!/^\d+(?:\.\d+)?$/.test(normalized)) return null;
  const value = Number(normalized);
  const isHours = unit === 'hours';
  if (!Number.isFinite(value) || value <= 0 || (isHours && value > 24) || (!isHours && value > 1440)) return null;
  const minutes = Math.round(isHours ? value * 60 : value);
  return minutes >= 5 ? minutes : null;
}

function formatWorkoutDuration(minutes) {
  const safeMinutes = Math.max(0, Math.round(Number(minutes) || 0));
  const hours = Math.floor(safeMinutes / 60);
  const rest = safeMinutes % 60;
  if (hours === 0) return `${rest} мин`;
  if (rest === 0) return `${hours} ч`;
  return `${hours} ч ${rest} мин`;
}

function getWorkoutsForDate(date = todayKey()) {
  return state.workouts.filter((workout) => workout.date === date);
}

function activityCountText(count) {
  const lastTwoDigits = count % 100;
  const lastDigit = count % 10;
  if (lastTwoDigits >= 11 && lastTwoDigits <= 14) return 'активностей';
  if (lastDigit === 1) return 'активность';
  if (lastDigit >= 2 && lastDigit <= 4) return 'активности';
  return 'активностей';
}

function hasWorkoutToday() {
  return getWorkoutsForDate().length > 0;
}

function renderActivityTypeSelection() {
  $$('.workout-type-btn').forEach((button) => {
    const selected = button.dataset.activityType === selectedActivityType;
    button.classList.toggle('active', selected);
    button.setAttribute('aria-checked', String(selected));
  });
}

function renderActivityTemplates() {
  const list = $('#activity-templates');
  if (!list) return;

  if (state.activityTemplates.length === 0) {
    list.innerHTML = '<p class="activity-template-empty">Пока нет готовых вариантов. Например: «Кардио 45 мин» или «Прогулка в парке».</p>';
    return;
  }

  list.innerHTML = state.activityTemplates.map((template) => {
    const type = ACTIVITY_TYPES[template.type] || ACTIVITY_TYPES.other;
    return `
      <li class="activity-template-item">
        <button class="activity-template-use" type="button" data-use-template="${template.id}">
          <span>${type.emoji} ${escapeHtml(template.name)}</span>
          <small>${formatWorkoutDuration(template.durationMinutes)}</small>
        </button>
        <button class="activity-template-remove" type="button" data-remove-template="${template.id}" aria-label="Удалить готовый вариант «${escapeHtml(template.name)}»">×</button>
      </li>`;
  }).join('');
}

const ACTIVITY_MET = {
  walk: { low: 2.5, medium: 3.5, high: 5 }, cardio: { low: 6, medium: 8, high: 10 },
  swim: { low: 5, medium: 7, high: 9 }, strength: { low: 3.5, medium: 5, high: 6 },
  stretch: { low: 2, medium: 2.5, high: 3 }, leisure: { low: 3, medium: 5, high: 7 }, other: { low: 3, medium: 5, high: 7 }
};
function estimateActivityKcal(workout) {
  const weight = state.profileSettings.weightKg;
  if (!weight || !workout) return null;
  const met = (ACTIVITY_MET[workout.type] || ACTIVITY_MET.other)[workout.intensity || 'medium'];
  return Math.round(met * weight * (workout.durationMinutes / 60));
}
/* 0.4.15 (аудит А3#13): интенсивность запоминается по типу активности
   (прогулка → средняя, силовая → высокая…); рядом честная оценка ≈ккал. */
function intensityMemoryLoad(type) {
  try { const m = JSON.parse(localStorage.getItem('fitflow:intensity-by-type') || '{}'); return m[type] || null; } catch (e) { return null; }
}
function intensityMemorySave(type, value) {
  try { const m = JSON.parse(localStorage.getItem('fitflow:intensity-by-type') || '{}'); m[type] = value; localStorage.setItem('fitflow:intensity-by-type', JSON.stringify(m)); } catch (e) { }
}
function currentDurationMinutes() {
  const input = $('#workout-duration');
  const raw = parseFloat(String((input && input.value) || '').replace(',', '.'));
  const base = Number.isFinite(raw) && raw > 0 ? raw : 30;
  const unitLabel = (($('#workout-duration-unit-label') || {}).textContent) || 'мин';
  return unitLabel.indexOf('ч') !== -1 ? Math.round(base * 60) : Math.round(base);
}
function updateActivityKcalHint() {
  const hint = $('#activity-kcal-hint');
  if (!hint) return;
  const mins = currentDurationMinutes();
  const metTable = ACTIVITY_MET[selectedActivityType] || ACTIVITY_MET.other;
  const met = metTable[selectedActivityIntensity || 'medium'];
  const weight = Number(state.profileSettings && state.profileSettings.weightKg) || 0;
  const kcal = Math.round(met * (weight || 70) * (mins / 60));
  hint.textContent = 'Расход: ≈ ' + kcal + ' ккал за ' + mins + ' мин'
    + (weight ? ' (при вашем весе ' + Number(weight).toLocaleString('ru-RU') + ' кг)' : ' — при условном весе 70 кг; укажите вес, станет точнее')
    + '. Оценка по MET — ориентир, не точный замер.';
}

function renderActivityIntensity() {
  $$('#activity-intensity [data-intensity]').forEach((button) => button.classList.toggle('active', button.dataset.intensity === selectedActivityIntensity));
  updateActivityKcalHint();
}

/* ============================================================
   🏋️ Дневник силовых тренировок (0.8.0, шаг 2 / 0.8.4)
   Каталог упражнений по мышечным группам, сеты «вес × повторы»,
   тоннаж и расчёт 1RM (Эпли + Бржицки). Полностью офлайн;
   данные едут в резервную копию вместе с профилем.
============================================================ */
const EXERCISE_CATALOG = {
  'Грудь': ['жим штанги лёжа', 'жим гантелей лёжа', 'жим на наклонной', 'разводка гантелей', 'отжимания от пола'],
  'Спина': ['подтягивания', 'тяга штанги в наклоне', 'тяга верхнего блока', 'тяга гантели к поясу', 'становая тяга'],
  'Ноги': ['приседания со штангой', 'жим ногами', 'выпады', 'румынская тяга', 'подъём на носки'],
  'Плечи': ['жим штанги стоя', 'жим гантелей сидя', 'махи гантелями в стороны', 'тяга к подбородку'],
  'Руки': ['подъём штанги на бицепс', 'подъём гантелей на бицепс', 'жим узким хватом', 'французский жим', 'разгибания на блоке'],
  'Пресс': ['скручивания', 'планка', 'подъём ног в висе', 'велосипед'],
  'Кардио': ['беговая дорожка', 'велотренажёр', 'эллиптический тренажёр', 'гребной тренажёр', 'скакалка']
};
const STRENGTH_GROUPS = Object.keys(EXERCISE_CATALOG);

/* Тоннаж набора подходов: Σ (вес × повторы). */
function computeSetTonnage(sets) {
  return (Array.isArray(sets) ? sets : []).reduce((sum, s) => {
    const w = Number(s && s.weight) || 0;
    const r = Number(s && s.reps) || 0;
    return sum + (w > 0 && r > 0 ? w * r : 0);
  }, 0);
}

/* 1RM по двум формулам (Эпли и Бржицки), берём среднее — устойчивее к крайностям. */
function estimate1RM(weight, reps) {
  const w = Number(weight) || 0;
  const r = Number(reps) || 0;
  if (w <= 0 || r <= 0) return 0;
  if (r <= 1) return Math.round(w);
  const epley = w * (1 + r / 30);
  const brzycki = r < 37 ? w * (36 / (37 - r)) : epley;
  return Math.round((epley + brzycki) / 2);
}

/* 1RM упражнения — максимум оценки по его подходам (лёгкий многоповторный и
   тяжёлый малоповторный дают честную оценку каждый по-своему). */
function computeExercise1RM(sets) {
  const list = (Array.isArray(sets) ? sets : [])
    .filter((s) => Number(s && s.weight) > 0 && Number(s && s.reps) > 0);
  if (!list.length) return 0;
  return Math.max(...list.map((s) => estimate1RM(s.weight, s.reps)));
}

function computeSessionTonnage(session) {
  const exercises = (session && Array.isArray(session.exercises)) ? session.exercises : [];
  return exercises.reduce((sum, ex) => sum + computeSetTonnage(ex && ex.sets), 0);
}

/* ============================================================
   🏅 Уровни силовых (0.8.6) — лестница порогов на упражнение.
   База + расписание шагов: в начале шаг крупный, дальше сжимается,
   в конце «каждый кг — приз». Пороги — прикидочные для прогрессии
   (опора — открытые strength standards), а не официальные нормативы.
============================================================ */
const STRENGTH_LADDER_RULES = [
  { base: 40, steps: [5, 5, 5, 5, 3, 3, 3, 1], keys: ['жим лежа', 'жим лёжа', 'жим штанги лежа', 'жим гантелей лежа', 'жим на наклонной'] },
  { base: 60, steps: [10, 10, 10, 5, 5, 5, 1], keys: ['присед'] },
  { base: 70, steps: [10, 10, 10, 5, 5, 5, 1], keys: ['становая'] },
  { base: 30, steps: [5, 5, 3, 3, 1], keys: ['жим стоя', 'армейский жим', 'жим штанги стоя', 'жим гантелей сидя'] },
  { base: 30, steps: [5, 5, 3, 3, 1], keys: ['тяга штанги', 'тяга гантели', 'тяга верхнего', 'тяга к подбородку'] },
  { base: 100, steps: [10, 10, 10, 5, 5, 1], keys: ['жим ногами'] }
];
const STRENGTH_GENERIC_LADDER = { base: 20, steps: [5, 5, 3, 3, 1] };

function strengthLadderFor(name) {
  const n = String(name || '').toLowerCase();
  const rule = STRENGTH_LADDER_RULES.find((r) => r.keys.some((k) => n.includes(k)));
  return rule ? { base: rule.base, steps: rule.steps } : STRENGTH_GENERIC_LADDER;
}

/* Порог уровня `level` (level=0 → база). После исчерпания списка шаг повторяется последним. */
function strengthTargetAt(ladder, level) {
  const l = (ladder && Number.isFinite(Number(ladder.base))) ? ladder : STRENGTH_GENERIC_LADDER;
  let t = Number(l.base);
  for (let i = 0; i < level; i++) {
    t += l.steps[Math.min(i, l.steps.length - 1)];
  }
  return Math.round(t * 10) / 10;
}

/* Уровень по лучшему 1RM: сколько порогов ≤ PR + следующая цель. */
function computeStrengthLevel(name, prKg) {
  const ladder = strengthLadderFor(name);
  const pr = Math.max(0, Number(prKg) || 0);
  let level = 0;
  let target = strengthTargetAt(ladder, 0);
  while (target <= pr) {
    level++;
    target = strengthTargetAt(ladder, level);
  }
  return {
    ladder,
    level,
    nextTarget: target,
    nextDelta: Math.max(0, Math.round((target - pr) * 10) / 10)
  };
}

/* 0.8.10: баланс нагрузки за последние N дней — минуты и ккал по категориям.
   Чистая функция (тестируется). Кардио = бег + велосипед + плавание. */
function computeLoadBalance(workouts, days, weightKg) {
  const cutoff = statsDateKey((Number(days) || 7) - 1);
  const cats = {
    strength: { label: 'Сила', minutes: 0, kcal: 0 },
    cardio: { label: 'Кардио', minutes: 0, kcal: 0 },
    stretch: { label: 'Растяжка', minutes: 0, kcal: 0 },
    other: { label: 'Другое', minutes: 0, kcal: 0 }
  };
  const weight = Number(weightKg) || 70;
  (Array.isArray(workouts) ? workouts : []).forEach((w) => {
    if (!w || !w.date || w.date < cutoff) return;
    const minutes = Number(w.durationMinutes) || 0;
    if (minutes <= 0) return;
    let key;
    if (w.type === 'strength') key = 'strength';
    else if (w.type === 'cardio' || w.type === 'bike' || w.type === 'swim') key = 'cardio';
    else if (w.type === 'stretch') key = 'stretch';
    else key = 'other';
    const met = (ACTIVITY_MET[w.type] || ACTIVITY_MET.other)[w.intensity || 'medium'];
    cats[key].minutes += minutes;
    cats[key].kcal += Math.round(met * weight * (minutes / 60));
  });
  return cats;
}

/* Нормализация сохранённых силовых (после загрузки/импорта/порчи). */
function normalizeStrengthSessions() {
  const list = Array.isArray(state.strengthSessions) ? state.strengthSessions : [];
  state.strengthSessions = list
    .filter((s) => s && typeof s === 'object' && /^\d{4}-\d{2}-\d{2}$/.test(s.date))
    .map((s) => {
      const exercises = (Array.isArray(s.exercises) ? s.exercises : [])
        .map((ex) => {
          const name = String((ex && ex.name) || '').trim().slice(0, 80);
          if (!name) return null;
          const sets = (Array.isArray(ex && ex.sets) ? ex.sets : [])
            .map((set) => ({
              weight: Math.max(0, Math.min(2000, Math.round(Number(set && set.weight) || 0))),
              reps: Math.max(0, Math.min(1000, Math.round(Number(set && set.reps) || 0)))
            }))
            .filter((set) => set.weight > 0 || set.reps > 0)
            .slice(0, 40);
          return { name, sets };
        })
        .filter(Boolean)
        .slice(0, 30);
      const dur = Number(s.durationMinutes);
      return {
        id: String(s.id || uid()),
        date: s.date,
        title: normalizeActivityName(s.title) || null,
        durationMinutes: (Number.isFinite(dur) && dur >= 5 && dur <= 1440) ? Math.round(dur) : null,
        exercises,
        createdAt: Number(s.createdAt) || Date.now()
      };
    })
    .filter((s) => s.exercises.length > 0)
    .sort((a, b) => b.createdAt - a.createdAt);
}

/* 0.8.8: шаблоны силовых — сохранённая структура тренировки (упражнения с
   рабочими весами), из которой можно начать новую сессию одним тапом. */
function normalizeStrengthTemplatesList(list) {
  const seen = new Set();
  return (Array.isArray(list) ? list : [])
    .filter((t) => t && typeof t === 'object')
    .map((t) => {
      const name = String((t.name || '').trim()).slice(0, 60);
      if (!name) return null;
      const exercises = (Array.isArray(t.exercises) ? t.exercises : [])
        .map((ex) => {
          const ename = String((ex && ex.name) || '').trim().slice(0, 80);
          if (!ename) return null;
          const sets = (Array.isArray(ex && ex.sets) ? ex.sets : [])
            .map((set) => ({
              weight: Math.max(0, Math.min(2000, Math.round(Number(set && set.weight) || 0))),
              reps: Math.max(0, Math.min(1000, Math.round(Number(set && set.reps) || 0)))
            }))
            .filter((set) => set.weight > 0 || set.reps > 0)
            .slice(0, 40);
          return { name: ename, sets };
        })
        .filter(Boolean)
        .slice(0, 30);
      return { id: String(t.id || uid()), name, exercises, createdAt: Number(t.createdAt) || Date.now() };
    })
    .filter((t) => t && !seen.has(t.name.toLowerCase()) && seen.add(t.name.toLowerCase()))
    .slice(0, 24)
    .sort((a, b) => a.createdAt - b.createdAt);
}

function normalizeStrengthTemplates() {
  state.strengthTemplates = normalizeStrengthTemplatesList(state.strengthTemplates);
}

function saveStrengthTemplate() {
  const name = String(strengthDraft.title || '').trim();
  if (!name) { toast('Дайте шаблону название (поле «Название»)'); return; }
  const exercises = strengthDraft.exercises
    .map((ex) => ({
      name: ex.name,
      sets: ex.sets.map((s) => ({ weight: Math.round(Number(s.weight) || 0), reps: Math.round(Number(s.reps) || 0) }))
    }))
    .filter((ex) => ex.sets.length > 0);
  if (!exercises.length) { toast('Добавьте хотя бы один подход'); return; }
  normalizeStrengthTemplates();
  if (state.strengthTemplates.some((t) => t.name.toLowerCase() === name.toLowerCase())) {
    toast('Шаблон с таким названием уже есть — переименуйте');
    return;
  }
  state.strengthTemplates.push({ id: uid(), name, exercises, createdAt: Date.now() });
  normalizeStrengthTemplates();
  saveState();
  renderStrengthDiary();
  toast('✓ Шаблон «' + name + '» сохранён');
}

function startStrengthFromTemplate(id) {
  const t = (state.strengthTemplates || []).find((x) => x.id === id);
  if (!t) return;
  strengthDraft = {
    title: t.name,
    durationMinutes: '',
    exercises: t.exercises.map((ex) => ({ name: ex.name, sets: ex.sets.map((s) => ({ weight: s.weight, reps: s.reps })) }))
  };
  renderStrengthDiary();
  toast('Шаблон «' + t.name + '» подставлен — поправьте веса и сохраните');
}

function deleteStrengthTemplate(id) {
  normalizeStrengthTemplates();
  state.strengthTemplates = state.strengthTemplates.filter((t) => t.id !== id);
  // 0.8.9: убираем из плана записи удалённого шаблона.
  normalizeStrengthPlan();
  state.strengthPlan = state.strengthPlan.filter((p) => p.templateId !== id);
  saveState();
  renderStrengthDiary();
  renderStrengthPlan();
}

/* ============================================================
   📅 План тренировок (0.8.9): шаблоны по дням недели.
   Минимально: назначаете шаблон дням — приложение подсказывает
   «что сегодня» и отмечает выполненное (сессия с именем шаблона
   сохранена сегодня). Ссылка на шаблон, не копия упражнений.
============================================================ */
const STRENGTH_PLAN_DAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];

function strengthTodayDow() {
  return (new Date().getDay() + 6) % 7; // 0=Пн … 6=Вс
}

function normalizeStrengthPlanList(list) {
  const seen = new Set();
  return (Array.isArray(list) ? list : [])
    .filter((p) => p && typeof p === 'object' && typeof p.templateId === 'string' && p.templateId)
    .map((p) => {
      const days = Array.from(new Set((Array.isArray(p.days) ? p.days : [])
        .map(Number)
        .filter((d) => Number.isInteger(d) && d >= 0 && d <= 6))).sort((a, b) => a - b);
      return { id: String(p.id || uid()), templateId: p.templateId, days };
    })
    .filter((p) => p.days.length > 0 && !seen.has(p.templateId) && seen.add(p.templateId))
    .slice(0, 24);
}

function normalizeStrengthPlan() {
  state.strengthPlan = normalizeStrengthPlanList(state.strengthPlan);
}

function togglePlanDay(templateId, day) {
  normalizeStrengthPlan();
  const entry = state.strengthPlan.find((p) => p.templateId === templateId);
  if (!entry) {
    if (day == null) return;
    state.strengthPlan.push({ id: uid(), templateId, days: [day] });
  } else {
    const idx = entry.days.indexOf(day);
    if (idx >= 0) entry.days.splice(idx, 1);
    else if (day != null) entry.days.push(day);
    if (!entry.days.length) state.strengthPlan = state.strengthPlan.filter((p) => p.templateId !== templateId);
  }
  normalizeStrengthPlan();
  saveState();
  renderStrengthPlan();
}

/* ============================================================
   ⏱ Таймер отдыха между подходами (0.8.10)
   Минимально: пресеты 30/60/90/120 с, отсчёт, вибрация в конце.
   Не привязан к renderStrengthDiary — живёт в своей строке, чтобы
   не сбрасываться при правках дневника.
============================================================ */
let strengthRestTimer = { seconds: 90, remaining: 0, timerId: null };

function setStrengthRestSeconds(seconds) {
  strengthRestTimer.seconds = Math.max(10, Math.min(600, Number(seconds) || 90));
  stopStrengthRest(false);
  renderStrengthRestTimer();
}

function startStrengthRest() {
  stopStrengthRest(false);
  strengthRestTimer.remaining = strengthRestTimer.seconds;
  renderStrengthRestTimer();
  strengthRestTimer.timerId = setInterval(() => {
    strengthRestTimer.remaining--;
    if (strengthRestTimer.remaining <= 0) {
      stopStrengthRest(true);
      return;
    }
    renderStrengthRestTimer();
  }, 1000);
}

function stopStrengthRest(notify) {
  if (strengthRestTimer.timerId) clearInterval(strengthRestTimer.timerId);
  strengthRestTimer.timerId = null;
  strengthRestTimer.remaining = 0;
  if (notify) {
    try { if (navigator.vibrate) navigator.vibrate([200, 100, 200]); } catch (e) { }
    toast('⏱ Отдых окончен — следующий подход');
  }
  renderStrengthRestTimer();
}

function renderStrengthRestTimer() {
  if (typeof document === 'undefined') return;
  const start = $('#strength-rest-start');
  const count = $('#strength-rest-count');
  if (start) start.textContent = strengthRestTimer.timerId ? 'Стоп' : 'Старт';
  if (count) {
    const active = !!strengthRestTimer.timerId;
    count.hidden = !active;
    if (active) {
      const m = Math.floor(strengthRestTimer.remaining / 60);
      const s = strengthRestTimer.remaining % 60;
      count.textContent = m + ':' + String(s).padStart(2, '0');
    }
  }
  const presets = document.querySelectorAll('#strength-rest-presets [data-rest]');
  if (presets.length) {
    presets.forEach((btn) => btn.classList.toggle('on', Number(btn.dataset.rest) === strengthRestTimer.seconds));
  }
}

function renderWeeklyLoadBalance() {
  const el = $('#weekly-load-balance');
  if (!el) return;
  const cats = computeLoadBalance(state.workouts, 7, (state.profileSettings && state.profileSettings.weightKg) || null);
  const parts = ['strength', 'cardio', 'stretch', 'other']
    .filter((k) => cats[k].minutes > 0)
    .map((k) => `${cats[k].label} ${formatWorkoutDuration(cats[k].minutes)}`);
  el.textContent = parts.length ? 'Баланс за 7 дней: ' + parts.join(' · ') : 'Баланс нагрузки появится после тренировок';
}

/* Выполнена ли тренировка по шаблону сегодня (сессия с тем же именем). */
function isPlanDoneToday(templateId) {
  const t = (state.strengthTemplates || []).find((x) => x.id === templateId);
  if (!t) return false;
  const name = t.name.toLowerCase();
  return (state.strengthSessions || []).some((s) => s.date === todayKey() && String(s.title || '').toLowerCase() === name);
}

function renderStrengthPlan() {
  if (typeof document === 'undefined') return;
  const box = $('#strength-plan');
  if (!box) return;
  const templates = state.strengthTemplates || [];
  const plan = normalizeStrengthPlanList(state.strengthPlan);
  const dow = strengthTodayDow();

  let html = '';
  if (!templates.length) {
    box.innerHTML = '<p class="strength-empty">Сначала сохраните шаблон тренировки — затем назначьте его дням недели.</p>';
    return;
  }

  // «Сегодня по плану»
  const todayPlan = plan.filter((p) => p.days.includes(dow))
    .map((p) => templates.find((t) => t.id === p.templateId)).filter(Boolean);
  html += '<p class="strength-plan-today">Сегодня · ' + STRENGTH_PLAN_DAYS[dow] + '</p>';
  if (todayPlan.length) {
    html += '<div class="strength-plan-today-list">';
    todayPlan.forEach((t) => {
      const done = isPlanDoneToday(t.id);
      html += `<div class="strength-plan-today-row">
        <span class="strength-plan-name">${done ? '✅' : '⬜'} ${escapeHtml(t.name)}</span>
        ${done ? '<span class="strength-plan-done">выполнено</span>'
          : `<button class="watch-btn watch-btn-add" type="button" data-s-plan-start="${escapeHtml(t.id)}">Выполнить</button>`}
      </div>`;
    });
    html += '</div>';
  } else {
    html += '<p class="strength-empty">На сегодня ничего не назначено — отметьте дни ниже.</p>';
  }

  // Сетка: шаблон × дни недели
  html += '<div class="strength-plan-grid">';
  html += '<div class="strength-plan-head"><span>Шаблон</span>' + STRENGTH_PLAN_DAYS.map((d) => `<span>${d}</span>`).join('') + '</div>';
  templates.forEach((t) => {
    const entry = plan.find((p) => p.templateId === t.id) || { days: [] };
    html += `<div class="strength-plan-row"><span class="strength-plan-name">${escapeHtml(t.name)}</span>`
      + STRENGTH_PLAN_DAYS.map((d, i) =>
        `<button type="button" class="strength-plan-day${entry.days.includes(i) ? ' on' : ''}" data-s-plan-day="${escapeHtml(t.id)}" data-s-plan-dow="${i}" aria-pressed="${entry.days.includes(i)}" aria-label="${escapeHtml(t.name)} — ${d}">${d}</button>`).join('')
      + '</div>';
  });
  html += '</div>';

  box.innerHTML = html;
}

/* Черновик (в памяти, до сохранения) и текущая группа в выборе упражнения. */
let strengthDraft = { title: '', durationMinutes: '', exercises: [] };
let strengthPickerGroup = STRENGTH_GROUPS[0];

function openStrengthExercisePicker() {
  if (!STRENGTH_GROUPS.includes(strengthPickerGroup)) strengthPickerGroup = STRENGTH_GROUPS[0];
  renderStrengthPicker();
  $('#strength-exercise-dialog').hidden = false;
}
function closeStrengthExercisePicker() {
  $('#strength-exercise-dialog').hidden = true;
  const input = $('#strength-custom-name');
  if (input) input.value = '';
}
function renderStrengthPicker() {
  const groupsEl = $('#strength-groups');
  const listEl = $('#strength-exercise-list');
  if (!groupsEl || !listEl) return;
  groupsEl.innerHTML = STRENGTH_GROUPS.map((g) =>
    `<button type="button" class="chip chip-sm ${g === strengthPickerGroup ? 'active' : ''}" data-s-group="${escapeHtml(g)}">${escapeHtml(g)}</button>`).join('');
  const exes = EXERCISE_CATALOG[strengthPickerGroup] || [];
  listEl.innerHTML = exes.map((name) =>
    `<button type="button" class="strength-exercise-btn" data-s-pick="${escapeHtml(name)}">${escapeHtml(name)}</button>`).join('');
}
function addStrengthExercise(name) {
  const clean = String(name || '').trim();
  if (!clean) return;
  if (strengthDraft.exercises.some((ex) => ex.name.toLowerCase() === clean.toLowerCase())) {
    toast('Упражнение уже в тренировке');
    return;
  }
  strengthDraft.exercises.push({ name: clean, sets: [{ weight: '', reps: '' }] });
}
function removeStrengthExercise(idx) {
  strengthDraft.exercises.splice(idx, 1);
  renderStrengthDiary();
}
function addStrengthSet(idx) {
  const ex = strengthDraft.exercises[idx];
  if (ex && ex.sets.length < 40) ex.sets.push({ weight: '', reps: '' });
  renderStrengthDiary();
}
function removeStrengthSet(idx, setIdx) {
  const ex = strengthDraft.exercises[idx];
  if (ex && ex.sets[setIdx]) ex.sets.splice(setIdx, 1);
  renderStrengthDiary();
}
function updateStrengthSummary(idx) {
  const el = document.querySelector(`[data-s-summary="${idx}"]`);
  if (!el) return;
  const ex = strengthDraft.exercises[idx];
  if (!ex) return;
  const valid = ex.sets.filter((s) => Number(s.weight) > 0 && Number(s.reps) > 0);
  const tonnage = computeSetTonnage(valid);
  const rm = computeExercise1RM(valid);
  el.textContent = valid.length
    ? `тоннаж ${fmt(tonnage)} кг · 1RM ≈ ${fmt(rm)} кг`
    : 'укажите вес и повторы';
}

function renderStrengthDiary() {
  if (typeof document === 'undefined') return;
  const box = $('#strength-diary');
  if (!box) return;
  const today = todayKey();
  const sessions = (state.strengthSessions || []).filter((s) => s.date === today);

  let html = '';
  html += '<div class="strength-meta">'
    + `<label class="strength-title-field"><span>Название (необязательно)</span><input type="text" class="form-input" maxlength="60" placeholder="Например, День ног" value="${escapeHtml(strengthDraft.title)}" data-s-title></label>`
    + `<label class="strength-title-field"><span>Длительность, мин (в недельную цель)</span><input type="number" inputmode="numeric" min="0" step="5" placeholder="Например, 60" value="${escapeHtml(strengthDraft.durationMinutes)}" data-s-duration aria-label="Длительность силовой в минутах"></label>`
    + '</div>';
  if (strengthDraft.exercises.length) {
    html += '<div class="strength-exercises">';
    strengthDraft.exercises.forEach((ex, idx) => {
      const setsHtml = ex.sets.map((set, si) => `
        <div class="strength-set">
          <input type="number" inputmode="decimal" min="0" step="0.5" placeholder="Вес, кг" value="${escapeHtml(set.weight)}" data-s-field="weight" data-s-ex="${idx}" data-s-set="${si}" aria-label="Вес в килограммах">
          <span class="strength-set-x">×</span>
          <input type="number" inputmode="numeric" min="0" step="1" placeholder="Повторы" value="${escapeHtml(set.reps)}" data-s-field="reps" data-s-ex="${idx}" data-s-set="${si}" aria-label="Количество повторов">
          <button class="strength-set-remove" type="button" data-s-remove-set="${idx}" data-s-set="${si}" aria-label="Удалить подход">×</button>
        </div>`).join('');
      const valid = ex.sets.filter((s) => Number(s.weight) > 0 && Number(s.reps) > 0);
      const tonnage = computeSetTonnage(valid);
      const rm = computeExercise1RM(valid);
      const summary = valid.length ? `тоннаж ${fmt(tonnage)} кг · 1RM ≈ ${fmt(rm)} кг` : 'укажите вес и повторы';
      html += `
        <div class="strength-exercise">
          <div class="strength-exercise-head">
            <strong>${escapeHtml(ex.name)}</strong>
            <span class="strength-exercise-summary" data-s-summary="${idx}">${summary}</span>
            <button class="strength-exercise-remove" type="button" data-s-remove-exercise="${idx}" aria-label="Удалить упражнение">×</button>
          </div>
          ${setsHtml}
          <button class="strength-set-add" type="button" data-s-add-set="${idx}">＋ подход</button>
        </div>`;
    });
    html += '</div>';
  } else {
    html += '<p class="strength-empty">Добавьте упражнение и подходы — приложение посчитает тоннаж и расчётный 1RM.</p>';
  }
  html += '<button class="btn btn-secondary" type="button" data-s-add-exercise>＋ Добавить упражнение</button>';
  html += '<button class="btn btn-primary training-add-btn" type="button" data-s-save>Сохранить силовую</button>';
  html += `<button class="btn btn-ghost" type="button" data-s-save-template>⭐ Сохранить как шаблон</button>`;

  // Шаблоны: начать одним тапом
  const templates = state.strengthTemplates || [];
  if (templates.length) {
    html += '<div class="strength-templates"><p class="strength-templates-hint">Шаблоны</p>';
    templates.forEach((t) => {
      const first = (t.exercises[0] || {}).name || '';
      html += `<div class="strength-template-row">
        <div class="strength-template-info"><strong>${escapeHtml(t.name)}</strong><span>${t.exercises.length} упр.${first ? ' · ' + escapeHtml(first) : ''}</span></div>
        <div class="strength-template-actions">
          <button class="watch-btn watch-btn-add" type="button" data-s-start-template="${escapeHtml(t.id)}">Начать</button>
          <button class="watch-btn watch-btn-ghost" type="button" data-s-del-template="${escapeHtml(t.id)}" aria-label="Удалить шаблон">×</button>
        </div>
      </div>`;
    });
    html += '</div>';
  }

  if (sessions.length) {
    html += '<div class="strength-saved"><p class="strength-saved-hint">Сегодня сохранено:</p>';
    sessions.forEach((s) => {
      html += `<div class="strength-saved-row"><span>🏋️ ${escapeHtml(s.title || 'Силовая тренировка')}</span><span>${s.exercises.length} упр. · ${fmt(computeSessionTonnage(s))} кг</span></div>`;
    });
    html += '</div>';
  }
  box.innerHTML = html;
}

function saveStrengthSession() {
  const title = String(strengthDraft.title || '').trim();
  const exercises = strengthDraft.exercises
    .map((ex) => ({
      name: ex.name,
      sets: ex.sets
        .map((s) => ({ weight: Math.round(Number(s.weight) || 0), reps: Math.round(Number(s.reps) || 0) }))
        .filter((s) => s.weight > 0 && s.reps > 0)
    }))
    .filter((ex) => ex.sets.length > 0);
  if (!exercises.length) {
    toast('Добавьте хотя бы один подход: вес (кг) × повторы');
    return;
  }
  // 0.8.6: уровни ДО сохранения — чтобы поймать «уровень поднят» как момент награды.
  const beforeLevels = new Map(
    computeStrengthRecords(state.strengthSessions).map((r) => [r.name.toLowerCase(), computeStrengthLevel(r.name, r.best1RM).level])
  );
  // 0.8.5: длительность силовой засчитывается в недельную цель активности —
  // это одна запись тренировки, а не два независимых места (дневник + минуты).
  let durMin = Math.round(Number(String(strengthDraft.durationMinutes || '').replace(',', '.')));
  if (!Number.isFinite(durMin) || durMin < 0) durMin = 0;
  if (durMin > 1440) durMin = 1440;
  const sessionTitle = normalizeActivityName(title) || 'Силовая тренировка';
  state.strengthSessions.unshift({
    id: uid(),
    date: todayKey(),
    title: sessionTitle,
    durationMinutes: durMin || null,
    exercises,
    createdAt: Date.now()
  });
  if (durMin >= 5) {
    state.workouts.unshift({
      id: uid(),
      date: todayKey(),
      type: 'strength',
      title: sessionTitle,
      note: 'из дневника силовых',
      intensity: 'medium',
      durationMinutes: durMin,
      createdAt: Date.now()
    });
  }
  normalizeStrengthSessions();
  const totalTonnage = exercises.reduce((s, ex) => s + computeSetTonnage(ex.sets), 0);
  strengthDraft = { title: '', durationMinutes: '', exercises: [] };
  saveState();
  renderTraining(); // обновляет и недельную цель, и дневник силовых
  // 0.8.6: моменты награды — какие упражнения подняли уровень.
  const ups = computeStrengthRecords(state.strengthSessions)
    .filter((r) => computeStrengthLevel(r.name, r.best1RM).level > (beforeLevels.get(r.name.toLowerCase()) || 0))
    .map((r) => `${r.name} → Lv ${computeStrengthLevel(r.name, r.best1RM).level}`);
  const upText = ups.length ? ` 🏅 Новый уровень: ${ups.join(' · ')}` : '';
  toast(`✓ Силовая сохранена: ${exercises.length} упр. · тоннаж ${fmt(totalTonnage)} кг${durMin >= 5 ? ` · +${durMin} мин в цель недели` : ''}${upText}`);
}

/* 0.8.5: личные рекорды по упражнениям (прогресс) — чистый расчёт для тестов. */
function computeStrengthRecords(sessions) {
  const map = new Map();
  (Array.isArray(sessions) ? sessions : []).forEach((s) => {
    (Array.isArray(s.exercises) ? s.exercises : []).forEach((ex) => {
      const name = String((ex && ex.name) || '').trim();
      if (!name) return;
      const key = name.toLowerCase();
      const rec = map.get(key) || { name, best1RM: 0, bestWeight: 0, bestReps: 0, bestSetTonnage: 0, lastDate: '' };
      const rm = computeExercise1RM(ex.sets);
      if (rm > rec.best1RM) rec.best1RM = rm;
      (Array.isArray(ex.sets) ? ex.sets : []).forEach((set) => {
        const w = Number(set && set.weight) || 0;
        const r = Number(set && set.reps) || 0;
        if (w > 0 && r > 0 && (w > rec.bestWeight || (w === rec.bestWeight && r > rec.bestReps))) {
          rec.bestWeight = w;
          rec.bestReps = r;
          rec.bestSetTonnage = w * r;
        }
      });
      if (s.date > rec.lastDate) rec.lastDate = s.date;
      map.set(key, rec);
    });
  });
  return Array.from(map.values()).sort((a, b) => b.best1RM - a.best1RM);
}

function renderStrengthHistory() {
  if (typeof document === 'undefined') return;
  const box = $('#strength-history');
  if (!box) return;
  const sessions = Array.isArray(state.strengthSessions) ? state.strengthSessions : [];
  const records = computeStrengthRecords(sessions);
  let html = '';
  if (records.length) {
    html += '<p class="strength-history-hint">Личные рекорды по упражнениям</p><div class="strength-records">';
    records.slice(0, 20).forEach((r) => {
      const lvl = computeStrengthLevel(r.name, r.best1RM);
      const levelTag = lvl.level >= 1 ? ` · Lv ${lvl.level}` : '';
      const goal = lvl.nextDelta > 0
        ? `🏅 цель: ${fmt(lvl.nextTarget)} кг (+${fmt(lvl.nextDelta)} кг)`
        : `🏅 цель: ${fmt(lvl.nextTarget)} кг`;
      html += `<div class="strength-record"><strong>${escapeHtml(r.name)}${levelTag}</strong><span>1RM ≈ ${fmt(r.best1RM)} кг · лучший подход ${fmt(r.bestWeight)} кг × ${r.bestReps} · ${formatWeightDate(r.lastDate)}</span><span class="strength-record-goal">${goal}</span></div>`;
    });
    html += '</div>';
  }
  const sorted = [...sessions].sort((a, b) => (b.date > a.date ? 1 : (b.date < a.date ? -1 : b.createdAt - a.createdAt)));
  if (sorted.length) {
    html += '<p class="strength-history-hint">Прошедшие тренировки</p><div class="strength-history-list">';
    sorted.slice(0, 30).forEach((s) => {
      const dur = s.durationMinutes ? ` · ${formatWorkoutDuration(s.durationMinutes)}` : '';
      html += `<div class="strength-history-row"><span>${escapeHtml(s.date)} · ${escapeHtml(s.title || 'Силовая тренировка')}</span><span>${s.exercises.length} упр. · ${fmt(computeSessionTonnage(s))} кг${dur}</span></div>`;
    });
    html += '</div>';
  }
  if (!records.length && !sorted.length) {
    html = '<p class="strength-empty">Сохраните первую силовую — здесь появятся рекорды и история.</p>';
  }
  box.innerHTML = html;
}

if (typeof window !== 'undefined') {
  window.openStrengthExercisePicker = openStrengthExercisePicker;
  window.closeStrengthExercisePicker = closeStrengthExercisePicker;
}

function renderTraining() {
  if (typeof document === 'undefined') return;
  const list = $('#training-list');
  const total = $('#training-total');
  if (!list || !total) return;

  const workouts = getWorkoutsForDate();
  const totalMinutes = workouts.reduce((sum, workout) => sum + workout.durationMinutes, 0);
  if (workouts.length === 0) {
    total.textContent = '0 мин';
    list.innerHTML = '<li class="workout-empty">Выберите вид активности, укажите длительность и добавьте первую запись 🚶</li>';
  } else {
    total.textContent = `${formatWorkoutDuration(totalMinutes)} (${workouts.length} ${activityCountText(workouts.length)})`;
    list.innerHTML = workouts.map((workout) => {
      const type = ACTIVITY_TYPES[workout.type] || ACTIVITY_TYPES.other;
      const title = workout.title || type.label;
      return `
        <li class="workout-item" data-workout-id="${workout.id}">
          <span class="workout-item-emoji" aria-hidden="true">${type.emoji}</span>
          <div class="workout-item-info">
            <p>${escapeHtml(title)}</p>
            <span>${formatWorkoutDuration(workout.durationMinutes)}${estimateActivityKcal(workout) != null ? ` · <span class="energy-estimate">≈ ${estimateActivityKcal(workout)} ккал</span>` : ''}${workout.note ? ` · ${escapeHtml(workout.note)}` : ''}</span>
          </div>
          <button class="workout-item-edit" data-edit-workout="${workout.id}" type="button" aria-label="Изменить активность «${escapeHtml(title)}»" title="Изменить">✏️</button>
          <button class="workout-item-export" data-export-workout="${workout.id}" type="button" aria-label="Записать в Health Connect" title="Записать тренировку в Health Connect">
            <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 16V4m0 0L7.5 8.5M12 4l4.5 4.5M4 16v4h16v-4" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
          </button>
          <button class="workout-item-remove" data-remove-workout="${workout.id}" type="button" aria-label="Удалить активность «${escapeHtml(title)}»">
            <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M6 6l12 12M18 6 6 18" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
            </svg>
          </button>
        </li>`;
    }).join('');
  }
  const weeklyMinutes = getStatsDays('week').reduce((sum, day) => sum + day.activityMinutes, 0);
  const weeklyGoal = state.activitySettings.weeklyGoalMinutes;
  // 0.4.15 (аудит А2): перевыполнение — успех, а не цифра «как ошибка».
  const weeklyOver = weeklyMinutes - weeklyGoal;
  // 0.5.2 — порядок «выполнено ИЗ цели». 0.5.5 (владелец: «надпись длинная,
  // на несколько строк, проще графиком»): числа коротко, итог — цветным чипом,
  // длинные объяснения уехали в «?». Арифметика та же, проверена 0.5.2.
  $('#weekly-activity-total').textContent =
    `${formatActivityDuration(weeklyMinutes)} из ${formatActivityDuration(weeklyGoal)}`;
  const weeklyChip = $('#weekly-status-chip');
  if (weeklyChip) {
    if (weeklyOver > 0) {
      weeklyChip.textContent = `✓ +${formatActivityDuration(weeklyOver)}`;
      weeklyChip.className = 'weekly-status-chip good';
    } else if (weeklyOver === 0) {
      weeklyChip.textContent = '✓ в цель';
      weeklyChip.className = 'weekly-status-chip good';
    } else {
      weeklyChip.textContent = `осталось ${formatActivityDuration(weeklyGoal - weeklyMinutes)}`;
      weeklyChip.className = 'weekly-status-chip todo';
    }
  }
  const progressEl = $('#weekly-activity-progress');
  if (progressEl) {
    const pct = (weeklyMinutes / Math.max(1, weeklyGoal)) * 100;
    progressEl.style.width = `${Math.min(100, pct)}%`;
    if (weeklyOver > 0) {
      progressEl.classList.add('over-goal');
    } else {
      progressEl.classList.remove('over-goal');
    }
  }
  renderActivityTypeSelection();
  renderActivityTemplates();
  renderDayChecklist();
  renderWatchWorkoutsSuggest(); // 0.8.0: подсказка «нашли тренировку с часов»
  renderStrengthDiary(); // 0.8.4: дневник силовых
  renderStrengthHistory(); // 0.8.5: рекорды и история силовых
  renderStrengthPlan(); // 0.8.9: план тренировок по дням недели
  renderStrengthRestTimer(); // 0.8.10: таймер отдыха
  renderWeeklyLoadBalance(); // 0.8.10: баланс нагрузки за 7 дней
}

async function syncTrainingReminderForToday() {
  if (!state.reminders.enabled) return true;
  // Тихая синхронизация: разрешение спрашиваем только при ЯВНОМ включении
  // пользователем — иначе после каждой сохранённой активности всплывал бы
  // системный запрос «разрешить уведомления» совсем не ко времени.
  const result = await scheduleTrainingReminder({
    skipToday: hasWorkoutToday(),
    clearDelivered: hasWorkoutToday(),
    requestPermission: false
  });
  return result.ok;
}

async function addActivity(template = null) {
  const durationInput = $('#workout-duration');
  const durationMinutes = template ? template.durationMinutes : parseWorkoutDuration(durationInput.value, selectedDurationUnit);
  if (!durationMinutes) {
    toast('Укажите длительность от 5 минут до 24 часов: например, 1,5');
    durationInput.focus();
    return;
  }

  const type = template
    ? template.type
    : (ACTIVITY_TYPES[selectedActivityType] ? selectedActivityType : 'other');
  const title = template ? template.name : null;
  const note = template ? null : normalizeOptionalNote($('#activity-note').value);
  const saveAsTemplate = !template && $('#activity-save-template').checked;
  const templateName = saveAsTemplate ? normalizeActivityName($('#activity-template-name').value) : null;
  if (saveAsTemplate && !templateName) {
    toast('Введите название готового варианта или выключите сохранение шаблона');
    $('#activity-template-name').focus();
    return;
  }
  // 0.5.0: запись задним числом — дата берётся из формы (по умолчанию сегодня).
  const dateInput = !template && $('#workout-date');
  const chosenDate = (dateInput && dateInput.value) ? dateInput.value : todayKey();
  if (chosenDate !== todayKey() && !validPastOrTodayDate(chosenDate)) {
    toast('Дата активности — не позже сегодняшней');
    return;
  }
  state.workouts.unshift({
    id: uid(),
    date: chosenDate,
    type,
    title,
    note,
    intensity: template ? 'medium' : selectedActivityIntensity,
    durationMinutes,
    createdAt: Date.now()
  });
  if (chosenDate !== todayKey()) syncPastDaySummary(chosenDate);
  if (saveAsTemplate) {
    state.activityTemplates.unshift({
      id: uid(), name: templateName, type, durationMinutes, createdAt: Date.now()
    });
    normalizeActivityTemplates();
  }
  saveState();
  if (!template) {
    durationInput.value = '';
    selectedDurationUnit = 'minutes';
    renderDurationUnit();
    $('#activity-note').value = '';
    $('#activity-save-template').checked = false;
    $('#activity-template-name').value = '';
    $('#activity-template-inline').classList.remove('is-open');
    if (dateInput) { dateInput.max = todayKey(); dateInput.value = todayKey(); }
  }
  renderTraining();

  // «Вечернее напоминание на сегодня» трогаем, только если запись за сегодня.
  const reminderUpdated = chosenDate === todayKey() ? await syncTrainingReminderForToday() : true;
  const reminderText = state.reminders.enabled && chosenDate === todayKey()
    ? (reminderUpdated ? ' Напоминание на сегодня отменено.' : ' Не удалось обновить напоминание.')
    : '';
  const label = title || ACTIVITY_TYPES[type].label;
  const dateNote = chosenDate === todayKey() ? '' : ` (${chosenDate.split('-').reverse().join('.')} — видно в статистике)`;
  toast(`${label}: ${formatWorkoutDuration(durationMinutes)} добавлено${dateNote}.${reminderText}`);
}

function saveCurrentAsActivityTemplate() {
  const nameInput = $('#activity-template-name');
  const durationInput = $('#workout-duration');
  const name = normalizeActivityName(nameInput.value);
  const durationMinutes = parseWorkoutDuration(durationInput.value, selectedDurationUnit);
  if (!name) {
    toast('Введите название готового варианта: от 2 до 60 символов');
    nameInput.focus();
    return;
  }
  if (!durationMinutes) {
    toast('Сначала укажите длительность: например, 0,5 или 1,5');
    durationInput.focus();
    return;
  }

  const type = ACTIVITY_TYPES[selectedActivityType] ? selectedActivityType : 'other';
  state.activityTemplates.unshift({
    id: uid(),
    name,
    type,
    durationMinutes,
    createdAt: Date.now()
  });
  saveState();
  nameInput.value = '';
  renderActivityTemplates();
  toast(`Готовый вариант «${name}» сохранён`);
}

function changeWeeklyActivityGoal(delta) {
  const next = Math.min(1440, Math.max(30, state.activitySettings.weeklyGoalMinutes + delta));
  if (next === state.activitySettings.weeklyGoalMinutes) return;
  state.activitySettings.weeklyGoalMinutes = next;
  saveState();
  renderTraining();
}

async function removeWorkout(id) {
  const index = state.workouts.findIndex((item) => item.id === id);
  if (index < 0) return;
  const workout = state.workouts[index];
  state.workouts.splice(index, 1);
  syncPastDaySummary(workout.date); // 0.5.0: сводка прошлого дня — точечно
  saveState();
  renderTraining();

  const reminderUpdated = await syncTrainingReminderForToday();
  const reminderText = state.reminders.enabled && !hasWorkoutToday()
    ? (reminderUpdated ? ' Напоминание снова активно.' : ' Не удалось обновить напоминание.')
    : '';
  // 0.5.0: удаление обратимо — снекбар с «Отменить»
  showUndoSnack(`Активность удалена.${reminderText}`, () => {
    state.workouts.splice(Math.min(index, state.workouts.length), 0, workout);
    syncPastDaySummary(workout.date);
    saveState();
    renderTraining();
    syncTrainingReminderForToday();
    toast('Активность восстановлена');
  });
}

function removeActivityTemplate(id) {
  const template = state.activityTemplates.find((item) => item.id === id);
  if (!template) return;
  state.activityTemplates = state.activityTemplates.filter((item) => item.id !== id);
  saveState();
  renderActivityTemplates();
  toast(`Готовый вариант «${template.name}» удалён`);
}

