const DEFAULT_VENDOR_NOTIFICATION_HINT = {
  title: 'Автозапуск и работа в фоне',
  note: 'Откроются настройки приложения. Найдите пункты про батарею, автозапуск или фоновую работу и снимите ограничения для FitFlow. На «чистом» Android обычно достаточно первых двух шагов.'
};

function getLocalNotifications() {
  if (typeof window === 'undefined' || !window.Capacitor || !window.Capacitor.Plugins) return null;
  return window.Capacitor.Plugins.LocalNotifications || null;
}

function getNativeSettingsBridge() {
  if (typeof window === 'undefined') return null;
  const bridge = window.FitFlowExport || window.AquaExport;
  return bridge && typeof bridge.openSettingsScreen === 'function' ? bridge : null;
}

function reminderTimeText(time) {
  return isValidReminderTime(time) ? time : DEFAULTS.reminders.time;
}

function canScheduleReminderToday(time, hasDataForToday, now = new Date()) {
  if (hasDataForToday || !isValidReminderTime(time)) return false;
  const [hours, minutes] = time.split(':').map(Number);
  const scheduled = new Date(now.getTime());
  scheduled.setHours(hours, minutes, 0, 0);
  return scheduled > now;
}

function nextReminderDate(time, skipToday = false) {
  const [hours, minutes] = reminderTimeText(time).split(':').map(Number);
  const next = new Date();
  next.setHours(hours, minutes, 0, 0);
  if (skipToday || next <= new Date()) next.setDate(next.getDate() + 1);
  return next;
}

function getVendorNotificationHint() {
  const bridge = getNativeSettingsBridge();
  let manufacturer = '';
  try {
    if (bridge && typeof bridge.getManufacturer === 'function') {
      manufacturer = String(bridge.getManufacturer() || '').toLowerCase();
    }
  } catch (e) {
    console.warn('Не удалось определить производителя телефона:', e);
  }

  for (const name of Object.keys(VENDOR_NOTIFICATION_HINTS)) {
    if (manufacturer.includes(name)) return VENDOR_NOTIFICATION_HINTS[name];
  }
  return DEFAULT_VENDOR_NOTIFICATION_HINT;
}

/* 0.4.15 (аудит А3#52): честный бюджет — «сегодня может прийти до N». */
function computeTodayNotificationBudget() {
  const parts = [];
  let total = 0;
  if (state.morningMotivation && state.morningMotivation.enabled) { total += 1; parts.push('мотивация — 1'); }
  const meals = (state.mealReminders && state.mealReminders.enabled && Array.isArray(state.mealReminders.meals))
    ? state.mealReminders.meals.filter((m) => m && m.enabled !== false).length : 0;
  if (meals) { total += meals; parts.push('питание — ' + meals); }
  if (state.reminders && state.reminders.enabled) { total += 1; parts.push('вечерняя активность — 1'); }
  if (state.dayMoodReminder && state.dayMoodReminder.enabled) { total += 1; parts.push('оценка дня — 1'); }
  if (state.waterReminders && state.waterReminders.enabled) {
    const from = String(state.waterReminders.windowStart || '08:00').split(':').map(Number);
    const till = String(state.waterReminders.windowEnd || '22:00').split(':').map(Number);
    const spanMin = (till[0] * 60 + (till[1] || 0)) - (from[0] * 60 + (from[1] || 0));
    const interval = Math.max(15, Number(state.waterReminders.interval) || 90);
    const waterN = spanMin > 0 ? Math.floor(spanMin / interval) + 1 : 0;
    if (waterN) { total += waterN; parts.push('вода — ' + waterN); }
  }
  let courseDoses = 0;
  try {
    (Array.isArray(state.myCourses) ? state.myCourses : []).forEach((c) => {
      if (c && Array.isArray(c.times)) courseDoses += c.times.length;
    });
  } catch (e) { }
  if (courseDoses) { total += courseDoses; parts.push('курс — ' + courseDoses); }
  return { total, parts };
}
function renderNotificationBudget() {
  if (typeof document === 'undefined') return;
  const el = $('#notif-daily-summary');
  if (!el) return;
  const budget = computeTodayNotificationBudget();
  el.textContent = budget.total === 0
    ? 'Сейчас все уведомления выключены — тишина гарантирована.'
    : 'Сегодня FitFlow может прислать до ' + budget.total + ' уведомлений (' + budget.parts.join(' · ') + ')' + (budget.total >= 10 ? ' — многовато? Лишнее можно выключить ниже.' : '.');
  el.classList.toggle('warn', budget.total >= 10);
}

function renderReminderSettings() {
  if (typeof document === 'undefined') return;
  const toggle = $('#workout-reminder-toggle');
  const timeInput = $('#workout-reminder-time');
  const status = $('#workout-reminder-status');
  if (!toggle || !timeInput || !status) return;

  toggle.checked = state.reminders.enabled;
  const opts = $('#workout-reminder-options');
  if (opts) opts.hidden = !state.reminders.enabled;
  timeInput.value = reminderTimeText(state.reminders.time);
  status.textContent = state.reminders.enabled
    ? `Каждый день в ${reminderTimeText(state.reminders.time)}. Напоминание сохранено на телефоне.`
    : 'Напоминание выключено.';
}

function renderMealRemindersSettings() {
  if (typeof document === 'undefined') return;
  const toggle = $('#meal-reminders-toggle');
  const list = $('#meal-reminders-list');
  const status = $('#meal-reminders-status');
  if (!toggle || !list || !status) return;
  const reminders = state.mealReminders;
  toggle.checked = reminders.enabled;
  const opts = $('#meal-reminders-options');
  if (opts) opts.hidden = !reminders.enabled;
  list.innerHTML = reminders.meals.map((meal) => `
    <div class="meal-reminder-row">
      <input type="checkbox" data-meal-enabled="${meal.id}" ${meal.enabled ? 'checked' : ''} aria-label="Напоминать: ${meal.label}">
      <label>${meal.label}</label>
      <input type="time" data-meal-time="${meal.id}" value="${meal.time}" aria-label="Время: ${meal.label}">
    </div>`).join('');
  const enabledCount = reminders.meals.filter((meal) => meal.enabled).length;
  status.textContent = reminders.enabled
    ? `Включено приёмов пищи: ${enabledCount} из ${reminders.meals.length}.`
    : 'Напоминания о питании выключены.';
}

function renderMorningMotivationSettings() {
  if (typeof document === 'undefined') return;
  const toggle = $('#morning-motivation-toggle');
  const timeInput = $('#morning-motivation-time');
  const themeLabel = $('#morning-motivation-theme-label');
  const status = $('#morning-motivation-status');
  if (!toggle || !timeInput || !themeLabel || !status) return;

  const motivation = state.morningMotivation;
  toggle.checked = motivation.enabled;
  const opts = $('#morning-motivation-options');
  if (opts) opts.hidden = !motivation.enabled;
  timeInput.value = motivation.time;
  themeLabel.textContent = MORNING_MOTIVATION_THEMES[motivation.theme];
  $$('#morning-theme-choices button').forEach((button) =>
    button.classList.toggle('active', button.dataset.morningTheme === motivation.theme));
  status.textContent = motivation.enabled
    ? `Каждое утро в ${motivation.time} · тема: ${MORNING_MOTIVATION_THEMES[motivation.theme]}.`
    : 'Утренние фразы выключены.';
}

async function ensureNotificationPermission(localNotifications) {
  try {
    let permission = await localNotifications.checkPermissions();
    if (permission.display !== 'granted') {
      permission = await localNotifications.requestPermissions();
    }
    return permission.display === 'granted';
  } catch (e) {
    console.warn('Не удалось запросить разрешение на уведомления:', e);
    return false;
  }
}

async function ensureTrainingReminderChannel(localNotifications) {
  if (typeof localNotifications.createChannel !== 'function') return;
  await localNotifications.createChannel({
    id: TRAINING_REMINDER_CHANNEL,
    name: 'FitFlow: активность',
    description: 'Вечерние напоминания о прогулках, спорте и активном отдыхе',
    importance: 5,
    visibility: 1,
    sound: 'default',
    vibrates: true
  });
}

function activityReminderId(dateKey) {
  let hash = 2166136261;
  for (let i = 0; i < dateKey.length; i++) { hash ^= dateKey.charCodeAt(i); hash = Math.imul(hash, 16777619); }
  return TRAINING_REMINDER_BASE_ID + ((hash >>> 0) % 900000);
}

function activityReminderIds() {
  const ids = [LEGACY_TRAINING_REMINDER_ID];
  const base = new Date(); base.setHours(0, 0, 0, 0);
  for (let offset = 0; offset <= TRAINING_REMINDER_SCHEDULE_DAYS; offset++) {
    const day = new Date(base.getTime()); day.setDate(day.getDate() + offset);
    const date = `${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`;
    ids.push(activityReminderId(date));
  }
  return ids;
}

async function removeDeliveredTrainingReminder(localNotifications = getLocalNotifications(), id = null) {
  if (!localNotifications || typeof localNotifications.removeDeliveredNotifications !== 'function') return false;
  try {
    await localNotifications.removeDeliveredNotifications({ notifications: [{ id: id || LEGACY_TRAINING_REMINDER_ID }] });
    return true;
  } catch (e) { return false; }
}

async function cancelTrainingReminder(localNotifications = getLocalNotifications()) {
  if (!localNotifications) return false;
  try {
    await localNotifications.cancel({ notifications: activityReminderIds().map((id) => ({ id })) });
    return true;
  } catch (e) { return false; }
}

async function scheduleTrainingReminder({ skipToday = false, clearDelivered = false, requestPermission = true } = {}) {
  const localNotifications = getLocalNotifications();
  if (!localNotifications) return { ok: false, message: 'Напоминания работают в Android-приложении, а не в браузере.' };
  let allowed = false;
  if (requestPermission) allowed = await ensureNotificationPermission(localNotifications);
  else { try { allowed = (await localNotifications.checkPermissions()).display === 'granted'; } catch (e) { } }
  if (!allowed) return { ok: false, message: 'Разрешите уведомления Android, чтобы включить напоминание.' };
  try {
    await ensureTrainingReminderChannel(localNotifications);
    await cancelTrainingReminder(localNotifications);
    const firstAt = nextReminderDate(state.reminders.time, skipToday);
    const notifications = [];
    for (let dayIndex = 0; dayIndex < TRAINING_REMINDER_SCHEDULE_DAYS; dayIndex++) {
      const at = new Date(firstAt.getTime()); at.setDate(at.getDate() + dayIndex);
      const date = `${at.getFullYear()}-${String(at.getMonth()+1).padStart(2,'0')}-${String(at.getDate()).padStart(2,'0')}`;
      if (hasWorkoutToday() && date === todayKey()) continue;
      notifications.push({
        id: activityReminderId(date),
        title: 'Была сегодня активность?',
        body: 'Откройте FitFlow, чтобы отметить прогулку, спорт или активный отдых.',
        schedule: { at, allowWhileIdle: true },
        channelId: TRAINING_REMINDER_CHANNEL,
        smallIcon: 'ic_stat_icon', iconColor: '#00696B', autoCancel: true,
        actionTypeId: NOTIF_SETTINGS_ACTION_TYPE,
        extra: { source: 'fitflow-training-reminder', notifSettings: 'evening' }
      });
    }
    if (notifications.length) await localNotifications.schedule({ notifications });
    if (clearDelivered) await removeDeliveredTrainingReminder(localNotifications);
    return { ok: true };
  } catch (e) {
    console.warn('Не удалось запланировать вечернее напоминание:', e);
    return { ok: false, message: 'Не удалось запланировать напоминание. Откройте «Настроить уведомления» и проверьте разрешения.' };
  }
}

async function refreshTrainingReminderOnLaunch() {
  if (!state.reminders.enabled || !getLocalNotifications()) return;
  await scheduleTrainingReminder({ skipToday: hasWorkoutToday(), requestPermission: false });
}

/* ============================================================
   P13 — вечерний пуш «Оцени день» (самочувствие 1–5)
   ------------------------------------------------------------
   По аналогии с вечерней активностью: один вопрос в день, тихий
   канал, кнопка «⚙️ Настроить» ведёт в свой раздел. Чистый JS на
   Capacitor LocalNotifications — правок workflow не требует.
   ============================================================ */
const MOOD_REMINDER_CHANNEL = 'fitflow_day_mood';
const MOOD_REMINDER_BASE_ID = 72000;
const MOOD_REMINDER_SCHEDULE_DAYS = 14;

function moodReminderId(dateKey) {
  let hash = 2166136261;
  for (let i = 0; i < dateKey.length; i++) { hash ^= dateKey.charCodeAt(i); hash = Math.imul(hash, 16777619); }
  return MOOD_REMINDER_BASE_ID + ((hash >>> 0) % 900000);
}

function moodReminderIds() {
  const ids = [];
  const base = new Date(); base.setHours(0, 0, 0, 0);
  for (let offset = 0; offset <= MOOD_REMINDER_SCHEDULE_DAYS; offset++) {
    const day = new Date(base.getTime()); day.setDate(day.getDate() + offset);
    const date = `${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`;
    ids.push(moodReminderId(date));
  }
  return ids;
}

async function ensureMoodReminderChannel(localNotifications) {
  if (typeof localNotifications.createChannel !== 'function') return;
  await localNotifications.createChannel({
    id: MOOD_REMINDER_CHANNEL,
    name: 'FitFlow: итоги дня',
    description: 'Вечерний вопрос «Как прошёл день?» — оценка самочувствия от 1 до 5',
    importance: 4,
    visibility: 1,
    sound: 'default',
    vibrates: true
  });
}

async function removeDeliveredMoodReminder(localNotifications = getLocalNotifications(), id = null) {
  if (!localNotifications || typeof localNotifications.removeDeliveredNotifications !== 'function') return false;
  try {
    await localNotifications.removeDeliveredNotifications({ notifications: [{ id: id || moodReminderId(todayKey()) }] });
    return true;
  } catch (e) { return false; }
}

async function cancelMoodReminder(localNotifications = getLocalNotifications()) {
  if (!localNotifications) return false;
  try {
    await localNotifications.cancel({ notifications: moodReminderIds().map((id) => ({ id })) });
    return true;
  } catch (e) { return false; }
}

async function scheduleMoodReminder({ skipToday = false, requestPermission = true } = {}) {
  const localNotifications = getLocalNotifications();
  if (!localNotifications) return { ok: false, message: 'Напоминания работают в Android-приложении, а не в браузере.' };
  let allowed = false;
  if (requestPermission) allowed = await ensureNotificationPermission(localNotifications);
  else { try { allowed = (await localNotifications.checkPermissions()).display === 'granted'; } catch (e) { } }
  if (!allowed) return { ok: false, message: 'Разрешите уведомления Android, чтобы включить напоминание.' };
  try {
    await ensureMoodReminderChannel(localNotifications);
    await cancelMoodReminder(localNotifications);
    const firstAt = nextReminderDate(state.dayMoodReminder.time, skipToday);
    const notifications = [];
    for (let dayIndex = 0; dayIndex < MOOD_REMINDER_SCHEDULE_DAYS; dayIndex++) {
      const at = new Date(firstAt.getTime()); at.setDate(at.getDate() + dayIndex);
      const date = `${at.getFullYear()}-${String(at.getMonth()+1).padStart(2,'0')}-${String(at.getDate()).padStart(2,'0')}`;
      if (date === todayKey() && getTodayMood()) continue; // уже оценено — не спрашиваем
      notifications.push({
        id: moodReminderId(date),
        title: 'Как прошёл день? 🌗',
        body: 'Откройте FitFlow и отметьте самочувствие от 1 до 5 — это займёт пару секунд.',
        schedule: { at, allowWhileIdle: true },
        channelId: MOOD_REMINDER_CHANNEL,
        smallIcon: 'ic_stat_icon', iconColor: '#8E6FBF', autoCancel: true,
        actionTypeId: NOTIF_SETTINGS_ACTION_TYPE,
        extra: { source: 'fitflow-day-mood', notifSettings: 'mood' }
      });
    }
    if (notifications.length) await localNotifications.schedule({ notifications });
    return { ok: true };
  } catch (e) {
    console.warn('Не удалось запланировать вечерний вопрос о самочувствии:', e);
    return { ok: false, message: 'Не удалось запланировать напоминание. Проверьте разрешения Android.' };
  }
}

async function refreshMoodReminderOnLaunch() {
  if (!state.dayMoodReminder.enabled || !getLocalNotifications()) return;
  await scheduleMoodReminder({ skipToday: !!getTodayMood(), requestPermission: false });
}

function renderMoodReminderSettings() {
  if (typeof document === 'undefined') return;
  const toggle = $('#day-mood-reminder-toggle');
  const timeInput = $('#day-mood-reminder-time');
  const status = $('#day-mood-reminder-status');
  if (!toggle || !timeInput || !status) return;
  toggle.checked = state.dayMoodReminder.enabled;
  const opts = $('#day-mood-reminder-options');
  if (opts) opts.hidden = !state.dayMoodReminder.enabled;
  timeInput.value = state.dayMoodReminder.time;
  status.textContent = state.dayMoodReminder.enabled
    ? `Каждый вечер в ${state.dayMoodReminder.time}, если оценка ещё не поставлена.`
    : 'Напоминание выключено.';
}

async function updateMoodReminderEnabled(enabled) {
  state.dayMoodReminder.enabled = enabled;
  saveState();
  renderMoodReminderSettings(); renderNotificationBudget();

  if (!enabled) {
    await cancelMoodReminder();
    toast('Вечерний вопрос «Как прошёл день?» выключен');
    return;
  }

  const result = await scheduleMoodReminder({ skipToday: !!getTodayMood() });
  if (!result.ok) {
    state.dayMoodReminder.enabled = false;
    saveState();
    renderMoodReminderSettings(); renderNotificationBudget();
    toast(result.message);
    return;
  }
  toast(`Вечером в ${state.dayMoodReminder.time} спрошу «Как прошёл день?» — отметить самочувствие можно одним тапом.`);
}

async function updateMoodReminderTime(time) {
  if (!isValidReminderTime(time)) {
    renderMoodReminderSettings(); renderNotificationBudget();
    toast('Укажите время в формате ЧЧ:ММ');
    return;
  }
  state.dayMoodReminder.time = time;
  saveState();
  renderMoodReminderSettings(); renderNotificationBudget();

  if (!state.dayMoodReminder.enabled) {
    toast(`Время вопроса: ${time}`);
    return;
  }
  const result = await scheduleMoodReminder({ skipToday: !!getTodayMood() });
  toast(result.ok ? `Вопрос перенесён на ${time}` : result.message);
}

function openMorningThemeDialog() {
  const dialog = $('#morning-theme-dialog');
  if (dialog) dialog.hidden = false;
  renderMorningMotivationSettings(); renderNotificationBudget();
  renderWaterReminderSettings(); renderNotificationBudget();
}

function closeMorningThemeDialog() {
  const dialog = $('#morning-theme-dialog');
  if (dialog) dialog.hidden = true;
}

function showMorningMessageDialog(message) {
  const dialog = $('#morning-message-dialog');
  const text = $('#morning-message-dialog-text');
  if (!dialog || !text) return;
  text.textContent = message || 'Пусть сегодняшний день будет добрым к вам.';
  dialog.hidden = false;
}

function closeMorningMessageDialog() {
  const dialog = $('#morning-message-dialog');
  if (dialog) dialog.hidden = true;
}

/* ============================================================
   0.5.4 — кнопка «⚙️ Настроить» прямо в уведомлении (идея владельца)
   ------------------------------------------------------------
   Мастер 0.5.3 спрашивает только ТИПЫ напоминаний, а точное время
   пользователь меняет «по факту»: у неудобного уведомления есть
   кнопка действия, ведущая сразу в его раздел настроек (с подсветкой).
   Действия добавляются уведомлениям планировщика LocalNotifications
   (чистый JS, без правок workflow); нативное уведомление воды
   (с кнопкой «+250 мл») получит «⚙️» в нативном пакете 0.8.0.
   ============================================================ */
const NOTIF_SETTINGS_ACTION_TYPE = 'fitflow-notif-settings';
const NOTIF_SETTINGS_ACTION_ID = 'open-notif-settings';
/* 0.8.25 (заказ владельца «как у воды — отметить прямо из уведомления»):
   у напоминания о курсе свой тип действий — «✓ Принял» + «⚙️ Настроить».
   Отметка ставится в фоне (foreground: false), приложение не открывается. */
const COURSE_DOSE_ACTION_TYPE = 'fitflow-course-dose';
const COURSE_DOSE_ACTION_ID = 'course-dose-taken';
const NOTIF_SETTINGS_TARGETS = {
  water: { view: 'settings-notifications', anchor: 'water-reminders-toggle' },
  meals: { view: 'settings-notifications', anchor: 'meal-reminders-toggle' },
  morning: { view: 'settings-notifications', anchor: 'morning-motivation-toggle' },
  evening: { view: 'settings-notifications', anchor: 'workout-reminder-toggle' },
  mood: { view: 'settings-notifications', anchor: 'day-mood-reminder-toggle' },
  course: { view: 'settings-courses', anchor: 'course-list' }
};

/* Тип действий регистрируется один раз при запуске, ДО планирования. */
async function registerNotificationSettingsActions() {
  const localNotifications = getLocalNotifications();
  if (!localNotifications || typeof localNotifications.registerActionTypes !== 'function') return;
  try {
    await localNotifications.registerActionTypes({
      types: [
        {
          id: NOTIF_SETTINGS_ACTION_TYPE,
          actions: [{ id: NOTIF_SETTINGS_ACTION_ID, title: '⚙️ Настроить уведомление', foreground: true }]
        },
        {
          // 0.8.25: курс — быстрая отметка приёма прямо из шторки
          id: COURSE_DOSE_ACTION_TYPE,
          actions: [
            { id: COURSE_DOSE_ACTION_ID, title: '✓ Принял', foreground: false, destructive: false },
            { id: NOTIF_SETTINGS_ACTION_ID, title: '⚙️ Настроить уведомление', foreground: true }
          ]
        }
      ]
    });
  } catch (e) { console.warn('Действие «⚙️ Настроить» для уведомлений недоступно:', e); }
}

/* Переход к разделу настроек уведомления + мягкая подсветка-вспышка. */
function openNotificationSettings(section) {
  if (typeof document === 'undefined') return;
  const target = NOTIF_SETTINGS_TARGETS[section];
  if (!target) return;
  switchView(target.view);
  setTimeout(() => {
    const anchor = document.getElementById(target.anchor);
    const group = anchor ? (anchor.closest('.settings-group') || anchor) : null;
    if (!group) return;
    try { group.scrollIntoView({ block: 'center', behavior: 'smooth' }); }
    catch (e) { try { group.scrollIntoView(true); } catch (e2) { } }
    group.classList.remove('settings-flash');
    void group.offsetWidth; // перезапуск анимации при повторном переходе
    group.classList.add('settings-flash');
    setTimeout(() => group.classList.remove('settings-flash'), 3600);
  }, 150);
}

function installActivityNotificationListener() {
  const localNotifications = getLocalNotifications();
  if (activityNotificationListenerInstalled || !localNotifications
      || typeof localNotifications.addListener !== 'function') return;

  try {
    localNotifications.addListener('localNotificationActionPerformed', async (event) => {
      const notification = event && event.notification;
      if (!notification) return;
      const extra = notification.extra || {};
      // 0.5.4: кнопка «⚙️ Настроить» — в свой раздел настроек, tap-ветки не трогаем
      if (event.actionId === NOTIF_SETTINGS_ACTION_ID) {
        if (extra.notifSettings) openNotificationSettings(extra.notifSettings);
        return;
      }
      /* 0.8.25: «✓ Принял» — отмечаем приём курса, не открывая приложение.
         Отмечаем ИМЕННО тот приём и ту дату, что записаны в уведомлении;
         повторное нажатие по уже отмеченному ничего не ломает (проверяем
         перед переключением, чтобы галочка не снялась). */
      if (event.actionId === COURSE_DOSE_ACTION_ID) {
        const courseId = extra.courseId;
        const doseIndex = Number(extra.doseIndex);
        const dateKey = extra.dateKey || todayKey();
        const course = getCourse(courseId);
        if (!course || !Number.isInteger(doseIndex)) return;
        const already = (((course.checkLog || {})[dateKey]) || []).includes(doseIndex);
        if (!already) toggleCourseDose(courseId, doseIndex, dateKey);
        renderDayPlan();
        await scheduleCourseReminders({ requestPermission: false }); // сегодняшний приём отмечен — не тревожим повторно
        toast(`✓ Приём отмечен: ${course.name}`);
        return;
      }
      if (extra.source === 'fitflow-water-reminder') {
        // 0.5.6 (решение владельца): вода из уведомления просто появляется в
        // приложении — смотри кольцо на Главной. Тост убран: при позднем входе
        // отложенный «+250 мл» читался как «приложение само что-то записало».
        addWater(250);
        return;
      }
      if (extra.source === 'fitflow-training-reminder') {
        await removeDeliveredTrainingReminder(localNotifications, notification.id);
        switchView('training');
        toast('Была сегодня активность? Выберите вид и добавьте запись.');
        return;
      }
      if (extra.source === 'fitflow-day-mood') {
        await removeDeliveredMoodReminder(localNotifications, notification.id);
        switchView('home');
        setTimeout(() => {
          const card = $('#day-mood-card');
          if (!card) return;
          try { card.scrollIntoView({ block: 'center', behavior: 'smooth' }); }
          catch (e) { try { card.scrollIntoView(true); } catch (e2) { } }
          const box = card.querySelector('.mood-card');
          if (box) {
            box.classList.remove('mood-card-flash');
            void box.offsetWidth; // перезапуск вспышки при повторном переходе
            box.classList.add('mood-card-flash');
            setTimeout(() => box.classList.remove('mood-card-flash'), 4000);
          }
        }, 250);
        toast('Как прошёл день? Отметьте самочувствие от 1 до 5.');
        return;
      }
      if (extra.source === 'fitflow-meal-reminder') {
        switchView('home');
        selectedMealTypeId = extra.mealId || '';
        mealTypeTouched = !!selectedMealTypeId;
        renderMealTypePicker();
        setTimeout(() => $('#food-input').focus(), 250);
        toast(`Запишите ${extra.mealLabel || 'приём пищи'} в дневник`);
        return;
      }
      if (notification.id >= MORNING_MOTIVATION_NOTIFICATION_BASE_ID
          && notification.id < MORNING_MOTIVATION_NOTIFICATION_BASE_ID + MORNING_MOTIVATION_SCHEDULE_DAYS) {
        const extra = notification.extra || {};
        showMorningMessageDialog(extra.message || notification.largeBody || notification.body);
      }
    });
    activityNotificationListenerInstalled = true;
  } catch (e) {
    console.warn('Не удалось подключить обработчик вечернего вопроса:', e);
  }
}

async function ensureMealReminderChannel(localNotifications) {
  if (typeof localNotifications.createChannel !== 'function') return;
  await localNotifications.createChannel({
    id: MEAL_REMINDER_CHANNEL,
    name: 'FitFlow: приёмы пищи',
    description: 'Напоминания записать завтрак, обед и другие приёмы пищи',
    importance: 4,
    visibility: 1,
    sound: 'default',
    vibrates: true
  });
}

function mealNotificationId(mealId, dateKey) {
  const text = `${mealId}|${dateKey}`;
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) { hash ^= text.charCodeAt(i); hash = Math.imul(hash, 16777619); }
  return 900000000 + ((hash >>> 0) % 900000000);
}

function mealReminderNotificationIds() {
  const legacy = Array.from({ length: MEAL_REMINDER_TYPES.length * MEAL_REMINDER_SCHEDULE_DAYS }, (_, index) => MEAL_REMINDER_NOTIFICATION_BASE_ID + index);
  const ids = [];
  const base = new Date();
  base.setHours(0, 0, 0, 0);
  for (let offset = 0; offset <= MEAL_REMINDER_SCHEDULE_DAYS; offset++) {
    const day = new Date(base.getTime());
    day.setDate(day.getDate() + offset);
    const pad = (value) => String(value).padStart(2, '0');
    const date = `${day.getFullYear()}-${pad(day.getMonth() + 1)}-${pad(day.getDate())}`;
    getMealTypes().forEach((meal) => ids.push(mealNotificationId(meal.id, date)));
  }
  return [...legacy, ...ids];
}

function hasMealTypeOnDate(mealId, date = todayKey()) {
  return state.food.items.some((item) => item.mealTypeId === mealId && state.food.date === date);
}

async function cancelMealReminders(localNotifications = getLocalNotifications()) {
  if (!localNotifications) return;
  try { await localNotifications.cancel({ notifications: mealReminderNotificationIds().map((id) => ({ id })) }); } catch (e) { }
}

async function scheduleMealReminders({ requestPermission = true } = {}) {
  const localNotifications = getLocalNotifications();
  if (!localNotifications) return { ok: false, message: 'Напоминания о питании работают только в Android-приложении.' };
  let allowed = false;
  if (requestPermission) allowed = await ensureNotificationPermission(localNotifications);
  else { try { allowed = (await localNotifications.checkPermissions()).display === 'granted'; } catch (e) { } }
  if (!allowed) return { ok: false, message: 'Разрешите уведомления Android, чтобы включить напоминания о питании.' };
  try {
    await ensureMealReminderChannel(localNotifications);
    await cancelMealReminders(localNotifications);
    const notifications = [];
    state.mealReminders.meals.filter((meal) => meal.enabled).forEach((meal) => {
      const firstAt = nextReminderDate(meal.time);
      for (let dayIndex = 0; dayIndex < MEAL_REMINDER_SCHEDULE_DAYS; dayIndex++) {
        const at = new Date(firstAt.getTime());
        at.setDate(at.getDate() + dayIndex);
        const pad = (value) => String(value).padStart(2, '0');
        const date = `${at.getFullYear()}-${pad(at.getMonth() + 1)}-${pad(at.getDate())}`;
        if (hasMealTypeOnDate(meal.id, date)) continue;
        notifications.push({
          id: mealNotificationId(meal.id, date),
          title: `Пора записать: ${meal.label} · ${meal.time}`,
          body: `Не забудьте добавить ваш ${meal.label.toLowerCase()} в FitFlow.`,
          schedule: { at, allowWhileIdle: true },
          channelId: MEAL_REMINDER_CHANNEL,
          smallIcon: 'ic_stat_icon', iconColor: '#FF9E3D', autoCancel: true,
          actionTypeId: NOTIF_SETTINGS_ACTION_TYPE,
          extra: { source: 'fitflow-meal-reminder', mealId: meal.id, mealLabel: meal.label, notifSettings: 'meals' }
        });
      }
    });
    if (notifications.length) await localNotifications.schedule({ notifications });
    return { ok: true };
  } catch (e) {
    console.warn('Не удалось запланировать напоминания о питании:', e);
    return { ok: false, message: 'Не удалось включить напоминания о питании. Проверьте разрешения Android.' };
  }
}


/* ==== ВОДНЫЕ НАПОМИНАНИЯ ==== */

async function ensureWaterReminderChannel(localNotifications) {
  if (typeof localNotifications.createChannel !== 'function') return;
  await localNotifications.createChannel({
    id: WATER_REMINDER_CHANNEL,
    name: 'FitFlow: вода',
    description: 'Регулярные напоминания выпить воду',
    importance: 3,
    visibility: 1,
    sound: 'default',
    vibrates: false
  });
}

function waterReminderIds() {
  const ids = [];
  for (let d = 0; d <= WATER_REMINDER_SCHEDULE_DAYS; d++) {
    for (let slot = 0; slot < 25; slot++) {
      ids.push(75000 + d * 100 + slot);
    }
  }
  return ids;
}

/* Минуты от полуночи для всех напоминаний в окне [start; end] с шагом interval.
   Окно через полночь (например, 22:00–02:00) тоже поддерживается.
   Результат отсортирован и без дублей. */
function buildWaterReminderTimes(interval, windowStart, windowEnd) {
  const toMin = (s) => {
    const parts = String(s || '').split(':');
    const h = Number(parts[0]);
    const m = Number(parts[1]);
    if (!Number.isFinite(h) || !Number.isFinite(m) || h < 0 || h > 23 || m < 0 || m > 59) return null;
    return h * 60 + m;
  };
  const step = Math.max(1, Number(interval) || 90);
  const start = toMin(windowStart);
  let end = toMin(windowEnd);
  if (start === null || end === null) return [];
  if (end < start) end += 24 * 60; // окно через полночь
  const times = [];
  for (let t = start; t <= end; t += step) times.push(t % (24 * 60));
  return [...new Set(times)].sort((a, b) => a - b);
}

/* 0.5.6 (решение владельца): «записал воду — ближайшее напоминание молчит».
   Слот пропускается, если запись была не раньше, чем за один интервал до него:
   при сетке «каждые 90 мин» сигнал в 15:30 умолкнет, если вода отмечена после
   14:00. Сетка не перестраивается — следующие напоминания идут в свои часы.
   То же правило — в нативном WaterReminderReceiver. */
function isWaterReminderSlotSkipped(atMs) {
  const last = Number(state.water && state.water.lastAddedAt) || 0;
  if (!last || atMs <= last) return false;
  const intervalMin = Math.max(1, Number(state.waterReminders && state.waterReminders.interval) || 90);
  return atMs - last < intervalMin * 60000;
}

function getNativeBridge() {
  return (typeof window !== 'undefined' && window.FitFlowExport) ? window.FitFlowExport : null;
}

async function cancelWaterReminders(localNotifications = getLocalNotifications()) {
  const bridge = getNativeBridge();
  if (bridge && typeof bridge.cancelWaterRemindersNative === 'function') {
    try { bridge.cancelWaterRemindersNative(); } catch (e) { }
  }
  if (!localNotifications) return;
  try { await localNotifications.cancel({ notifications: waterReminderIds().map((id) => ({ id })) }); } catch (e) { }
}

async function scheduleWaterReminders({ requestPermission = true } = {}) {
  const localNotifications = getLocalNotifications();
  const bridge = getNativeBridge();
  const hasNative = bridge && typeof bridge.scheduleWaterRemindersNative === 'function';
  if (!localNotifications && !hasNative) return { ok: false, message: 'Напоминания о воде работают только в Android-приложении.' };
  let allowed = false;
  if (localNotifications) {
    if (requestPermission) allowed = await ensureNotificationPermission(localNotifications);
    else { try { allowed = (await localNotifications.checkPermissions()).display === 'granted'; } catch (e) { } }
  } else {
    try { allowed = bridge.areNotificationsEnabled(); } catch (e) { allowed = false; }
  }
  if (!allowed) return { ok: false, message: 'Разрешите уведомления для напоминаний о воде.' };

  /* Приоритет — нативный планировщик: уведомление с кнопкой «+250 мл»
     работает прямо из шторки, без открытия приложения, и обновляет виджет.
     JS-напоминания остаются запасным вариантом для старых сборок. */
  if (hasNative) {
    try {
      const wr = state.waterReminders;
      const times = buildWaterReminderTimes(wr.interval, wr.windowStart, wr.windowEnd);
      if (times.length === 0) return { ok: false, message: 'Проверьте окно напоминаний о воде.' };
      bridge.scheduleWaterRemindersNative(times.join(','));
      // Снять возможные старые JS-уведомления, чтобы не было дублей.
      if (localNotifications) try { await localNotifications.cancel({ notifications: waterReminderIds().map((id) => ({ id })) }); } catch (e) { }
      return { ok: true, count: times.length, native: true };
    } catch (e) {
      console.warn('Нативный планировщик воды недоступен, переключаюсь на JS:', e);
    }
  }
  if (!localNotifications) return { ok: false, message: 'Напоминания о воде сейчас недоступны.' };
  try {
    await ensureWaterReminderChannel(localNotifications);
    await cancelWaterReminders(localNotifications);
    const wr = state.waterReminders;
    const [sh, sm] = wr.windowStart.split(':').map(Number);
    const [eh, em] = wr.windowEnd.split(':').map(Number);
    const now = new Date();
    const notifications = [];
    let slotCounter = 0;
    for (let d = 0; d <= WATER_REMINDER_SCHEDULE_DAYS; d++) {
      const base = new Date(); base.setDate(base.getDate() + d);
      let at = new Date(base); at.setHours(sh, sm, 0, 0);
      const dayEnd = new Date(base); dayEnd.setHours(eh, em, 0, 0);
      while (at <= dayEnd && slotCounter < 75) {
        // 0.5.6: слот сразу после недавней записи воды не планируем вовсе
        if (at > now && !isWaterReminderSlotSkipped(at.getTime())) {
          notifications.push({
            id: 75000 + d * 100 + slotCounter,
            title: '💧 Время выпить воду',
            // 0.5.7 (владелец): текст короче — полностью виден в свёрнутом
            // уведомлении, разворачивать не нужно (кнопки и так сразу на месте).
            body: `Сегодня: ${state.water.total || 0} из ${state.water.goal} мл.`,
            schedule: { at: new Date(at), allowWhileIdle: true },
            channelId: WATER_REMINDER_CHANNEL,
            smallIcon: 'ic_stat_icon', iconColor: '#00696B', autoCancel: true,
            actionTypeId: NOTIF_SETTINGS_ACTION_TYPE,
            extra: { source: 'fitflow-water-reminder', notifSettings: 'water' }
          });
        }
        at = new Date(at.getTime() + wr.interval * 60000);
        slotCounter++;
      }
    }
    if (notifications.length) await localNotifications.schedule({ notifications });
    return { ok: true, count: notifications.length };
  } catch (e) {
    console.warn('Не удалось запланировать напоминания о воде:', e);
    return { ok: false, message: 'Не удалось включить напоминания о воде.' };
  }
}

async function refreshWaterRemindersOnLaunch() {
  if (!state.waterReminders.enabled || !getLocalNotifications()) return;
  await scheduleWaterReminders({ requestPermission: false });
}

function renderWaterReminderSettings() {
  if (typeof document === 'undefined') return;
  const toggle = $('#water-reminders-toggle');
  const status = $('#water-reminders-status');
  const opts = $('#water-reminders-options');
  if (!toggle || !status) return;
  toggle.checked = state.waterReminders.enabled;
  if (opts) opts.hidden = !state.waterReminders.enabled;
  $$('#water-interval-choices button').forEach((btn) =>
    btn.classList.toggle('active', Number(btn.dataset.waterInterval) === state.waterReminders.interval));
  const winStart = $('#water-reminder-window-start');
  const winEnd = $('#water-reminder-window-end');
  if (winStart && document.activeElement !== winStart) winStart.value = state.waterReminders.windowStart || '08:00';
  if (winEnd && document.activeElement !== winEnd) winEnd.value = state.waterReminders.windowEnd || '22:00';
  status.textContent = state.waterReminders.enabled
    ? `Каждые ${state.waterReminders.interval} мин с ${state.waterReminders.windowStart} до ${state.waterReminders.windowEnd}.`
    : 'Напоминания о воде выключены.';
}

async function updateWaterReminderWindow(start, end) {
  if (isValidReminderTime(start)) state.waterReminders.windowStart = start;
  if (isValidReminderTime(end)) state.waterReminders.windowEnd = end;
  saveState();
  renderWaterReminderSettings();
  renderNotificationBudget();
  if (state.waterReminders.enabled) {
    await scheduleWaterReminders();
    toast(`Период напоминаний о воде: с ${state.waterReminders.windowStart} до ${state.waterReminders.windowEnd}`);
  }
}

async function updateWaterRemindersEnabled(enabled) {
  state.waterReminders.enabled = enabled;
  saveState();
  renderWaterReminderSettings(); renderNotificationBudget();
  if (!enabled) { await cancelWaterReminders(); toast('Напоминания о воде выключены'); return; }
  const result = await scheduleWaterReminders();
  if (!result.ok) { state.waterReminders.enabled = false; saveState(); renderWaterReminderSettings(); renderNotificationBudget(); toast(result.message); return; }
  toast(`Напоминания о воде включены: каждые ${state.waterReminders.interval} мин`);
}

async function updateWaterReminderInterval(interval) {
  state.waterReminders.interval = interval;
  saveState();
  renderWaterReminderSettings(); renderNotificationBudget();
  if (!state.waterReminders.enabled) return;
  await scheduleWaterReminders();
  toast(`Интервал: каждые ${interval} мин`);
}

/* ===== Совместимость и алиасы для функций рендеринга ===== */
function renderWaterReminderSetting() { return renderWaterReminderSettings(); renderNotificationBudget(); }
function renderReminderSetting() { return renderReminderSettings(); renderNotificationBudget(); }
function renderMealRemindersSetting() { return renderMealRemindersSettings(); renderNotificationBudget(); }
function renderMorningMotivationSetting() { return renderMorningMotivationSettings(); renderNotificationBudget(); }
function renderDayChecklistSetting() { return renderDayChecklistSettings(); }
function renderHomeLayoutSetting() { return renderHomeLayoutSettings(); }
function renderWeightSetting() { return renderWeightSettings(); }


async function syncMealRemindersForToday() {
  if (!state.mealReminders.enabled) return;
  await scheduleMealReminders();
}

async function refreshMealRemindersOnLaunch() {
  if (!state.mealReminders.enabled || !getLocalNotifications()) return;
  await scheduleMealReminders({ requestPermission: false });
}

async function updateMealRemindersEnabled(enabled) {
  state.mealReminders.enabled = enabled;
  saveState();
  renderMealRemindersSettings(); renderNotificationBudget();
  if (!enabled) { await cancelMealReminders();
  await cancelWaterReminders(); toast('Напоминания о питании выключены'); return; }
  const result = await scheduleMealReminders();
  if (!result.ok) { state.mealReminders.enabled = false; saveState(); renderMealRemindersSettings(); renderNotificationBudget(); toast(result.message); return; }
  toast('Напоминания о питании включены');
}

async function updateMealReminder(id, changes) {
  const meal = state.mealReminders.meals.find((item) => item.id === id);
  if (!meal) return;
  Object.assign(meal, changes);
  if (!isValidReminderTime(meal.time)) { renderMealRemindersSettings(); renderNotificationBudget(); toast('Укажите время в формате ЧЧ:ММ'); return; }
  saveState();
  renderMealRemindersSettings(); renderNotificationBudget();
  if (!state.mealReminders.enabled) return;
  const result = await scheduleMealReminders();
  if (!result.ok) toast(result.message);
}

async function setAllMealReminders(enabled) {
  state.mealReminders.meals.forEach((meal) => { meal.enabled = enabled; });
  saveState();
  renderMealRemindersSettings(); renderNotificationBudget();
  if (state.mealReminders.enabled) await scheduleMealReminders();
}

async function ensureMorningMotivationChannel(localNotifications) {
  if (typeof localNotifications.createChannel !== 'function') return;
  await localNotifications.createChannel({
    id: MORNING_MOTIVATION_CHANNEL,
    name: 'FitFlow: утренняя мотивация',
    description: 'Короткие мотивирующие фразы в начале дня',
    importance: 3,
    visibility: 1,
    sound: 'default',
    vibrates: false
  });
}

function getMorningMotivationNotificationIds() {
  return Array.from(
    { length: MORNING_MOTIVATION_SCHEDULE_DAYS },
    (_, index) => MORNING_MOTIVATION_NOTIFICATION_BASE_ID + index
  );
}

function daySequenceIndex(date) {
  const localMidnight = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  return Math.floor(localMidnight.getTime() / 86400000);
}

function morningScheduleStart(time) {
  return nextReminderDate(time);
}

async function cancelMorningMotivation(localNotifications = getLocalNotifications()) {
  if (!localNotifications) return;
  try {
    await localNotifications.cancel({
      notifications: getMorningMotivationNotificationIds().map((id) => ({ id }))
    });
  } catch (e) {
    // Часть фраз может уже прийти или ещё не быть запланирована.
  }
}

async function scheduleMorningMotivation({ requestPermission = true } = {}) {
  const localNotifications = getLocalNotifications();
  if (!localNotifications) {
    return { ok: false, message: 'Утренняя мотивация работает только в Android-приложении.' };
  }

  let allowed = false;
  if (requestPermission) {
    allowed = await ensureNotificationPermission(localNotifications);
  } else {
    try {
      const permission = await localNotifications.checkPermissions();
      allowed = permission.display === 'granted';
    } catch (e) {
      allowed = false;
    }
  }
  if (!allowed) return { ok: false, message: 'Разрешите уведомления Android, чтобы включить утренние фразы.' };

  try {
    await ensureMorningMotivationChannel(localNotifications);
    await cancelMorningMotivation(localNotifications);
    const motivation = state.morningMotivation;
    const firstAt = morningScheduleStart(motivation.time);
    const notifications = Array.from({ length: MORNING_MOTIVATION_SCHEDULE_DAYS }, (_, index) => {
      const at = new Date(firstAt.getTime());
      at.setDate(at.getDate() + index);
      const message = getMorningMotivationMessage(motivation.theme, daySequenceIndex(at));
      return {
        id: MORNING_MOTIVATION_NOTIFICATION_BASE_ID + index,
        title: 'Доброе утро ☀️',
        body: message,
        largeBody: message,
        summaryText: 'FitFlow · утренняя мотивация',
        schedule: { at, allowWhileIdle: true },
        channelId: MORNING_MOTIVATION_CHANNEL,
        smallIcon: 'ic_stat_icon',
        iconColor: '#00696B',
        autoCancel: true,
        actionTypeId: NOTIF_SETTINGS_ACTION_TYPE,
        extra: { source: 'fitflow-morning-motivation', message, notifSettings: 'morning' }
      };
    });
    motivation.message = notifications[0].body;
    saveState();
    await localNotifications.schedule({ notifications });
    return { ok: true };
  } catch (e) {
    console.warn('Не удалось запланировать утреннюю мотивацию:', e);
    return { ok: false, message: 'Не удалось включить утренние фразы. Проверьте разрешения Android.' };
  }
}

async function refreshMorningMotivationScheduleOnLaunch() {
  if (!state.morningMotivation.enabled || !getLocalNotifications()) return;
  // При обычном открытии приложения не показываем повторный системный запрос.
  // Если разрешение уже есть, обновляем окно из 30 будущих фраз.
  await scheduleMorningMotivation({ requestPermission: false });
}

async function updateMorningMotivationEnabled(enabled) {
  state.morningMotivation.enabled = enabled;
  saveState();
  renderMorningMotivationSettings(); renderNotificationBudget();
  renderWaterReminderSettings(); renderNotificationBudget();

  if (!enabled) {
    await cancelMorningMotivation();
    await cancelWaterReminders(); // 0.4.15: случайный дубль убран
    toast('Утренние фразы выключены');
    return;
  }

  const result = await scheduleMorningMotivation();
  if (!result.ok) {
    state.morningMotivation.enabled = false;
    saveState();
    renderMorningMotivationSettings(); renderNotificationBudget();
  renderWaterReminderSettings(); renderNotificationBudget();
    toast(result.message);
    return;
  }
  toast(`Утренняя фраза включена: каждый день в ${state.morningMotivation.time}`);
}

async function updateMorningMotivationTime(time) {
  if (!isValidReminderTime(time)) {
    renderMorningMotivationSettings(); renderNotificationBudget();
  renderWaterReminderSettings(); renderNotificationBudget();
    toast('Укажите время в формате ЧЧ:ММ');
    return;
  }
  state.morningMotivation.time = time;
  saveState();
  renderMorningMotivationSettings(); renderNotificationBudget();
  renderWaterReminderSettings(); renderNotificationBudget();
  if (!state.morningMotivation.enabled) {
    toast(`Время утренней фразы: ${time}`);
    return;
  }
  const result = await scheduleMorningMotivation();
  toast(result.ok ? `Утренняя фраза перенесена на ${time}` : result.message);
}

async function updateMorningMotivationTheme(theme) {
  if (!MORNING_MOTIVATION_THEMES[theme]) return;
  state.morningMotivation.theme = theme;
  saveState();
  renderMorningMotivationSettings(); renderNotificationBudget();
  renderWaterReminderSettings(); renderNotificationBudget();
  if (!state.morningMotivation.enabled) {
    toast(`Тема утренних фраз: ${MORNING_MOTIVATION_THEMES[theme]}`);
    return;
  }
  const result = await scheduleMorningMotivation();
  toast(result.ok ? 'Тема утренних фраз обновлена' : result.message);
}

async function cancelTestActivityNotification(localNotifications = getLocalNotifications()) {
  if (!localNotifications) return;
  try {
    await localNotifications.cancel({ notifications: [{ id: ACTIVITY_TEST_NOTIFICATION_ID }] });
  } catch (e) {
    // Тест может ещё не быть запланирован — это нормально.
  }
}

async function sendTestActivityNotification() {
  const localNotifications = getLocalNotifications();
  if (!localNotifications) {
    toast('Тест уведомления доступен только в Android-приложении');
    return;
  }

  const allowed = await ensureNotificationPermission(localNotifications);
  if (!allowed) {
    toast('Разрешите уведомления Android, затем повторите тест');
    return;
  }

  try {
    await ensureTrainingReminderChannel(localNotifications);
    await cancelTestActivityNotification(localNotifications);
    await localNotifications.schedule({
      notifications: [{
        id: ACTIVITY_TEST_NOTIFICATION_ID,
        title: 'Тест уведомлений FitFlow',
        body: 'Если это сообщение пришло — уведомления настроены правильно ✓',
        schedule: { at: new Date(Date.now() + 5000), allowWhileIdle: true },
        channelId: TRAINING_REMINDER_CHANNEL,
        smallIcon: 'ic_stat_icon',
        iconColor: '#00696B',
        autoCancel: true,
        extra: { source: 'fitflow-activity-test' }
      }]
    });
    toast('Тестовое уведомление придёт примерно через 5 секунд');
  } catch (e) {
    console.warn('Не удалось отправить тестовое уведомление:', e);
    toast('Не удалось отправить тест. Проверьте разрешения Android.');
  }
}

async function updateTrainingReminderEnabled(enabled) {
  state.reminders.enabled = enabled;
  saveState();
  renderReminderSettings(); renderNotificationBudget();

  if (!enabled) {
    await cancelTrainingReminder();
    toast('Вечернее напоминание выключено');
    return;
  }

  const result = await scheduleTrainingReminder({ skipToday: hasWorkoutToday() }); // ручное время на будущее сегодня создаёт новый вопрос, если активности нет
  if (!result.ok) {
    state.reminders.enabled = false;
    saveState();
    renderReminderSettings(); renderNotificationBudget();
    toast(result.message);
    return;
  }

  toast(`⏰ Вечернее напоминание об активности: каждый день в ${reminderTimeText(state.reminders.time)}. Если за день тренировки так и не появится, спрошу вечером. Изменить/выключить: Настройки → Уведомления.`);
}

async function updateTrainingReminderTime(time) {
  if (!isValidReminderTime(time)) {
    renderReminderSettings(); renderNotificationBudget();
    toast('Укажите время в формате ЧЧ:ММ');
    return;
  }

  state.reminders.time = time;
  saveState();
  renderReminderSettings(); renderNotificationBudget();

  if (!state.reminders.enabled) {
    toast(`Время напоминания: ${time}`);
    return;
  }

  const result = await scheduleTrainingReminder({ skipToday: hasWorkoutToday() });
  toast(result.ok
    ? `Напоминание перенесено на ${time}`
    : result.message);
}

function refreshNotificationSetupState() {
  if (typeof document === 'undefined') return { notifications: false, battery: false };
  const bridge = getNativeSettingsBridge();
  let notifications = false;
  let battery = false;

  try {
    if (bridge && typeof bridge.areNotificationsEnabled === 'function') {
      notifications = Boolean(bridge.areNotificationsEnabled());
    }
  } catch (e) {
    console.warn('Не удалось проверить разрешение на уведомления:', e);
  }
  try {
    if (bridge && typeof bridge.isBatteryOptimizationIgnored === 'function') {
      battery = Boolean(bridge.isBatteryOptimizationIgnored());
    }
  } catch (e) {
    console.warn('Не удалось проверить оптимизацию батареи:', e);
  }

  const mark = (okSelector, badSelector, granted) => {
    const ok = $(okSelector);
    const bad = $(badSelector);
    if (ok) ok.hidden = !granted;
    // В браузере статус неизвестен: не показываем ошибку, которой там нет.
    if (bad) bad.hidden = granted || !bridge;
  };

  mark('#setup-notifications-ok', '#setup-notifications-bad', notifications);
  mark('#setup-battery-ok', '#setup-battery-bad', battery);

  const hint = getVendorNotificationHint();
  const title = $('#setup-autostart-title');
  const note = $('#setup-autostart-hint');
  const vendorNote = $('#setup-vendor-note');
  if (title) title.textContent = hint.title;
  if (note) note.textContent = 'Разрешает приложению запускаться после перезагрузки телефона и работать в фоне.';
  if (vendorNote) vendorNote.textContent = hint.note;

  return { notifications, battery };
}

function hasAcceptedTerms() {
  try { return localStorage.getItem(TERMS_ACCEPTED_KEY) === '1'; } catch (e) { return false; }
}

/* Режим «только просмотр»: условия можно перечитать из раздела «О приложении»,
   тогда кнопка «Не принимаю» скрыта, а основная кнопка просто закрывает окно. */
let termsViewOnly = false;

function openTermsDialog(viewOnly = false) {
  termsViewOnly = viewOnly;
  const dialog = $('#terms-dialog');
  if (!dialog) return;
  const declineBtn = $('#terms-decline');
  const acceptBtn = $('#terms-accept');
  const hint = dialog.querySelector('.app-dialog-hint');
  if (declineBtn) declineBtn.hidden = viewOnly;
  if (acceptBtn) acceptBtn.textContent = viewOnly ? 'Закрыть' : 'Понимаю и принимаю';
  if (hint) {
    hint.textContent = viewOnly
      ? 'Вы уже приняли эти условия. Если вы не согласны с ними, пожалуйста, прекратите использование приложения и удалите его с устройства.'
      : 'Нажатием «Понимаю и принимаю» вы подтверждаете ознакомление с условиями использования и лицензией FitFlow (полный текст лицензии — кнопка «📜 Читать лицензию полностью» выше, после входа — Настройки → О приложении → «📜 Лицензия»).';
  }
  dialog.hidden = false;
}

function maybeShowTerms() {
  if (hasAcceptedTerms()) return;
  openTermsDialog(false);
}

function acceptTerms() {
  if (!termsViewOnly) {
    try { localStorage.setItem(TERMS_ACCEPTED_KEY, '1'); } catch (e) { console.warn('Не удалось сохранить принятие условий:', e); }
  }
  termsViewOnly = false;
  const dialog = $('#terms-dialog');
  if (dialog) dialog.hidden = true;
  renderProfileBasics();
}

function declineTerms() {
  const terms = $('#terms-dialog');
  const blocked = $('#terms-blocked-dialog');
  if (terms) terms.hidden = true;
  if (blocked) blocked.hidden = false;
}

function closeApplicationAfterTermsDecline() {
  try {
    if (window.FitFlowExport && typeof window.FitFlowExport.closeApp === 'function') {
      window.FitFlowExport.closeApp();
      return;
    }
  } catch (e) {
    console.warn('Не удалось закрыть приложение:', e);
  }
  // В браузере окно нельзя гарантированно закрыть; условия останутся при следующем запуске.
  try { window.close(); } catch (e) { }
}

function openSourcesDialog() {
  const dialog = $('#sources-dialog');
  if (dialog) dialog.hidden = false;
}

function closeSourcesDialog() {
  const dialog = $('#sources-dialog');
  if (dialog) dialog.hidden = true;
}

/* 0.5.8: лицензия с вкладками (RU / EN / Сторонние библиотеки) без внешних ссылок */
function switchLicenseTab(tab) {
  const tabs = ['ru', 'en', 'third-party'];
  if (!tabs.includes(tab)) tab = 'ru';
  $$('#license-lang-tabs [data-license-tab]').forEach((btn) => {
    const active = btn.dataset.licenseTab === tab;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-selected', active ? 'true' : 'false');
  });
  tabs.forEach((t) => {
    const panel = $(`#license-panel-${t}`);
    if (panel) panel.hidden = t !== tab;
  });
}

function openLicenseDialog(tab = 'ru') {
  switchLicenseTab(typeof tab === 'string' && ['ru', 'en', 'third-party'].includes(tab) ? tab : 'ru');
  const dialog = $('#license-dialog');
  if (dialog) dialog.hidden = false;
}

function closeLicenseDialog() {
  const dialog = $('#license-dialog');
  if (dialog) dialog.hidden = true;
}

