  ['#day-plan-card', '#day-mood-card'].forEach((sel) => {
    $(sel)?.addEventListener('click', (e) => {
      const moodBtn = e.target.closest('[data-mood-inline]');
      if (moodBtn) { saveDayMood(Number(moodBtn.dataset.moodInline)); } // 0.4.15: смайл — 1 тап
      if (e.target.closest('[data-dayplan-toggle]')) toggleDayPlanCollapsed();
      if (e.target.closest('[data-sleep-open]')) openSleepCheckinDialog();
      // 💊 Мой курс (0.3.30): чип приёма — ручная отметка/снятие.
      // После отметки перепланируем напоминания: сегодняшний принятый
      // приём уже не должен тревожить.
      const doseBtn = e.target.closest('[data-course-dose]');
      if (doseBtn) {
        const [courseId, idxRaw] = String(doseBtn.dataset.courseDose || '').split(':');
        if (courseId && toggleCourseDose(courseId, Number(idxRaw))) {
          renderDayPlan();
          refreshCourseRemindersOnLaunch();
        }
      }
    });
  });
  // Быстрый переход по разделам Главной: плавная прокрутка к карточке.
  // 0.8.16: scrollIntoView + scroll-margin-top (задан в CSS через
  // --quicknav-scroll-margin, значение = quicknavStuckBottom − 4) — карточка
  // приземляется чуть ВЫШЕ порога подсветки, поэтому нажатый чип подсвечивается.
  const quicknavEl = $('#home-quicknav');
  quicknavEl?.addEventListener('click', (e) => {
    const chip = e.target.closest('[data-jump]');
    if (!chip) return;
    const target = document.getElementById(chip.dataset.jump);
    if (!target) return;
    // Сразу подсветить нажатый раздел — дальше подсветку поведёт прокрутка.
    $$('#home-quicknav [data-jump]').forEach((c) => c.classList.toggle('active', c === chip));
    // 0.9.1: пересчитать scroll-margin ПЕРЕД прокруткой. Высота шапки меняется
    // (индикатор сети, перенос строки, смена ориентации), а --quicknav-scroll-margin
    // до этого обновлялся только на resize — с устаревшим значением карточка
    // приземлялась не на порог и подсвечивался соседний чип.
    syncQuickNavTop();
    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    clearTimeout(quicknavEl._settleTimer);
    quicknavEl._settleTimer = setTimeout(updateHomeQuickNavActive, 700);
  });
  syncQuickNavTop();
  window.addEventListener('resize', syncQuickNavTop);
